/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250304-3","meetingId":"r07-c-budget","date":"2025年3月4日","dateIso":"2025-03-04","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ５時３９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"ゆきた副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問","question":"明日からは、いよいよ当初予算の査定、審査が始まりますけれども、無駄をなくすというところにあまり着目し過ぎてしまうと、新規事業を実施する際には視野を狭めてしまわないか、大変心配しています。無駄の削減というように、令和６年度の最終補正予算において、先ほどお話があった、積立てられた基金というものが、令和７年度の当初予算においてはどのように活かされているのか教えてください。","respondent":"加島財政課長","answer":"これらの基金を活用いたしまして、令和７年度予算案におきましては、ハード整備、それから学校改築推進経費に係る歳出を支えてまいりたいと考えております。予算編成上のあくまで一般論ですけれども、歳入と歳出というのは同額で組む必要があります。","voiceIndex":11,"id":"exchange-002"},{"speaker":"まつざわ委員","kind":"確認","question":"今の話で、積み立てた基金をしっかり正確に使っているということの確認が取れました。次に、庁舎整備基金の積立金２０億円余についてお聞きしたいと思います。基金も新たに積立てを行ったと認識しておりますが、改めてこの基金の増額の理由を教えてください。これに伴って庁舎整備全体の資金、また財源の構成というのはどうなっていくのか、お聞かせください。","respondent":"加島財政課長","answer":"そのうち、国・都の負担金を除きまして、５５３億円が区負担となります。区負担５５３億円のうち、起債により約４１３億円を調達いたします。それから、庁舎整備基金から約１４０億円を繰入れすることにより、区負担分の財源を確保してまいる計画です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問","question":"区債を組むというのは、将来にわたって、負担のバランスというのですか、負担の平準化というのですか、そういうものを図るという部分では意味があると考えます。今、起債の話が出ました。４１３億円。これは区の借入れですよね。区の借入れとなるため、私たち区民の中には心配に思われる方もいらっしゃると考えますが、返済計画等の概要といったことについて教えてください。","respondent":"加島財政課長","answer":"それぞれ、今現在、計画の中では、借入れにつきましては５年満期一括償還を予定しております。減債基金に計画的な積立てを行うことによって、元金の償還、将来の償還に対応してまいりたいと考えております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"まつざわ委員","kind":"確認","question":"区民に負担がかからないことの確認が取れました。新庁舎ですけれども、総事業費が７００億円余と聞いていますが、これは想定より上がったものではないでしょうか。しかし、そういったイレギュラーにはしっかり対応していただかないと、工事業者の方も大変困るというのがありますので、契約後にそういったイレギュラーな事案というものが発生した場合の契約変更の考え方を教えてください。","respondent":"小林新庁舎建設担当課長","answer":"区としましても、コスト削減策としまして、設計者や発注者の支援をいただいておりますコンストラクション・マネジャーらと広く検討を進めてきましたが、今回改めて見直しを行わせていただいて、予算として提案するものです。","voiceIndex":17,"id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"しっかり対応してくれるということを聞いて安心しました。本当に難しい工事になっていくのかと思いますけれども、しっかりフォローしてあげてほしいと思います。庁舎として求められる環境面、また防災面は、どのように考えているのでしょうか。新庁舎の設計の中で、区としてどのように工夫を考えているのか。他自治体の庁舎建設の事例と比較して、特に品川区ならではといった特徴があるのか、教えてください。","respondent":"小林新庁舎建設担当課長","answer":"２点目の、環境や防災面の対応ですが、これにつきましても、当初の段階から、現庁舎と比較してより向上させたものとして検討を進めているところですので、その考えには変わりはないところです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"まつざわ委員","kind":"意見","question":"そうですね。やはり駅から直結というのは、私もいろいろ調べましたが、なかなかない。これは品川区新庁舎の本当に強みだと思っています。これは大変期待が高まっていることであります。しかし一方で、補助２６号線、あそこが開発されてしまうと、補助２６号線を歩く人が少なくなるということが懸念されているかと思っています。庁舎跡地の活用検討をどのように考えているのかお聞かせください。","respondent":"泉広町事業調整担当課長","answer":"周辺地区との連携というお話が今ございましたけれども、こちらは、令和２年に策定いたしました大井町駅周辺のまちづくり方針、また今年度の６月まで開催してまいりました、跡地の活用検討委員会の検討の結果を踏まえながら。","voiceIndex":21,"id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問","question":"広町が品川区の中心になりますように、また品川区の象徴となる庁舎建設が、妥協を一切許さない、しっかりした施設になるように願いまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"４９ページ、在宅子育て支援事業、８１ページ、八潮在宅子育て支援施設の整備、４３ページ・４９ページ、病児・病後児保育委託、８５ページ、病児保育新規開設運営補助経費、４９ページ・８３ページ、ベビーシッター利用支援事業費から、関連して伺ってまいります。初めに、４９ページ・８１ページに記載されております予算額が、ともにマイナス補正となっておりますので、この内容をお知らせください。","respondent":"藤村子ども育成課長","answer":"マイナス補正の金額につきましては、工事契約の落差額分という形になっております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"子育て支援施設、待望の八潮地域での開設となります。これまで私は、高齢者が多く住まわれている都営住宅の１階に開設されるということで、多世代交流の観点から、住民との交流が持てることを要望してまいりました。ぜひこの事業を活用して、東京都と連携を取っていただきながら、キッチンカーの誘致をぜひしていただけたらと考えていますが、見解を伺います。","respondent":"藤村子ども育成課長","answer":"委員のご説明のとおり、今回の八潮の子育て支援施設におきましては、キッチン機能の整備はございませんが、飲食など、多世代交流という観点も踏まえて運営していきたいと考えております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひよろしくお願いします。地元の地域の人も、キッチンカーの誘致というのは大変期待しているところでありますので、もし何かそういう声が上がっているようでありましたら声をここでお聞かせいただきたいのですが、いかがでしょうか。","respondent":"今井八潮まちづくり担当課長","answer":"委員よりご紹介いただきましたとおり、今年の１月に東京都と覚書を締結いたしまして、品川区として都営住宅における買物弱者支援事業ということで実施させていただいているところです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮の中にはコインパーキングもありますので、施設を案内する際にはぜひ、この施設だけではなく八潮地域周辺もアピールしていただきながら、多くの方を施設へと誘導していただきたいと思いますが、見解を伺います。そしてまた、品川総合福祉センターと連携していただきながら、施設内でのプチレーブのパンの販売もぜひご検討いただきたいと思いますが、見解を伺います。","respondent":"藤村子ども育成課長","answer":"プチレーブと連携した施設内でのパンの販売といった、福祉施設との連携というところも、しっかり検討してまいりたいと思います。","voiceIndex":31,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、病児保育についてお伺いいたします。昨年の予算特別委員会でも取り上げました。現在、病児保育の施設が区内に３か所ということで、限られた地域での展開となっております。今後、区においては、ベビーシッターを優先していくお考えなのか、また病児保育をしっかりと広げていくお考えなのか、改めてお伺いしたいと思います。","respondent":"中島保育施設運営課長","answer":"病児保育施設につきましては、昨年の９月に説明会を開催いたしました。今、具体的には、３施設と新規開設に向けて協議しています。","voiceIndex":33,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"確実に３件増やしていただくこと、また、区民が利用しやすい体制を整えていただきたいことを要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、品川区各会計補正予算書の４３ページの０歳児見守り・子育てサポート事業について、そして８３ページのベビーシッター利用支援事業について、順不同で質問いたします。最初に、ベビーシッター利用支援事業についてお伺いいたします。今回の最終補正予算において１億１２９万２,０００円の増額となっておりますが、令和６年度当初予算の考え方として想定の人数と金額についてお伺いいたします。","respondent":"芝野保育入園調整課長","answer":"令和６年度当初予算につきましては、令和５年度前半の実績に基づいて、２,３５０人程度の利用を想定し、予算額を約２億６,０００万円としておりましたが、事業周知が進んだことにより、当初の想定を上回る２,６８０人、３億６,０００万円程度の利用が見込まれることなどから。","voiceIndex":37,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問","question":"すごく需要の高まりを感じております。具体的にどのような方が利用しているのか、利用時間帯など、分かる範囲で教えてください。","respondent":"芝野保育入園調整課長","answer":"保護者のリフレッシュや、お子さんの病院の通院など、日常生活上の突発的な事情による一時的利用というのが多いものと認識しております。","voiceIndex":39,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今の社会が直面する少子化問題、また共働き世帯の増加に伴って、育児に対する不安や負担を軽減するためにも、このような支援が今後ますます求められていると考えています。現在、児童１人につきひと年度当たり１４４時間、東京都の登録している事業者のみでこの助成が利用されていると認識しておりますが、東京都のベビーシッター登録制度について、登録団体とその方法についてお聞かせください。","respondent":"芝野保育入園調整課長","answer":"登録に際しましては、都が定める認定基準というものを満たす必要がありますので、施設の要件として法人登記を行っていることが定められております。したがいまして、現状、個人としての登録は今できない形となっています。","voiceIndex":41,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"意見","question":"保育の基準が、児童１人に対しベビーシッター１人による保育であることとあり、双子などの場合には２人のベビーシッターを手配する必要があるなど、利用しづらいというようなご意見もいただいておりますが、実際に現場の声としてどのような声が届いているのかお聞かせください。この需要の高まりに対する対応策、利用者目線の改善も今後必要だと思いますが、区の見解もお聞かせください。","respondent":"芝野保育入園調整課長","answer":"意見交換の場というのがかなりありまして、そちらを通じて声を聞いているような状況で、人材育成等の研修というものも実施しているです。こちらも東京都の動きを注視させていただきまして、よりベビーシッター事業を推進していけるように、区としても対応していきたいと思います。","voiceIndex":43,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何か東京都の要件が緩和される、また団体だけではなくて個人の方でも、幾つか研修を受けた上でしっかりと対応が保証されるということが確認できたら利用できるというような仕組みづくりを、ぜひ区としても都に伝えていってほしいと考えています。利用率の向上、また利用につながっていない方の分析を行い、誰一人取り残さない子育て支援の要望をしておりますが、現在の進捗状況などについてお聞かせください。","respondent":"石橋品川保健センター所長","answer":"本年度の途中に、国での運用が変更され、国庫補助金の補助額が減少されると通知がありました。そのため、減額の補正をしたものとなります。今回の事業は一部減額補正ということにはなりましたが、しっかりと計画どおり適切に実施してまいりたいと思います。","voiceIndex":45,"id":"exchange-019"},{"speaker":"ひがし委員","kind":"確認","question":"国の補助金が少し減額になっているので心配していたところなのですけれども、今ご答弁の中で、しっかりと実施していくということが確認できました。区の負担も少し増えたのかとは認識しておりますが、今後もしっかりとこの事業を進めていただき、誰一人取り残さない子育て支援を行っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"９７ページ、小山三丁目第２地区再開発事業補助金について伺います。こちらは、武蔵小山駅前のアーケードをまたぐ地域に４１階建てビル２棟を建てる計画です。７億７,７６０万円の皆減ですが、まずこの地区の想定事業費と補助金投入総額は幾らなのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"想定事業費および補助金の金額ですが、今現在、この地区におきましては、地域の方々で今そういったまちづくりを検討している最中というところで、総事業費または補助金といったところは今現在、検討中というところで聞いております。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"こちらは都市計画決定もされておりまして、この時点で想定事業費も補助金総額も答弁しないというのはおかしいと私は思うのですけれども、もう一回お伺いします。","respondent":"中道都市開発課長","answer":"事業費につきましては、今現在、準備組合の総会等の中で様々議論されているという状況です。区にはまだ正式な報告というのは届いていないという状況です。","voiceIndex":51,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"正式な報告が届いていないと、何をもって言っているかは分かりませんけれども、準備組合の書類を見ますと、補助金総額は２３７億４,０００万円と伺っています。７億７,７６０万について、皆減した理由を伺います。予算説明書の節の区分の欄に、「補償、補填及び賠償金」と書かれているのですが、これはどういう意味なのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"補助金の皆減の理由ですが、令和６年度当初予算におきましては、小山三丁目第２地区の準備組合とヒアリングを行いまして、今年度、市街地再開発組合が設立し、建築設計または権利変換といった形を実施する回答のあったことから予算計上を行ったものですが。","voiceIndex":53,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり無理があるのです。現在、認可申請を狙って、狙っているのでしょう。伺いたいのですけれども、小山三丁目第１・第２地区でも従前評価というのは行われたのか、改めて伺います。それが行われた上で、こちらの２地区というのは都市計画手続に入って、手続に入っていいと言ったのは、手続に入るのは区ですけれども、都市計画決定が行われたのか確認させてください。","respondent":"中道都市開発課長","answer":"都市計画決定後におきましても、その時代に合った権利変換といったものを概算でお示ししながら、皆様、地域の方々が今後進めるか進めないか、またはどのようにまちづくりの将来像を担っていくのかといったところを検討しているという形で進んでいるです。","voiceIndex":55,"id":"exchange-024"},{"speaker":"安藤委員","kind":"確認","question":"分かりました。それで、小山三丁目第１・第２地区でも従前評価が行われて、それが行われた上で、これらの２地区というのは都市計画手続に入って、都市計画決定もされたということなのかということを聞いたので、確認させてください。","respondent":"中道都市開発課長","answer":"準備組合から、そういった形で、小山三丁目第１地区、第２地区ともに、モデル的な権利変換というのをご提示しながら進んでいるということは聞いてあります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"だから、担保がなく決定権もない、任意団体である準備組合が、当時の説明で行った価格と今の説明がかなり大きくずれているということで、組合認可申請にも至れないというのが今の段階だということだと思います。都市計画決定をした行政として、これは見直す、廃止すべき、というのも１つの選択肢に入ってくるのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"都市計画事業についてのご質問です。市街地再開発事業は、地区内の方々でまちづくりの将来像を検討しながら、進める・進めない、またはどのような形で課題を整理していくかというようなところを検討している事業となります。","voiceIndex":59,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３６ページ、特別区民税、特別区たばこ税、３８ページ、特別区財政調整交付金、地方特例交付金など、歳入全般についてお伺いいたします。６９ページの区民保養所経費、９７ページ、武蔵小山駅周辺地区再開発事業についてお伺いいたします。特別区民税等々からお伺いいたしますけれども、特別区民税は今回、増えている。財政調整交付金も増えております。","respondent":"吉野税務課長、加島財政課長","answer":"特別区民税なのですけれども、普通徴収税に関しましては、納税義務者が、当初の見込みが８万６,０００人だったところが８万８,０００人と。特別区財政調整交付金ですけれども、こちらの伸びにつきましては、今回、調整税３税の伸びが大きかったところです。特別区たばこ税なのですけれども、こちらは実績見合いで減収という形になっております。","voiceIndex":62,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。地方特例交付金の実績に基づいて減というところを、もう少し詳しくお聞かせください。結局、区民税は納税者が増えていっているということと、特別区財政調整交付金も増えたということは、それなりに税収が増えていると。これがあと何年続くのか。ただ、一方で人口減少という問題がありますので、大体どの程度で頭打ちが来るのかということは、お分かりになるでしょうか。お知らせください。","respondent":"吉野税務課長、加島財政課長","answer":"転入の数も増えてはいるのですけれども、実際の納税義務者の部分、３０代・４０代の部分が減っておりますが、ただ、いわゆる課税標準額でいきますと、こちらが増えて。今、総合実施計画を策定しておりますが、総務委員会にてご報告させていただいた中では２０５１年が人口のピークとなりますので、そこのところが１つのターニングポイントになってくるかと考えております。","voiceIndex":66,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"そうですね。２０５１年が人口のピークということで、それまでは、やはり増加の傾向が続くのかと思います。では、比較的健全な財政状況、ある程度、余裕のある運営ができるのかと思いますけれども、その辺りのご所見をお伺いいたします。","respondent":"加島財政課長","answer":"２０５１年までは、こういったものの都区財政調整や区民税の伸びというのが一定程度見込めますけれども、２０５１年以降、人口ピークを迎えた後につきましては、少子化と高齢化が同時進行してまいりますので。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。健全な財政を、引き続きどうぞよろしくお願いします。続いて区民保養所について伺いますけれども、今回、７７７万円ほど減になっておりますけれども、その理由をお知らせください。","respondent":"宮澤地域活動課長","answer":"今年度、伊東市にあります品川荘につきまして、空調設備の老朽化に伴いまして更新工事を実施したところです。工事の影響によりまして、９月から１月まで休館対応したことによりまして、宿泊助成の実績が減った部分を減額補正しているものです。","voiceIndex":71,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"この件は、それで承知いたしました。ただ一方、この間、築年数も経っているかと思います。３０年程度経っているかと思いますけれども、かなり老朽化も進んできているかと考えていますし、また、事務事業評価を見ますと、稼働率が少し落ちているのかと思います。保養所を運営するにあたり、課題というのは何かお考えがありますでしょうか。","respondent":"宮澤地域活動課長","answer":"委員がご指摘のとおり、品川荘、光林荘ともに、３０年近くの築年数が経ってきているところで、老朽化が進んでいるです。今後、老朽化に伴う更新工事等が必要な時期というのは来ておりますので、そういったところを実施していくのかというところが課題となっているところです。","voiceIndex":73,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"むしろ、品川区内の行政需要に応える事業に集中すべきかと考えております。これは私は１期目から申しておるところですけれども、ついに事務事業評価でもＣ評価がつきました。そして、事務事業評価にありますとおり、保養所の在り方検討会議を開催し、令和１０年度以降の保養所の方向性について検討するとありますけれども、今、この検討会議についてどのような議論になっているのかお知らせください。","respondent":"宮澤地域活動課長","answer":"先ほどのとおり、老朽化も進んでおります。ただ日光にあります光林荘につきましては校外学習施設ということで、子どもたちが校外学習で利用しているという現状もあります。今後の方向性につきましては、引き続き検討を進めていくです。","voiceIndex":75,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"今現在、民間貸付けによって運営されていると思うのですけれども、貸付期間が令和１０年３月３１日までということで、残りの期間も少ないのかと考えています。続いて、武蔵小山駅周辺地区再開発事業に移りますけれども、７億７,８００万円程度の減の理由。これは、都市開発法の３分の２以上の同意が得られなかったという理由でよろしいのでしょうか。","respondent":"中道都市開発課長","answer":"今現在、地域の方々が、まちづくりの議論を交わしている最中というところで、まだまだそういったまちづくりを進めるといった形での様々な同意に至っていないということについて、準備組合の報告がございましたので、今回、予算を皆減したです。","voiceIndex":77,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"今、本当に港区では、無理やり分筆して分母を増やして、同意を強引に取りに行くというようなことも起きているとも聞いておりますけれども、今後、不動産価格高騰について、なかなか再開発の同意が得にくくなるという事象が増えてくると思うのですけれども、その辺りはいかがお考えなのでしょうか。","respondent":"中道都市開発課長","answer":"今後の再開発ですが、やはりそこにつきましても、地域の方々に今後どのようなまちにしていくのかというところを考えていただきながら、また、区としてもいただいたご不安な点などに、丁寧に対応していきたいと考えています。","voiceIndex":79,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"私からは、８３ページのベビーシッター利用支援事業、８５ページ、病児保育新規開設運営補助経費について質問します。今後については、今、３施設、開設へ向けて協議をしていらっしゃると先ほどお聞きしました。病児保育のニーズもあるとご答弁がありました。今年度の受入れ可能数と病児保育利用者数を、前年と比較してお聞かせいただけますでしょうか。","respondent":"中島保育施設運営課長","answer":"今年度につきましては３施設でございまして、定員が合計１７名、年間の受入れ可能人数が４,０８０人です。実績としましては、１月末現在の数字ですが、１,１１７人という実績です。","voiceIndex":82,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"ベビーシッターについて続いてお聞きしたいのですけれども、こちらも大変ニーズがあり、当初予算よりも大幅に、１億円を超える予算を追加しているということになります。区としては、シッターの病児受入れについては、どのようにお感じになっていらっしゃいますでしょうか。","respondent":"芝野保育入園調整課長","answer":"東京都から令和７年度予算の中で、突発的な病気などで保育園に預け入れが難しい未就園児に対して、都から認定を受けたベビーシッター事業者を利用した場合、その利用料の一部を助成するという、ベビーシッターを利用した病児保育に係る検証事業を実施すると示されておりますので。","voiceIndex":84,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"子どもの発熱や体調不良で保育施設に通えない場合は、病児保育に加えてベビーシッターを利用するという選択肢が今あるとは思っておりますので、確認させていただきました。保育施設から病児保育の送迎をしている自治体がありまして、隣の大田区なのですけれども、病児保育送迎事業として、今、試行実施をしていることを確認しました。これについて、品川区の見解をお聞かせください。","respondent":"中島保育施設運営課長","answer":"つきましては、運用方法や、例えばお迎えに行く体制など課題もあると思いますが、現状の病児保育施設のご意見や、先行の自治体の事例などもお聞きしながら、検討してまいりたいと思います。","voiceIndex":86,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"ベビーシッターの需要が高まり、まず予定の合う方を１人探すことが精いっぱいで、さらに児童１人に対してベビーシッター１人による保育であることという条件が多子世帯の方にとって高いハードルになります。ベビーシッターの中には、同時保育できる人数を明記している事業者もありますので、一対一の保育という部分を使いやすくしていただきたいと、以前、私も仲間たちと都へ要望したことがあります。","respondent":"芝野保育入園調整課長","answer":"ベビーシッター、多子世帯の利用状況ですが、正確な数字は分かりかねるところではあるのですが、令和５年度の実績が、１,８３０人中、大体６００世帯程度、ご兄弟がいる方がご利用されているというような、ざっくりとしたデータですが、当課で把握しています。","voiceIndex":88,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"私からは、６６ページ、人事管理費、１０３ページ、品川図書館職員給与費についてお伺いいたします。１点目に、品川図書館職員給与費についてお伺いいたします。補正の内容をご説明ください。","respondent":"宮尾人事課長","answer":"と申しますのは、職員給与費につきましては基本的に、当初予算では前年度１０月１日現在の現員現給の数字を使わせていただいておりますので、その関係で職員数の変動が生じることに対応するもの、それからもう一点が、人事委員会の勧告に伴う給与改定に対応するもの。","voiceIndex":92,"id":"exchange-039"},{"speaker":"横山委員","kind":"提案","question":"ご説明ありがとうございました。理解いたしました。知識と情報の差を、情報はノイズの除去された知識のことを指すとしています。文部科学省の、公共図書館の運営基準の見直しで示されている議論のポイントも大事な論点ですが、読書離れの根本である、なぜ本が読めなくなってきているのかという背景を押さえながら、新しい子ども読書推進計画を進めていただきたいと考えますが、区のお考えをお聞かせください。","respondent":"河内品川図書館長","answer":"私からは、まず背景からご説明申し上げます。背景ですが、当該計画におきまして、区民の方へアンケートを実施しております。区立学校の５年生と８年生にアンケートを実施いたしました。","voiceIndex":94,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"職員、教職員の皆さんが、日々お仕事を常に全身全霊で頑張っていては疲れ果ててしまいますから、働きながら本が読める区役所ではないですけれども、人によって、それは読書ではなくて、ご家族との時間かもしれませんし、休息や趣味、推し活などかもしれませんが、今後も引き続き１４日以上の割合を増やすなど、年次有給休暇の取得促進を進めていただきたいと要望いたしますが、いかがでしょうか。","respondent":"宮尾人事課長","answer":"委員から今お話のありましたように、良質な区民サービスを提供するために、職員の健康管理、健康であることというのはもう大前提のことかと思います。今後も、休暇の計画的な取得を含め、職員の働きやすい環境づくりに努めてまいりたいと思います。","voiceIndex":96,"id":"exchange-041"},{"speaker":"横山委員","kind":"意見","question":"ウェルビーイング、真剣にやることと、真面目にやることと、楽しくやることというのも、私は実現できると思っておりまして、楽しいというのも人によって感じ方が違うかと思いますし、また、お休みやリフレッシュの取り方というものも人によって違うかと思いますので、それぞれの職員の、何というのでしょう、自己実現やリフレッシュなどの時間、大切なものを大切にしていただくということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-042"},{"speaker":"こしば委員","kind":"確認","question":"私からは、９５ページ、下水道管改修事業についてお伺いいたします。先月の１月２８日に発生しました埼玉県八潮市の道路陥没事故、トラックの運転手が巻き添えとなりまして、いまだに行方不明のままです。答弁は、空洞調査や、ＡＩを活用した路面点検の結果を再確認し、異常がないことを確認したとの答弁であったと認識しております。このマイナス補正となりました理由について教えていただければと思います。","respondent":"北原河川下水道課長","answer":"減額補正の理由につきましては、工事を実施するに当たりまして、下水道局が実施する下水道管の調査に基づき設計検討を行った結果、健全である既設の管渠をそのまま活用できるなど、予算時に想定したより安く工事が発注可能となった等の理由により。","voiceIndex":100,"id":"exchange-043"},{"speaker":"こしば委員","kind":"確認","question":"調査により健全性を確認できたということを理解いたしました。そうなりますと、点検により健全性が確認された下水管というのは、そうはいいましても、今後、必要な期間を経て点検が必要になってくると思いますし、また八潮市の陥没の事故を受けまして、点検の頻度を上げていくことも必要ではないかと思いますが、お答えをお願いいたします。","respondent":"北原河川下水道課長","answer":"下水道管の管理・点検については、東京都下水道局で実施しているものでございまして、日頃から巡視・点検を行うとともに、腐食するおそれが高い下水道管については５年に１度、それ以外の管については３０年に１度など定期的に調査を行って。","voiceIndex":102,"id":"exchange-044"},{"speaker":"こしば委員","kind":"質問・要望","question":"やはり、都下水道局が主体となる。その一部を品川区が受託しているですが、やはり東京都との連携が必要不可欠になってくるわけです。今、品川区で、八潮市の事故もありましたけれども、東京都に対しまして下水道事業の拡充等を要望していると思うのですが、その中身について、東京都に要望していることについて教えていただければと思います。","respondent":"北原河川下水道課長","answer":"東京都への要望についてですけれども、２３区では品川区長が会長となりまして、特別区下水道事業促進連絡会というものを組織しておりまして、浸水対策の実施、老朽化対策の整備促進、耐震化の促進など、要望を都知事宛てに行っている状況になります。","voiceIndex":104,"id":"exchange-045"},{"speaker":"こしば委員","kind":"質問・要望","question":"一方で、点検の上、補修工事が必要になってしまう場合のことについてもお聞きしたいと思います。品川区の下水道管の老朽化が大分進んできているところですが、補強工事の進捗、品川区の状況について教えていただきたいのと、また今後の見通しについても併せて教えていただければと思います。","respondent":"北原河川下水道課長","answer":"品川区で一部を受託して進めております老朽化対策工事についてですが、現在は、老朽化が特に進んでおります目黒川の左岸側のエリアを中心に事業を進めておりまして、品川区の多くのエリアを占める右岸側の広いエリアについては、それ以降に実施するエリアで。","voiceIndex":106,"id":"exchange-046"},{"speaker":"こしば委員","kind":"質問・要望","question":"今後の見通しということについてもお答えいただきました。そういったことで、やはり今、品川区、都下水道局が取組を行ってきておりましたけれども、区民の安心のレベルというものを上げていくためにも、ぜひその辺の報告といいますか、周知ということを、広報しながわなどありますけれども、そういった媒体を使ってぜひ進めていただきたいと思いますが、見解を教えていただきたいと思います。","respondent":"北原河川下水道課長","answer":"本事業につきましては、下水道局が進めている事業ということもありますので、今の段階で何ができるかというのはお答えしづらいところもありますが、例えば道路課でやっている空洞調査の状況等も含め。","voiceIndex":108,"id":"exchange-047"},{"speaker":"こしば委員","kind":"質問","question":"その辺り、私道整備というのは、大原則が民間の民有地なので民間に頼むものではありますけれども、ぜひ区にできること、例えば補助金、また点検であれば点検のやり方といったものをレクチャーしていくような試みも必要だと思いますが、時間が、もし答弁できましたらお願いします。","respondent":"森建築課長","answer":"私道整備助成の中で、下水道管を直すこともできます。","voiceIndex":110,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"３６ページ、特別区民税、６７ページ、庁舎管理費、５５ページ、公立学校給食費負担軽減事業補助金、１０５ページ、学校給食無償化について伺っていきたいと思います。そのうち、届出がなくて都の歳入になったのが６億６,０００万円と聞きました。その中で、品川区の平均世帯所得が分かれば教えていただきたいのと、転入人口ではどういう世代、またどういう所得層の方々が増えてきているのか教えてください。","respondent":"吉野税務課長、崎村企画課長","answer":"実際には、１,０００万円以上の方たちがかなり増えておりまして、前年と比較しますと３０代ですと１,０００人、４０代、４９歳ですと７００人といった形で、大分増えているところです。人口動態の特徴というところで少し補足しますと、品川区は今、人口が増加傾向にあるというところで、その多くが単身者の転入となっております。中でも、２０歳から２９歳の単身者の転入が圧倒的に多いという状況です。","voiceIndex":113,"id":"exchange-049"},{"speaker":"つる委員","kind":"提案","question":"もう一つは、単身者、単身世帯のベーシックサービスの展開を今後どうしていくのかというところでは、これは非常に大きな課題で、国で本来はというところは当然あるわけですけれども、先行して事例を示していく品川区として、先ほどありましたけれども、２０代から２９歳のいわゆる若者や単身者、単身のみ世帯といったところのベーシックサービスの展開というのは。","respondent":"崎村企画課長","answer":"こういった世帯に対して何を行っていくのかというところかと思いますけれども、単身世帯については、今後検討をしていかなければいけない部分かとは思いますけれども、ファミリー世帯については、転出をなるべくしていただかずに。","voiceIndex":116,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"大枠でありがとうございました。ただ、生まれ育った方々が、ある一定の年代となると、出ざるを得ない状況になるというのは、やはり対応していかなくてはいけないことなのかなとは思いますので、また別の場所でも伺っていきたいと思います。次に、庁舎管理費に関連してなのですが、エレベーターの保守に関連して伺いたいと思います。改めて、その権限の根拠や、金額の根拠についても教えてください。","respondent":"佐藤経理課長","answer":"エレベーターの保守に関しましては、委員のご指摘のとおり、大きい事故があったという経緯も踏まえまして、メーカーに関係するメンテナンス会社を主としまして契約を進めておるところです。長期的・継続的な保守が求められるというところで、随意契約で結んでおります。","voiceIndex":118,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"今のところなのですが、金額については、幾らまでが随意契約で、所管課長の権限なのか。別表第１の（１９）の、昇降機等の保守についてというところであると思います。金額については、幾らまで随意契約でいけるのか教えてください。","respondent":"佐藤経理課長","answer":"課長への権限の移譲の部分ですけれども、エレベーターの保守に関しましては、金額ではなくて契約内容に基づいて課長に権限を移譲しているという形です。","voiceIndex":122,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"分かりました。これは民間企業ですから、あると思うのですが、その上で、独立系を活用したときには、それだけの保守点検の削減効果があるというところも、随意契約といえども、そのメーカーの関連するメンテナンス会社ともしっかりと交渉して、少しでも経費を削減していく努力というのは各課長等もできるのではないかと思いますが、最後、時間がないですが、ご提言いただければと思います。","respondent":"佐藤経理課長","answer":"繰り返しになりますけれども、エレベーターに関しては非常に安全性が強く求められる設備だと思いますので、今後とも安全をまず第一に考えて、契約形態については考えていきたいと思います。","voiceIndex":124,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"私からは、６４ページ、総務費、デジタル推進費から、ガバメントクラウドについてお聞きいたします。品川区のガバメントクラウドの事業者、また移行の進捗と、既に移行した事業部署の状況、今後のスケジュールについてお伺いします。品川区は令和５年度からガバメントクラウドの早期移行団体検証事業公募に参加しておりましたが、他自治体に比べて早く進んでいるのか、併せてお聞きします。","respondent":"横田デジタル推進課長","answer":"令和６年度の標準化といたしまして、住民基本台帳、印鑑、国民健康保険、年金、選挙人名簿管理をガバメントクラウドに移行しております。品川区におきましては、早期移行団体として、この５事業につきまして、国と協力しながら検証しています。","voiceIndex":127,"id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問","question":"ありがとうございました。今、移行後の事業は特に問題なく進められているということでよろしいでしょうか。","respondent":"横田デジタル推進課長","answer":"こちらも、早期移行した５事業につきましては、特に問題なく現在、稼働しております。","voiceIndex":129,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"クラウドの事業者はどちらでしょうか。","respondent":"横田デジタル推進課長","answer":"失礼いたしました。全事業、ＡＷＳを予定しております。","voiceIndex":131,"id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区はＡＷＳということで、アマゾンということを確認いたしました。現状、アマゾンが９０％以上を占め、残りはアメリカの３社がほかの自治体でも選択されているということで、海外企業のクラウドを使うということは、そこで少しリスクもありますので、ちょっとお聞きしたいと思います。アマゾンはアメリカの企業であり、アメリカの法律によってアメリカ政府がデータへのアクセスを求める可能性があります。","respondent":"横田デジタル推進課長","answer":"日本企業が育っていないのではないかですが、政府の令和５年度の調達仕様書におきまして、まだＩＳＭＡＰ等の基準やガバメントクラウド基準を満たしていない場合でも、令和７年度中までに参加できるような条件を満たすのであれば。","voiceIndex":133,"id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問","question":"ご説明ありがとうございました。最後に、国内企業の育成についてお伺いいたします。政府としては、完全に海外クラウドに依存するのではなく、国外企業の成長も支援しながら、実現的に海外クラウドと併用するといった方針を取っております。品川区では、五反田バレーをＩＴ企業の中心地として掲げております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、４９ページのベビーシッター利用支援事業、それから４３ページの０歳児見守り・子育てサポート事業、それから６７ページ、情報公開等経費について伺います。１つはベビーシッターです。その点について、今後、制度を何とか使えるようにしていただける方向だといいと思うのですけれども、検討されているのかどうか、その点について伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"マッチング、相性のところですが、東京都の制度は、マッチングには対応しておりませんので、事業者に登録、利用の申込みをして、利用者のほうでその方に合うような方を派遣するという形になっていますため、今の段階ではマッチングには対応はしていないという状況であります。","voiceIndex":138,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望にとどめます。もう一つが、０歳児見守りについてです。今度、登録はそこまで進んだということで、登録された方は１００％使っておられるのか、それともその中でも使っていない方がおられるのか、その辺についての分析はどうされているのか、伺いたいと思います。配るの人の人数というのは足りているのでしょうか。それから、前に質問したときは、しっかり研修をしていると伺っております。","respondent":"石橋品川保健センター所長","answer":"いろいろ支援が必要なご家庭や、保健センターと連携の必要なご家庭等についての研修というのは、区としっかりと情報連携をしておりまして、支援員の方も訪問後、支援員同士での情報共有等も毎回行っていただいているというのを聞いておりますので、そういったことも含めて。","voiceIndex":140,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。いい制度にだんだん育っていっているということが確認できました。それで、適切な支援につながっているということであれば、それから支援を受ける方からの評価のお声というのは、今のところ、どうでしょうか。","respondent":"石橋品川保健センター所長","answer":"お声としましては、先ほどもお話をさせていただいたとおり、支援員の方が一人も今、辞めておられないということもありますので、同じ方が定期的に毎月訪問できているという形で、気軽な気持ちで相談できるということと、前回相談したことをきちんと記録で残しておりますので。","voiceIndex":142,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、１つだけ申し上げておきたいのは、よくお分かりなので言わずもがなかもしれませんけれども、やはり当初の、これは物を配るのが目的ではなくて、支援につなげることが目的だという、そこだけはぜひ押さえておいていただきたいということを要望しておきます。これは要望です。もし何かお考えがあったら伺いたいと思います。これはどう考えても理不尽だと思うのですけれども、見解を伺います。","respondent":"與那嶺戦略広報課長","answer":"委員がおっしゃるとおり、こちらの件について大変時間がかかっているというところについては、確かにそのとおりというところもありますけれども、所管を通じまして、こちらの公開箇所については再度整理していますので、完了次第。","voiceIndex":144,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ期限を切っていただきたいと思います。「どれくらいには出ます」など、大体でもいいです。それは、普通の社会人の生活として、それが普通かと思うのですけれども、それがないということについては、これは経費がどれぐらいかかるか分かりませんけれども、減額している場合ではなくて、ぜひ、しっかりこの制度をつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"與那嶺戦略広報課長","answer":"実際に各手続について期間を定めるかというところにつきましては、様々制度を運用している他自治体等も含めて、こちらも研究していくべきところかと思ってありますので、こちらについては今後の研究課題とします。","voiceIndex":146,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、きっちり、こちらは大体４０日以内とか、それを言われますので。それで、私たちが最終的に求めているのは、期限を切って、書面が出せなかったら、その時点で公開決定としてほしいと思います。それが嫌だったらと言うのも変ですけれども、公開が理不尽だと思うのであれば、しっかりその期日までに弁明書なり再弁明書なりを出していただきたいと思うのですけれども、その辺についていかがでしょう。","respondent":"與那嶺戦略広報課長","answer":"期間の中で、過ぎてしまった場合は原則公開としてほしいというご意見ではあったのですけれども、情報公開における公開に当たっては、条例に定めてあるとおり、基本的には原則として公開としながらも、公開できない情報というところを個別に定めているところです。","voiceIndex":148,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"出さない、公開できない理由があるとおっしゃっているわけですよね。だから、そこが平等でないというのは制度の問題で、公開すべき内容かどうかということと違うのではないですか。期日を守って出しています。非公開の理由があるのだったら、期日も守るべきではないですか。この文書のやり取りも、そちらも緊張感を持っていただきたいという、それだけのことなのですけれども、いかがでしょう。","respondent":"與那嶺戦略広報課長","answer":"ただ、こちらについて、繰り返しになってしまいますけれども、現状、法令等において定めがないところでもありますので、こちらについては、今後どのように制度を運用していくかというところについては。","voiceIndex":150,"id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ以上はもう繰り返しになりますね。それで、１つ、申し上げたいのは、それぞれの所管が今、情報公開の手続をしているのです。どの所管の情報公開についても、戦略広報課ではなくて、別立てで窓口をつくっていただいてもいいのですけれども、それを専門とする窓口があると、私以外にも、情報公開請求をする方たちもそれを求めておられます。","respondent":"與那嶺戦略広報課長","answer":"窓口の件に関してですけれども、現状、各所管で情報公開請求を受け付けているところもありまして、それぞれの部署で受けているところです。一方……。","voiceIndex":152,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１０５ページの補助教材費保護者負担軽減事業、８３ページの区立保育園費の育児休業代替等人材派遣について伺います。補助教材費、いわゆる学用品無償化についてです。義務教育の無償化に踏み出したことは、よかったと思います。今回、補正で１,０００万円、減額となっている理由を伺います。","respondent":"柏木学務課長","answer":"補助教材費保護者負担軽減事業の減額の理由ですが、こちらは、当初予算では、各学校・各学年の補助教材費の最高額で予算を計上しています。実際、今年度、執行してまいりまして、上限までいかない学校が当然多くあったという部分で、今回、減額補正をしています。","voiceIndex":155,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"区民から声が寄せられていまして、学用品が無償になったのにリコーダーのお金を請求されたとか、分度器のお金を払ったとか、また別の学校では無償だったのに、うちの学校では請求されたという声などが寄せられています。こうした声が上がる理由を伺いたいと思います。学校の裁量はあるとは思うのですけれども、学校によって差が生まれているという現状の改善が必要ではないでしょうか。伺います。","respondent":"柏木学務課長","answer":"それと、今後の改善の件ですが、実施して１年がたちまして、各学校からも意見等いただいていることですので、来年度につきましては、現在、学校の意見も聞きながら検討しています。","voiceIndex":157,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"保育園の育休代替についてです。補正において１億２,０００万円余を増額したということで、その理由と派遣人数は何人なのかを伺います。それで、今年度、育休・産休を取った人数と、病休を取った人数、それぞれの全保育士に対する割合を伺います。","respondent":"中島保育施設運営課長、宮尾人事課長","answer":"現状、育休代替と育児短時間勤務、部分休業のカバーを含めまして、１０３人を見込んでいるところです。現時点で育休を取っている保育士は９３名いるところです。すみません。病気休暇に関しましては全体の数字になってしまうのですが、２月の時点で、職員全体でですが、１２２名です。","voiceIndex":159,"id":"exchange-069"},{"speaker":"のだて委員","kind":"質問","question":"派遣が１０３人で、育休・産休が９３人、今年度取っていらっしゃるということで、現場のお話を聞くと、園の中で４人から５人いるということで、その半分が大体、派遣ではないかという実感のようですけれども、これだけいる中で産休・育休が９３人いるということで、これは実際に補充できているのかどうか、伺いたいと思います。空いたままという状況になっていないのかどうか、伺います。","respondent":"中島保育施設運営課長","answer":"失礼いたしました。今回、補正で上げさせていただいた人数は、担任のできる派遣保育士１７名分です。その他の予算と調整した結果、この部分が不足するということで計上させていただいたところです。","voiceIndex":162,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問","question":"空きがないのかということで伺ったのですが、お答えください。","respondent":"中島保育施設運営課長","answer":"失礼いたしました。空きはしっかり対応し、派遣保育士、会計年度任用職員、臨時的任用を含めまして、しっかりと、穴はないように実施しています。","voiceIndex":164,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今年度は穴がないということなのですかね。今、急遽の場合、臨時的に派遣を使っているということでしたけれども、当初の場合から使っているということも聞いております。やはり、分かっている場合は正規で補充するようにすべきだと思いますけれども、いかがでしょうか。少なくとも臨時的任用職員か会計年度任用職員ということで補充すべきだと思いますが、いかがでしょうか。","respondent":"中島保育施設運営課長","answer":"やはり年度後半になりますと、派遣がなかなかすぐに安定的に入れないという場合もありまして、日替わりというか、少し短期間に入るような形の場面もありますが、極力、園に運営の支障がないように対応してまいりたいと思います。","voiceIndex":166,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"年度後半は難しいという話ですけれども、最初から埋まらないという事態があったということですので、そこはぜひ正規でやっていただきたいと思いますし、派遣が多いことで正規が大変になっているということでありますので、正規が担当する部分が多いということで、やはり正規を増やして、大変さを補うことで集まるということもあると思いますので、ぜひ正規を基本に補充していただきたいと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０１ページの防災課職員給与費に関連して、２月４日のＪアラート訓練、国民保護共同訓練も伺いたいと思います。２１日の本会議にて、選択的夫婦別姓について議論を尽くすことを国会および政府に求める意見書が採択され、私は反対しました。その理由は、今、国に求めることは議論ではなく、選択的夫婦別姓の導入だと思うからです。訓練実施前から中止を求める意見が区にも寄せられていると伺っております。","respondent":"伊藤災害対策担当課長","answer":"第２会場である、しながわ中央公園の会場につきましては、訓練会場に入ってしまったため、平面からですので人数は確認はできませんでしたけれども、訓練をやる前から大きな声が聞こえましたので、大勢の方が集まっていらっしゃったのかという認識です。","voiceIndex":170,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"多くの方が抗議の声を上げたということです。非戦闘員への無差別攻撃もまた国際法違反です。そこで品川区は非核平和都市品川宣言をしておりますが、こうした弾道ミサイルの発射、避難、救出救助、除染活動とは、品川区の平和宣言に反する事態だとは思わないのか伺います。宣言に反する事態を想定する訓練に品川区は参加すべきではないと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"ただ、区といたしましても、この訓練につきましては、平素から起こり得るであろう災害に関する地震や風水害といった訓練と同様に必要な訓練だと認識しておりますし、また、平和都市宣言に反するものではないと、私としては思っているところです。","voiceIndex":172,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"私が聞いたのは訓練の概要や目的ではなくて、こうした想定が平和宣言に反するものではないかと伺いました。お答えください。","respondent":"伊藤災害対策担当課長","answer":"ただいまの委員のご質問ですけれども、先ほども申し上げましたとおり、品川区の宣言に反するものではないと感じてあります。","voiceIndex":174,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問","question":"何がどういう理屈で宣言に反するものではないのか、全く中身がありませんでした。この訓練の想定について、区も弾道ミサイルと議会に説明しております。こうした訓練の想定は、まさに平和宣言に反する事態だと私は思いますが、何がどう思わないのか、しっかりお答えください。核兵器も搭載可能な弾道ミサイルの発射、避難、高い殺傷力、非人道性。どう考えても宣言に反すると思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"それが、ミサイルの落下であると判明したため、国民保護訓練につながったという内容であると認識しています。","voiceIndex":176,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"違うと言うだけで、何がどう違うのか全く説明がないという答弁が２回もありました。私は、こうした訓練の規模が大きくなればなるほど、平和宣言がなきものになってしまうと危機感を抱いております。訓練の想定は宣言に反するとはなぜ思わないのか、伺いたいと思います。他国であれ、日本であれ、どの国であっても、宣言に反する事態やその訓練は許されないと私は思いますが、いかがでしょうか。","respondent":"勝亦総務課長","answer":"そして冒頭で、「開発された兵器で使われなかったものはない。」と宣言しています。そういった意味では、理想の、核兵器のない、恒久的な平和な世界を目指している中でも、そういった現実を見つめるという部分については、非核平和宣言と反するものではないと考えています。","voiceIndex":178,"id":"exchange-078"},{"speaker":"中塚委員","kind":"質問・要望","question":"指摘に対して特に答弁はなく、ただ、区の事業を説明するだけのひどい答弁だと思います。やはり、訓練への参加は、宣言に照らして明らかに反する。こうしたものへの参加をやめるよう強く要望したいと思います。排除の声もあったのですけれども、それは後日また質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-079"},{"speaker":"せお委員","kind":"質問","question":"８５ページ、病児保育新規開設運営補助経費、１０５ページ、就学人口増に伴う教室整備を伺います。昨年９月に新規開設募集の説明会がありまして、午前中にも質疑で３事業者と協議しているというお話がありました。施設が減って説明会を行うという流れが昨年あったわけですけれども、それに伴って、品川区病児保育事業実施要綱は変更がありましたでしょうか。少し、その辺をお聞かせください。","respondent":"中島保育施設運営課長","answer":"要綱につきましては、１施設閉鎖になりましたので、その閉鎖に伴いまして、見直しています。","voiceIndex":182,"id":"exchange-080"},{"speaker":"せお委員","kind":"確認","question":"私は以前から考え方を区にはお伝えしていて、昨年の一般質問でもお話ししましたが、子どもの体調が悪いときには保護者が仕事を休めるような社会になるのが最終目標で、それに到達するまでは、病児保育を充実させることが行政の役割であると考えています。今お話ししたような様々な状況を踏まえた上で再度確認なのですけれども、区としての病児保育の在り方や方向性を、いま一度お聞かせください。","respondent":"中島保育施設運営課長","answer":"ベビーシッターにつきましても、現状周知に努めているところですが、他区の事例なども参考にしまして、区の独自支援などにつきましては、引き続き考えてまいりたいと考えています。","voiceIndex":184,"id":"exchange-081"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひ未就学児だけでなく、小学校低学年を対象にすることも含めて、ニーズの把握や、あと課題の抽出などを進めていただければと、今後のことを要望して、次に移ります。１０５ページ、就学人口増に伴う教室整備です。続けて、これは私の中ではここに関連しているのですけれども、校内別室指導のための教室、お部屋などは、全校、準備されている状況なのでしょうか。教えてください。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"では私からは、減額補正の理由についてお答えいたします。こちらにつきましては、本年度予定しておりました第三日野小学校の普通教室増設対応を取りやめたことによるものです。不登校児童・生徒が利用する校内別室指導を行う部屋についてですけれども、専用の部屋がない学校については、会議室やパソコン室、多目的室等を、開いている時間等を工夫しながら活用しています。","voiceIndex":186,"id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区もそのような考え方と方向性を明確にしてほしいと要望いたします。学校改築の方向性も明確にした上で、少し時代は違っていた、約１０年ぐらい前の改築が終了した学校などは、学校格差ができるという課題もありますので、教室整備という名目で、様々な要因に応じた部分改修というところは予算で確保するぐらいの方向性も、今後、示してほしいと考えているのですが、その辺の見解を教えてください。","respondent":"荒木学校施設担当課長","answer":"ご紹介いただいたように、品川区の未来の学校づくりというものを私のほうでも拝見しております。品川区の学校づくりに関しましても、効果的に外部に発信する手法についても検討してまいりたいと思います。","voiceIndex":189,"id":"exchange-083"},{"speaker":"せお委員","kind":"質問・要望","question":"ご答弁にもありましたが、本当に時代に合った、あと児童・生徒に合った学校整備を進めていっていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"こういう話で、なるほど、それは、人工芝が燃えるというか、人工芝というのはそういうものなのだろうというのは思ったのですけれども、一方で、きちんと管理しながらというか、気をつけながらやれば、できる部分というのはないのかとも思ったりもしたので、学校として、こういった防災訓練等で、人工芝のグラウンドの上などで火器を使うということに対して、どういった見解なのか、お伺いしたいと思います。","respondent":"荒木学校施設担当課長","answer":"ただし、町会の行事などで、一定程度、煮炊きをしたいといったご要望も聞いておりますので、そういった際は、人工芝の周辺に火を使えるようなスペースを設けて実施していただいているところです。","voiceIndex":193,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。厳禁ということで、非常に厳しくやられているのですね。続いて７７ページの、戸越地区児童発達支援センター等整備で、２,６００万円の減ということになっています。今年９月開設予定ですけれども、まず、この減額補正の理由を教えてください。","respondent":"佐藤障害者施策推進課長","answer":"こちらは、今おっしゃっていただいたとおり、本年９月の開設を見込んでいるところで、昨年から工事を進めているところですが、設計段階で材料費の物価上昇率等を見込んで予算化していたものですが、そういったところが想定を下回ったというところで。","voiceIndex":195,"id":"exchange-086"},{"speaker":"塚本委員","kind":"意見","question":"物価高を見込んだというところで、非常に先見の明があったということなのか、微妙な評価なのですけれども、いろいろな建築関係費用がスライド条項で増額となっている中で、やや目を引くというか、減額になった理由というのは、最初からそれを見込んでいたからだというところだったのですけれども、特に今、公共事業が多く増額になっている中で、今回減になったというところについて。","respondent":"長尾施設整備課長","answer":"こちらの工事の見積りにおいては、設計内容を踏まえて、工事費を概算で出しまして、また近年ですと物価上昇が見込まれますので、その部分に関しては一定の割合を乗じて、予算化するというところで進めております。","voiceIndex":197,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"その指定管理の中で、インクルージョンを実現させる内容というようなところを、１つ、ポイントとして評価点として挙げられているのですけれども、このインクルージョン、何となくイメージはできるのですが、児童センターと児童発達支援センターと、それぞれなので、もう少し具体的に、どういったものをこの施設の中で実現しようとしているのかを、開設がいよいよ迫る中で。","respondent":"藤村子ども育成課長","answer":"こちらにつきましては、今、指定管理者と調整しているところで、まだ概要というところなのですが、児童センターで、いわゆるグレーゾーンにあるお子様たちに向けて、学習支援というか、宿題の支援というか。","voiceIndex":199,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"いわゆる障害者支援のほうから言うところのインクルージョンというところでのご見解は何かありますでしょうか。そこを少しお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"今後、児童発達支援センター内に児童センターも設けることにより、より広く、子どもたち、障害の有無にかかわらず、また親子の交流、そして地域との交流というものができるような拠点にしていきたいと考えております。","voiceIndex":201,"id":"exchange-089"},{"speaker":"塚本委員","kind":"意見","question":"そういった中では手探りのようなところもあるかもしれませんけれども、児童センターと児童発達支援センターが、１つの施設の中で、フロアは違いますけれども、１つの指定管理者によって運営していくという中で、しっかりとした成果というか、相乗効果というようなものが生み出される、そういった施設としてやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":203,"id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私からは、７９ページ、福祉人材確保・定着事業と、７７ページの障害者グループホーム整備助成等について、お願いします。品川区の介護職員居住支援手当なのですけれども、こちらは１億６,０００万円ほどの減額となっております。その理由をお伺いいたします。","respondent":"菅野高齢者福祉課長","answer":"私からは、品川区介護職員居住支援手当の減額の理由をご説明します。こちらについては、今年度、新規事業で始めさせていただいておりましたが、申請件数が想定よりも少なく、執行残が発生するため、今回、減額補正とさせていただきました。","voiceIndex":205,"id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく想定の７割ぐらいなのかと思うのですけれども、具体的になぜ、執行率というか、申請が７割程度だったのかということの分析というのは、区でされていますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"委員のおっしゃったとおり、申請が予想よりも少なかったということの理由等につきましては、約７割ぐらいということなのですが、その理由としましては、まず今回、今年度初めての事業ということでしたので、事業の動き出し、事業スキームの制度設計等も、東京都に合わせたり。","voiceIndex":207,"id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"想定されることとして、そのほかに例えば、こういった事業を知らないなどという可能性もあるかと思うのですけれども、全国規模の事業所は、格差が出てしまうからあえて申請しないということを伺いました。もしアンケートで事業者や職員の方の声などがあればお聞かせください。","respondent":"菅野高齢者福祉課長","answer":"区のホームページを通しても周知させていただいた次第です。このアンケートにつきましても、ポータルサイトを通じて実施させていただいたところ、寄せられたという結果となっております。","voiceIndex":209,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"看護師でももらえるのです。今回、１億６,０００万円ということは、大体、見込みと比べ１,３００人、１,４００人ぐらい申請できていないのかと思います。せっかく区として目玉の、物すごくいい事業だと思いますので、ぜひこういったところも柔軟に検討していただきたいと思いますけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"都においては来年度も対象者を拡充するとは聞いておりません。区も、来年度も同じように事業を実施させていただいて、事業者からいろいろな声が今後寄せられると思います。その辺りのところは今後検討していきたいと思います。","voiceIndex":211,"id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ前向きに検討していただければと思います。ちょうど先週、地域を回っていて、７０歳の高齢の方が、９０代のお母様を介護していて、日曜日にヘルパーがなかなか見つからないのだとお聞きしました。次です。これは、資格要件があり、もしくは実務経験が常勤で３年以上ということで、非常にハードルが高い。今期の見込みの実績がもし分かれば、お伺いしたいのですが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"グループホームの有資格者助成の今期の見込みですが、１事業者・２件です。","voiceIndex":213,"id":"exchange-095"},{"speaker":"やなぎさわ委員","kind":"質問","question":"やはり見込みより少ないということです。これは、職員１人につき毎月１０万円、助成されるということで、非常に事業所としてはありがたいものなのですけれども、やはり申請にハードルがあるです。そのときの前回の決算特別委員会の答弁で、事業者の声を聞きながら、緩和を検討していただけるとおっしゃっていたのですけれども、その後の状況はいかがでしょうか。","respondent":"松山障害者支援課長","answer":"要件緩和につきまして検討いたしましたところ、サービスの質を確保する観点から、現行の要件による助成は継続しつつも、加えまして、中・重度の障害者の方が入居をさらに進めるために、来年度から事業所に対する新たな助成を考えることといたしました。","voiceIndex":215,"id":"exchange-096"},{"speaker":"やなぎさわ委員","kind":"質問","question":"初耳なのですけれども、ぜひその要件をお伺いしてもよろしいですか。恐らくプレス発表がないと思うので、お願いします。","respondent":"松山障害者支援課長","answer":"具体的には、入居者１人当たり、例えば最重度の方、区分６の方については月９万円。それから、区分３の方については月４万５,０００円と、障害支援区分につきまして助成額を設けまして、より重度の方の入居が進むよう、事業者を支援してまいります。","voiceIndex":217,"id":"exchange-097"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"非常にすばらしい施策だと思います。ちなみにこれはプレス発表がなかったと思うのですけれども、ぜひこれは、品川区で全面的に広めていったほうがいいかと思うのですけれども、いかがでしょう。何でプレス発表がなかったのかというのと、周知をしっかりしていただきたいのですけれども、その辺はいかがでしょうか。お伺いいたします。","respondent":"松山障害者支援課長","answer":"この事業につきましては、大変いい事業と自負しておりますが、プレスにつきましては、総合的に区としてプレスしたものですので、今後この事業につきまして周知に努めてまいります。","voiceIndex":219,"id":"exchange-098"},{"speaker":"松永委員","kind":"確認","question":"私からは、６９ページの区民施設経費、そして８７ページ、猫の適正飼養および活動支援事業について伺いたいと思います。初めに６９ページの区民施設経費、７７７万７,０００円の減額について伺いたいと思います。利用状況の中で、品川区内、そして区外、外国人の方についての統計を取っていれば、そのことについても併せて伺いたいと思います。","respondent":"宮澤地域活動課長","answer":"その後、宿泊者は減少してきておりまして、コロナ前、令和元年は１,８３５名という状況。コロナ後につきましては、一般利用のうち団体に限って貸しておりまして、令和５年度は約８０名という形です。","voiceIndex":223,"id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"年々、利用状況がよい方向に向かえればいいかと考えていますが、先ほどのご答弁の中で、そうではないということは確認できました。","respondent":"宮澤地域活動課長","answer":"利用目的につきましては、アンケート等を取っておりますが、特段、利用目的等はお伺いしておりませんが、おおむね区民の保養所というところで、それぞれ大人のグループ同士で来たり、宿泊されていたり、家族連れで来たりということで。","voiceIndex":225,"id":"exchange-100"},{"speaker":"松永委員","kind":"質問","question":"そういった統計やアンケートというのはいろいろお伺いしました。そこで、料金設定について伺いたいと思います。今現在、食材価格も物価高騰等で大変苦労されているかと思いますが、区としてどういった対策を行っているのか教えてください。誰もが利用できるような施設であるべきと私は考えますけれども、これは、利用者が増えれば、今後、一般の方も利用できるということでよろしいでしょうか。","respondent":"宮澤地域活動課長","answer":"光林荘を含めてのところになりますが、宿泊者数が確かに増えていけば、団体に限らず一般の利用というのもできるかというところでありますが、コロナ前の時点からも、なかなかそこが難しいとは、事業者からお話は聞いているところです。","voiceIndex":227,"id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"そこで、誰でも利用しやすい保養所についてですが、ホームページ等を拝見させていただきましたが、ホームページのアクセス数については統計などは取られているのでしょうか。そこで、ホームページにアクセスしやすい環境、いわゆる旅行会社との連携や、ホームページにヒットさせやすくするための口コミなど、区が行える範囲のＳＮＳの活用など、今後の取組についてお知らせいただければと思います。","respondent":"宮澤地域活動課長","answer":"事業者で、品川荘であればインスタグラムを使って、現地からのお料理の写真等々、発信しています。区といたしましても、ＳＮＳの活用など、効果的な周知の方法については検討していきたいと考えております。","voiceIndex":229,"id":"exchange-102"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ今後、進めていただければと思います。次に８７ページの、猫の適正飼養および活動支援事業、６５０万円減について伺います。例えば、近隣住民の敷地内でふん尿をする、深夜の鳴き声、花壇を荒らすなど、近隣の方が迷惑し、苦情が多く寄せられている事例があると伺っております。このことについて、猫の講習会ということを行っていると思いますけれども、どういった内容になるのでしょうか。","respondent":"赤木生活衛生課長","answer":"今週末も第２回目というところで実施する予定で、内容としましては、これから地域猫活動を始めようとされている方に向けて、実際にトラップゲージという、猫を捕まえる、わながあるのですけれども、そういう、わなの使い方や。","voiceIndex":231,"id":"exchange-103"},{"speaker":"松永委員","kind":"意見","question":"こうしたトラブルを解決するためには、地域・まちの声と理解というのがとても大事になってきますので、こうした講習会については、町会・自治会でも「やってくれ」という声があれば、ぜひ引き受けていただければと考えていますが、区の考えをお知らせください。","respondent":"赤木生活衛生課長","answer":"先ほど委員からご質問としていただきました、町会からの要望というところでの講習会の実施ですが、今、現状としまして、町会・自治会からご要望というのは特にはいただいてはいない状況ではありますけれども、もしご要望等いただけるようであれば。","voiceIndex":233,"id":"exchange-104","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは私の認識では、平成３０年から、公道上の、道路において、大地震や台風などによって倒壊のおそれがあり、人命を守るため安全性が確認できない公道の、４２条２項道路沿いの塀の除却を支援するということで、これは、まず今年度目標の件数と、今お分かりになるのであれば現在までの件数をお示ししていただきたいと思います。","respondent":"森建築課長","answer":"コンクリートブロック塀の助成の目標数値ですけれども、目標は今年度、５０件でございました。実績といたしましては、本日までで３０件となっています。","voiceIndex":237,"id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"確認","question":"区は、ポスティングなどで、いろいろ啓発などやられていると思うのです。そういうことで言うと、今現在、「今年度は例えば荏原ブロックを、限定してやっています」などという考え方でよろしいのでしょうか。","respondent":"森建築課長","answer":"品川区内を５区画に分けまして、５か年で区内全域にチラシを配っております。１年当たり約７００枚程度お配りさせていただいて、今までで２,６００枚から２,７００枚、お配りしています。","voiceIndex":239,"id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"確認","question":"こういったことをやって取り組んでおられるのならば改めてご答弁をお願いしたいのと、私は、これはすごく、お子さんの安全を守る観点からも、やはり通学路に面するブロック塀の点検をしていただいて、なおかつそこが、損傷が見られる、倒壊のおそれがある住居・宅地に至っては、そのオーナーにポスティングをする、啓発して取り組んでもらうというのは。","respondent":"森建築課長","answer":"通学路の安全性につきましては、教育委員会の教育総合支援センターで行っているとは思うのですけれども、建築課からも、ブロック塀の安全性についても一緒に確認してほしいというお話をしていますし、必要であれば我々も参加させていただいて。","voiceIndex":241,"id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望します。次に９１ページ、創業・スタートアップ等支援経費についてお伺いいたします。最初に、今年度から新しく組織変更されて、新しくスタートアップ支援担当ができたということで、新しくこの課をまとめるに当たって、課長も相当、この１年間ご苦労があったかと思うのですけれども、まず最初に感想を述べていただきたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"この年度末にかけて、ようやく手応えというか、成果が出始めてきたところですので、この勢いを来年度にもつなげていきたいと考えております。","voiceIndex":243,"id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、あと昨年ですか、１０月２９日に福岡市とのイベント、今年度、区長も行かれたかと思っているのですが、これはもう一番に、２０１２年にスタートアップ支援、スタートアップ都市宣言を実施した福岡市と、連携していくということで今後どういうふうにやっていくのか。ぜひとも福岡市だけでなく、今後どういうふうに取り組んでいくのか、方向性をお示ししていただければと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"この取組は来年度も継続してやっていきたいと考えております。","voiceIndex":245,"id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。ぜひ今後ともよろしくお願いいたします。最後に、先日、第１４回ウーマンズビジネスグランプリがあったかと思います。以前、友人が入賞して、それからいろいろお話をさせていただいたのですけれども、ぜひ今後、今までの入賞者、参加していただいた方への伴走支援をしていただきたいと要望して終わりにしたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問","question":"私も、スタートアップ、頑張っていただいていると思っています。今日はやらないから大丈夫です。８３、８５ページ、各保育園運営費について、そして８１ページ、しながわネウボラネットワーク事業についてお伺いします。その部分が今回、運営費に入っているのかと思うのですが、改めて、いわゆる保育士等の給与アップについて、どのようなものが運営費に盛り込まれているのか教えてください。","respondent":"佐藤保育事業担当課長","answer":"今、委員からお話しいただきました運営費の増額補正についてですが、こちらは、お話しいただきましたように、処遇改善の加算の増額ということで、４月に遡って各事業者に支払われる分です。","voiceIndex":249,"id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そうすると、人件費ではないところで使う園もあると聞いています。それは分かるのだけれども、今、保育士等の給与を何とかして上げて人材を確保していこうという部分もあっての給与アップだと思うので、そこはぜひ、できる限り、各保育士の処遇改善につながっていくように、区としても保育園、各運営事業者と取り組んでいただきたいと思います。その辺を教えてください。","respondent":"佐藤保育事業担当課長","answer":"制度における相談体制ですが、毎月、我々は運営費の支払いというのを各私立保育園等に実施してございまして、そういった意味ではコミュニケーションが非常によく取れてありますので、何か質問等あった際には丁寧な対応をいつでもできるように体制を整えているところです。","voiceIndex":251,"id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ進めていっていただければと思います。いわゆる保育園の経営をもっときちんと見える化していこうというのが、義務化されると思うのですけれども、やはり、そういった制度が変更されていく中で、なかなか業務が煩雑になってしまう可能性もあるので、先ほどお話ししたとおり、相談体制というか、制度が変わったときに区に確認したら、すぐ対応してもらえるというような体制づくりが必要だと思います。","respondent":"佐藤保育事業担当課長","answer":"制度の改正というものの背景に、非常に細かい事務作業というのがあるので、それを簡略化したいという国の意向もあります。我々としてもしっかりと丁寧に、私立保育園園長会等がありますので、そうした機会を使いながら丁寧に説明していきたいと考えております。","voiceIndex":253,"id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ進めていっていただければと思います。続きまして、ネウボラについてです。品川区が考えるネウボラについて、どのように区として考えているのか教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"その両者の連携が非常に重要であるというところを認識しておりまして、この４月からは、保健センターにも子ども家庭支援センターの福祉職の配置をするなど、より連携を強めて、ネウボラネットワーク全体として切れ目のない支援を実施していきたいと考えているところです。","voiceIndex":255,"id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問","question":"これが全部違うのです。しかも、その方が例えば、何だろう、表情一つでも元気に来てくれて、「何かありますか」といったときには、こちらもそういう対応をするかもしれないけれども、「どうですか」と言われたらそうでもないし、それは人によっても違うと思うのだけれども、私は、やはりここは、ある程度、有識者というか、相談ができる体制づくりをつくっていかないと、やる意味がないのではないかと思う。","respondent":"石橋品川保健センター所長","answer":"その後、妊娠８か月頃の面談や、あとは出産後のすくすく赤ちゃん訪問、見守りおむつ定期便、確かに対応する職員や支援員は違うのですが、そこについてはしっかりと、保健センターの職員、専門職と連携を取って実施しているところになります。","voiceIndex":257,"id":"exchange-115"},{"speaker":"こんの委員","kind":"質問","question":"私からは、９７ページ、大井町駅周辺地区再開発事業、１０５ページ、校舎等整備、空調改修工事費について伺いたいと思います。順不同で行きます。具体的に１つ申し上げると、伊藤小学校では、空調が効きが悪いという、そういう声を聞いたのですけれども、まずその点についてご認識されていらっしゃいますでしょうか。そのときの対応はどのようにされたのか、簡単にお答えください。","respondent":"荒木学校施設担当課長","answer":"その対応につきましては、現地の機器を確認したところ、空調機の詰まり、フィルターの詰まりなどが確認できましたので、こちらは即、業者に依頼して、フィルターの清掃を実施し、現在は改善されているという認識です。","voiceIndex":260,"id":"exchange-116"},{"speaker":"こんの委員","kind":"質問","question":"現状について、ありがとうございました。減額補正で、１,８７０万円減額になっているので、この物価高の中、空調機工事についても物価高の影響を得ている中で、減額というのはどういう状況だったのかというのを、参考までに伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"先ほどの答弁で申し上げたような伊藤小学校とは別に、耐用年数をおおむね１５年程度と、空調機は計画しているのですけれども、この耐用年数が過ぎたものに関して計画的に改修を進めているというものです。","voiceIndex":262,"id":"exchange-117","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"確認","question":"全面改修という形でリニューアル、しかも１５年程度を経過したものという基準でされているということを確認いたしました。そうしましたら、評価ＢとＣに値する小学校３校と中学校２校は、一度も改修工事がされていない現状が見受けられました。こうしたことが、なかなか修繕に至っていないのかという現状が見えるのですが、その辺のところを教えてください。","respondent":"荒木学校施設担当課長","answer":"現地も確認いたしまして、１５年を経過している空調機も数多く発生しておりますので、保全的に実施するものと、もう緊急的に対応しなければいけないものをしっかりと見極めて工事に当たっているところです。","voiceIndex":264,"id":"exchange-118"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校改築が計画されているところは、そのときにするというのも私は理解しております。そうではない、まだ順番が来ていない学校で不具合が起きたときの対応です。その箇所だけの修繕ではなくて、抜本的にやはり替えていかなくてはいけないという現状を、よくよく見極めて対応していただきたいと思います。この点については、いかが考えていますでしょうか。","respondent":"荒木学校施設担当課長","answer":"既存校につきましては、面積的・スペース的な問題から、なかなか取り組むのが難しいという現状はあるのですけれども、こちらも経費などを勘案しまして、可能な限り、対応を検討してまいりたいと思います。","voiceIndex":266,"id":"exchange-119"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校改築のときに合わせてというお考えは分かりました。一方で、「ＪＲでは大型のエレベーターやスロープ設置は難しいと聞いています」という答弁だったのですが、区としては、それで仕方がないという状況でいらっしゃるのか、いやいや、区民の利便性とというところで、さらに要望していくというお考えなのか、その点をもう一度確認させてください。","respondent":"中道都市開発課長","answer":"なかなか立地条件等は難しい状況ではありますが、「ＯＩＭＡＣＨＩ ＴＲＡＣＫＳ」が１年後に開業しますけれども、北口にも新たなバリアフリールートなどができまして、また、そこからサンピア商店街とつながる通路などもできるですので、そうした状況を区としては注視しながら。","voiceIndex":268,"id":"exchange-120"},{"speaker":"鈴木委員","kind":"提案","question":"私からは、８ページの歳入全体と、それから７９ページの品川区介護職員居住支援手当の減額について伺いたいと思います。前の補正予算を見てみたのですけれども、令和元年から令和５年度の５年間の中で、この３項目が計上されていないのですけれども、今年度、特にこの３項目が増収になった理由を区としてどう捉えているのかを伺いたいと思います。","respondent":"加島財政課長","answer":"１点目の、配当割交付金、株式等譲渡所得割交付金、地方消費税交付金の増額補正を行った理由についてですけれども、こちらは令和６年度、年度途中までの収入実績を見込みまして、令和７年度末までの予測を立てて、今回、最終補正で増額を組んだものです。","voiceIndex":271,"id":"exchange-121"},{"speaker":"鈴木委員","kind":"質問","question":"私はこれは、物価高の影響があるのではないかと思うのですけれども、その点はいかがでしょうか。それから、あと地方消費税というのは、一般的な標準税率の、１０％の場合は地方消費税２.２％、それから軽減税率の食品などは１.７６％ということになっていますけれども、このうち品川区に入る消費税分というのは何％なのかを伺いたいと思います。","respondent":"加島財政課長、吉野税務課長","answer":"この区の収入となるうち、２２分の１０を一般財源、２２分の１２を社会保障の財源として充てしています。こちらは法律に基づく対応です。非課税世帯の件なのですけれども、令和５年度と令和６年度を比べまして、ほぼ一緒の数字になっております。４万３,０００世帯になっております。","voiceIndex":273,"id":"exchange-122"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、これだけ今まで近年にない増収になっているわけですから、これは区民に対して還元すべきではないかと思います。これは、中小企業や商店街支援とともに、地球温暖化対策ということでも大変効果的なのではないかと思っていまして、そういう点でも、こういう心を寄せた施策、それから、今年、打ち切るのではなくて継続ということもできるのではないかと思いますけれども、いかがでしょうか。","respondent":"吉野税務課長、小林地域産業振興課長","answer":"非課税世帯の割合ですけれども、２０％前後になっております。今後も物価高騰の状況や、あるいは地域の声を聞きながら、必要な対策というのを、資金繰り支援も含めて、助成金も含めて、進めてまいりたいと考えております。","voiceIndex":276,"id":"exchange-123"},{"speaker":"鈴木委員","kind":"意見","question":"もう時間がないので、すみません。この補正予算に対しての態度を表明したいと思います。１１８億円という増収分は、近年にない最高の増収ということで、特に貧困で苦しむ方のためにも還元すべきだということで、反対という表明をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":279,"id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、９９ページ、耐震診断関連で、住宅・建築物耐震化支援事業、７９ページ、品川区介護職員居住支援手当関係、９１ページ、中小企業の販路拡大支援事業、８７ページ、産後ケア事業に関連してお伺いしたいと思います。最後、区議会事務局にもお伺いしたいと思いますので、よろしくお願いします。今挙げた項目というのは、それぞれは聞きません。","respondent":"加島財政課長","answer":"令和６年度ウェルビーイング予算に関する評価ですけれども、令和６年度のウェルビーイング予算につきましては、４つの柱、「安全・安心を守る」、「社会全体で子どもと子育てを支える」、「生きづらさをなくし住み続けられるやさしい社会をつくる」など。","voiceIndex":281,"id":"exchange-125"},{"speaker":"田中委員","kind":"質問","question":"私は説明の後に部長にお伺いしたのですけれども、令和７年度は、いわゆるウェルビーイング予算をしないのか、事務事業評価をして、それで生み出した財源を基に新たな支出をすることはないのかという質問をしたところ、ようやく部長からご答弁いただいたのですが、そういうのを見ていると、区長は積極的にプレス発表等々でウェルビーイングの２.０バージョンを発表されている一方で、我々議会に対して。","respondent":"久保田企画経営部長","answer":"１月の末に、各会派、無所属議員も含めて、各予算の説明をさせていただきました。これは、プレス発表とは違いまして、各事業について令和７年度に品川区としてどういう取組を進めていくかということを、詳しくプレス発表の前に事前に説明するという趣旨でやらせていただいたです。","voiceIndex":283,"id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、区議会事務局の関係でお伺いしたいのですけれども、令和６年度の予算案が議決したときの区議会だよりには、ここには毎年、新年度予算の議決内容が報告されますが、令和６年度の議決がされた際に、ウェルビーイング予算の「ウ」の字も、一文字も載っていなかったのですけれども、これは、どういうことからそういう紙面になってしまったのか、お伺いしたいと思います。","respondent":"大澤区議会事務局長","answer":"区議会だよりの内容につきましては、広報会議で検討されて掲載されているものですので、事務局からの見解というよりは、広報会議での決定ということになってあります。","voiceIndex":285,"id":"exchange-127"},{"speaker":"田中委員","kind":"質問・要望","question":"二元代表制の下での議決機関として、我々は責任があるわけですので、そういった意味では、プレス発表の資料ではなくて、議会説明資料をプレスに発表するという、本来はそうあるべきだと考えていますが、戦略広報課、今度は報道関係のことに変わるのですけれども、その辺の議会に対する説明の在り方、プレス発表の在り方について、お聞かせいただきたいと思います。","respondent":"與那嶺戦略広報課長","answer":"そういった形でこれまで進めてきたところですので、事前の議会への説明というところ、今回ご指摘がありましたけれども、そちらについては今後の検討かと思います。","voiceIndex":287,"id":"exchange-128"},{"speaker":"田中委員","kind":"意見","question":"プレス発表に力を入れるのは当然必要だと考えています。区長は恐らくそれだけを目的にプレス発表されているとは当然思えず、私はそのような発表こそ、直接議会に、我々が一つ一つの施策をどういう思いで立案され、どうしようと思われているのかということをしっかり説明した上で、今日のような予算特別委員会に本当は臨んでいくことがいい形なのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":289,"id":"exchange-129"},{"speaker":"えのした委員","kind":"質問","question":"私からは、９９ページのしながわ水族館リニューアル経費についてお伺いします。令和６年度に行われた決算特別委員会でもお伺いいたしましたが、水族館は、持続可能な開発目標、ＳＤＧｓの１７の目標に関わり貢献することができ、魅力ある品川区の施設として価値を高めることが期待されています。今後の進め方を、なぜ見直しをするのか、改めて理由をお伺いいたします。","respondent":"大友公園課長","answer":"この状況を踏まえまして、より効果的かつ効率的な整備運営手法の再検討を実施するものです。見直しに当たりましては、しながわ水族館のより一層の魅力向上に向けて、さらなる民間活力の導入も検討してまいります。","voiceIndex":292,"id":"exchange-130"},{"speaker":"えのした委員","kind":"確認","question":"ご答弁ありがとうあります。確認が取れました。総務省が今年の１月に発表した、２０２４年１２月の消費者物価指数は、変動の大きい生鮮食品を除く総合指数が１０９.６となり、前年同月と比べて３.０％上昇した。物価高騰による影響を受けてとのことであるようですが、水族館のリニューアルにおいての影響はどのようなものか、お伺いいたします。","respondent":"大友公園課長","answer":"建設資材の高騰は、３年で約３割増となっております。特注品の設備につきましては、一般的な建築資材よりも上昇幅が大きく超えるものがあるところです。","voiceIndex":294,"id":"exchange-131"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。昨年１２月の建設委員会での議会報告会では、久しぶりに区民の方と一緒にしながわ水族館も見学させていただき、バックヤードなどの、普段入れない施設の案内をしていただきました。その旨、理解いたしました。そこでお伺いいたします。リニューアルのオープンはいつ頃になるのでしょうか。お聞かせください。","respondent":"大友公園課長","answer":"は来年度、整備運営手法の検討を行いまして、併せてリニューアルオープン時期を含めたスケジュールの見直しも行う予定です。今後、その検討を踏まえまして、リニューアルオープンの時期など、スケジュールについて結果をご報告したいと考えております。","voiceIndex":296,"id":"exchange-132"},{"speaker":"えのした委員","kind":"質問","question":"よいご報告を期待してお待ちしております。そこでお伺いいたします。これは課題として、リニューアルオープンを遅らせれば、さらに事業費は上昇するのではないでしょうか。ご見解をお聞かせください。","respondent":"大友公園課長","answer":"物価高騰を予測することは、かなり難しいところではあります。今後も物価の高騰が続くことも想定されますが、より効果的かつ効率的な整備運営手法を見直すことで、事業費の削減を図っていければと考えています。","voiceIndex":298,"id":"exchange-133"},{"speaker":"えのした委員","kind":"質問","question":"そうですね。今まで人気のあったイルカショーやイルカ展示は行わないとしておりますが、しながわ水族館リニューアルの方向性について見直しをするのでしょうか。ご見解をお伺いします。","respondent":"大友公園課長","answer":"基本的には、しながわ水族館リニューアルの方向性についての内容を変えることは考えておりません。リニューアルに当たっては、方向性で示した内容を、より効果的かつ効率的に実現できる手法を検討してまいります。","voiceIndex":302,"id":"exchange-134"},{"speaker":"えのした委員","kind":"提案","question":"確認が取れました。そして、リニューアル後はどのような水族館になるのか、冒頭、決算特別委員会でも、質問・提案、様々させていただいたと申しましたが、その後、建設委員会の行政視察では、岐阜県各務原市、世界淡水魚園水族館アクア・トトぎふ、あと、また会派視察では、福井県の坂井市の越前松島水族館に伺いました。そんなことが当たり前になってきております。ご見解をお伺いいたします。","respondent":"大友公園課長","answer":"併せて、大井競馬場をはじめとした周辺施設との連携強化を進めてまいりたいと考えています。","voiceIndex":304,"id":"exchange-135"},{"speaker":"えのした委員","kind":"質問・要望","question":"現状、しながわ水族館でも体験として、餌やり体験やバックヤードに入れる体験、アザラシへの餌やりなど、これは事前の予約から当日まで行うことを確認しております。ぜひ大井競馬場との連携強化を進めていただきたく、要望とします。そこでお伺いいたします。リニューアルオープンは期待するところではありますが、リニューアルの延長に伴って、現状の水族館はどうなるのでしょうか。お聞かせください。","respondent":"大友公園課長","answer":"引き続き、しながわ水族館の魅力を発信する企画や展示を実施するなど、事業者と連携しながら、より魅力のあるしながわ水族館の運営に努めてまいりたいと考えております。","voiceIndex":306,"id":"exchange-136","title":"町会・自治会支援"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご答弁ありがとうあります。やはり、現状のしながわ水族館についても、リニューアルオープンまでに時間がありますので、まだオープン時期も決まっていないということですから、区民をはじめとした多くの皆様から引き続き愛され続ける、魅力のある水族館の運営を期待・要望して質問をしますが、まだ時間が少し余りましたので、ぜひリニューアルに向けた思いを聞かせていただければと思います。","respondent":"大友公園課長","answer":"しかしながら、今回、このような物価高騰に伴うきっかけもあり、一時、立ち止まらせていただくというところはありますけれども、ピンチをチャンスにといったことも先ほどいただいたところではありますけれども、よりよい水族館になるような検討機会を与えられたというところで。","voiceIndex":308,"id":"exchange-137"},{"speaker":"若林委員","kind":"確認","question":"７７ページの生活介護については、まずは増額の理由を確認します。それから、同じく７７ページの救急代理通報システム。これについては１,７００万円減額になっております。これについての減額理由も教えてください。よろしくお願いします。","respondent":"松山障害者支援課長、東野福祉計画課長","answer":"私からは、生活介護の増額の理由です。当初は前年度実績の利用者４９６人を見込みまして予算を組んでおりましたが、令和６年１２月末時点で既に利用者が４９６人に達しまして、今後も増える見込みであるため、補正を計上するものです。無償化によりまして利用者が大分増えるという見込みをしていたところなのですけれども、現在のところ、令和６年１２月現在で約１,１００件というところで、見込みが少し多過ぎたかというところでの減額となっております。","voiceIndex":311,"id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"生活介護は既に４９６人の予定を大幅に超えそうだというところで、重症心身障害者のことについて数字をいろいろ確認させていただきたいと思います。一応聞きます。その辺の、委託先の例えば出動数など、実績も確認させていただいて、逆に、どのぐらいまでなら１委託先で対応可能なのかというところが分かれば教えていただきたいと思います。","respondent":"松山障害者支援課長、東野福祉計画課長","answer":"重症心身障害者という定義が大島分類という定義で成っておりますので、区分等ではなく、実際に一件一件、ケースを当たりましてお調べしないと、把握できないものです。こちらにつきましては、廃止も含めてというところになります。月対応でいきますと、年間で３７０件設置している、廃止が１７０件ほどあるというような状況となっております。","voiceIndex":314,"id":"exchange-139"},{"speaker":"若林委員","kind":"確認","question":"すみません。いわゆる車椅子を使わないといけない、あとは、いわゆる支援区分５や６などという重度の方は。そうか。通じないか。事前の確認が不十分だったかもしれません。では、これは飛ばしまして、救急代理通報システムについてはもう、例えば令和７年度の予算をまだ見ていませんけれども、こういった１,５００件などという予算立て、件数は、１委託先ではもう無理だと表した答弁なのでしょうか。","respondent":"東野福祉計画課長","answer":"令和７年度予算は、実は月１,５００件という形で組んでいるところです。今、受託している事業者が今後どういう形で対応できるかというところにつきましても、併せ持って来年度、委託の仕方については考えていければと思っているところです。","voiceIndex":317,"id":"exchange-140"},{"speaker":"若林委員","kind":"質問・要望","question":"予算も組まれているということで、また改めて確認するかもしれませんけれども、さらに拡充していくと。障害者も含めて高齢者等の命を守っていく大事なサービスということで、いずれにしても充実を図っていただきたい。それ以外に申請されている窓口というのはあるのでしょうか。その辺の数値的な実績もお聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"先ほどの３７０件という数字からいきますと、支え愛・ほっとステーションで受けているのが１６７件、在宅介護支援センターで受けているのが２０３件という形になってあります。","voiceIndex":319,"id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひ大家も含めて、居住する方の安心も含めて、ぜひ広げていっていただきたいサービスの一つだというのも、委員会でご紹介させていただいたと思います。そこで、例えばこれから、居住支援の充実も来年度さらに図っていくということで、課がまたがりますけれども、例えば住宅部門との連携で、そういったことの充実・拡充というのも図っていただきたいと要望いたしますが、お考えをお聞かせください。","respondent":"東野福祉計画課長","answer":"住宅部門とも連携を取りまして、拡充を図っていければと考えています。","voiceIndex":321,"id":"exchange-142"},{"speaker":"西本委員","kind":"質問","question":"今まで議論がありました病児保育について一言質問したいと思います。病気になったときぐらい、親が面倒を見るべきだと私は思うのです。なので、大切なのは、やはり病気で仕事を休むというのが当たり前の社会になるというのが、これが最高・究極の目標だと思います。これはすごくいいことだと思っているのです。誰が子どもの面倒を見るのですか。そのことに関して、この支援について、もう一度お答えください。","respondent":"中島保育施設運営課長","answer":"あくまでそれは最終的な目標ということで、社会がそういうふうになればいいのかとは確かに思いますが、現状、就労している状況の中で、それを両立するという現実もありますので、そこに区もしっかりと対応して。","voiceIndex":324,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"皆さん、これはもう既に工事が始まっているのでしょうか。でも、これは遺贈という形で、公正証書等を含めて報告するという形だったのですけれども、議会への報告はないですけれども、それでも既に始まってしまっているのでしょうか。これはどうなのでしょうか。これは想定内なのですか、想定外なのですか。それが倍以上になっているのですか。見立てが非常に甘いのではないですか。その辺をお伺いします。","respondent":"勝亦総務課長、吉岡政策推進担当課長、平原防災課長、飛田子育て応援課長","answer":"現状、荏原町「秀」への移転に向けまして、賃貸借契約は９月下旬に締結いたしまして、これに基づきまして。公正証書、遺言の作成についてというお尋ねがありましたけれども、こちらについては個人のプライバシーに関わる部分ですので、報告の時期というのは。ただ、区といたしましては、在宅避難を区民に推奨する中で、それぞれ何が必要かを考えていただくきっかけとして、ハンドブックとともに。","voiceIndex":326,"id":"exchange-144"},{"speaker":"西本委員","kind":"質問","question":"「秀」の件ですけれども、公正証書は、別に個人情報が書かれたものですから、中身はいいです。そういう形で工事等々を進めるのですか」という形で、それはオーケーを取っていたと思います。議会に報告されるのですか。お答えください。反省してほしいと思います。そうしたら、高校生まで拡大するというではないですか。これはおかしくないですか。そういうのをよしとしてやるのですか。そこをお答えください。","respondent":"吉岡政策推進担当課長、平原防災課長、飛田子育て応援課長","answer":"こちらにつきましては、個人情報に係るところですので、適切な時期に、そういった報告をするというふうに考えているところです。そのような中で、それだけの数のものが届いているという状況ですので、令和６年度はまず配布していますけれども。それにまた、お米をただ支援するだけではなくて、児童センターでの見守りも図っていきたいと考えております。","voiceIndex":331,"id":"exchange-145"},{"speaker":"澤田委員","kind":"確認","question":"私からは、８３ページ、ベビーシッター利用支援事業費、８７ページ、不妊治療等支援事業についてお伺いしたいと思います。は８３ページ、ベビーシッター利用支援事業費についてです。１億円を超える増額補正が行われており、それだけニーズが多いということは、本日、質疑の中で何度も確認されたところであります。私自身も、小学生の双子を現在育てておりますけれども、何もかもが２倍かかるので大変です。","respondent":"芝野保育入園調整課長","answer":"国の調査によりますと、子どもが１人の世帯が全体の約４９％、２人以上の世帯が全体の５１％ということになっておりますので、多い・少ないという比較は難しいところではあるのですが、兄弟で利用されている家庭のニーズはあるものと認識しております。","voiceIndex":336,"id":"exchange-146"},{"speaker":"澤田委員","kind":"質問","question":"ただ、どうしてもすまいるスクールに合わないお子さんや、保護者がひとり親の場合には特にですけれども、両親がそろっていたとしても、近くに祖父母などの頼れる人がいなくて、１９時までにお迎えできない場合もあるかと思います。１０時まで預かってくださいますが、様々課題があるともお聞きしています。すまいるスクールに合わないお子さんなどについては、どのようにお考えでしょうか。","respondent":"藤村子ども育成課長","answer":"すまいるスクールに合わないお子様というところで、今、すまいるスクールに行きますと、すまっぴという形で、親御さんにメールが行くような形で、安心安全の環境を提供しておるのですけれども、児童センターにつきましても。","voiceIndex":340,"id":"exchange-147"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ児童センター、すまいるスクール、ファミリー・サポート・センター、いろんなサポートの形で支援していて、でも、そこに合わない、どうしても無理だ、難しいというお子さんや保護者の方に向けて、品川区としても、低学年児童のベビーシッター利用者の現状やニーズの把握をまずはじめとして、先ほど来から皆さんがおっしゃっていますけれども病児保育とともに、私からの要望として。","respondent":"若生健康課長","answer":"不妊治療支援事業の減額理由です。今年度７月から開始しました生殖補助医療による不妊治療医療費の助成件数が、当初の見込みより少なかったことになります。","voiceIndex":342,"id":"exchange-148"},{"speaker":"澤田委員","kind":"質問・要望","question":"年度途中からのスタートということで、こちらもまだこれから伸びていく事業なのかなと考えています。ぜひこれからも、より一層、この事業の周知に力を入れていただきたいと考えています。例えばＬＩＮＥやしながわこどもぽけっとなどを活用していただければと思いますけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"本事業の周知につきまして、事業開始時に、広報、ホームページ、事業案内チラシの医療機関等への配布等、周知に努めてまいりましたが、加えて、区のＬＩＮＥ、Ｘでも情報を発信しているところです。","voiceIndex":344,"id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６ページ、歳入で特別区税、特別区民税についてお伺いします。今回の補正で、特別区民税が２８億５,８００万円増額になっております。補正後は５３２億３,８００万円です。それに関して、ふるさと納税の寄附金控除額について幾つかお伺いします。これは看過できない状況となっております。そこで、この数字でまず正しいのかということと、数字のことなのでお分かりになる範囲で、正しいのかお伺いします。","respondent":"吉野税務課長","answer":"委員のご指摘のとおりだと思います。","voiceIndex":347,"id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということで、数字が正しいと。なぜ区民税に占める割合を確認させていただいたかと申しますと、今年度の納税控除額の大きさからいうと、世田谷区が１１０億円と、２３区では圧倒的に多額で、マスコミで話題になっていますけれども、問題は区民税に占める割合がどうかということだと思うのです。２３区を眺めてみると、世田谷区は今年度８.６８％で品川区より低いわけです。","respondent":"吉野税務課長","answer":"委員のご指摘のとおり、５０.９億円というのは看過できない状態です。去年なのですけれども、ＳＮＳで、「５０.９億円とは」という部分と、「５０.９億円があったら何ができるのか」というようなことをＳＮＳで発信させていただきました。","voiceIndex":349,"id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、ＳＮＳの効果についてご説明いただきました。まさにそのとおりです。ただ、なかなかもう少し詳しくということになってきますと、やはりホームページというところが必要になってきます。区民の皆様も今、１２万件ということがありましたけれども、自分ごととして考えていただきたい。そして、易しく分かりやすい内容で図解も入れて広報するべきだと思いますが、いかがでしょうか。","respondent":"吉野税務課長","answer":"来年度なのですけれども、特設サイトというものを作成する予定でおります。ここに当然、返礼品も入れるのですけれども、今、委員のおっしゃられた内容につきましても、もう少し分かりやすい内容を加味していきたいと考えております。","voiceIndex":351,"id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"品川区民の方へは数字をお示しするにも、示し方や図解、グラフなども、言い方を変えれば、小学６年生にも分かるようにといったイメージで、ふるさと納税の課題と、区が直面している課題を表現する必要があるかと思います。その辺も活用して、ワンストップの問題や、地方交付税等の問題もありますので、その点も含めて表現していただきたいと思うのですが、改めてもう一度、いかがでしょうか。","respondent":"吉野税務課長","answer":"やはり、何というのでしょうか、この制度自体の周知といいますか、そういったところ。どこが悪いのかといったところも含めて、やはり周知していかなければいけないと考えていますので、分かりやすい内容にしたいと考えております。","voiceIndex":353,"id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問","question":"様々な広報の方法を、今後も、ＳＮＳという一歩踏み込んだところをやっていただいたので、多くの方に周知されたと思います。その一方で、今までいろいろな委員会で問題になっていますけれども、この区民税、税収のマイナス分の要素については、これはまた考えていかなくてはいけないのですが、区民税収のマイナス要素に、今後、区としてどのように対処していくのか、お伺いします。","respondent":"吉野税務課長","answer":"先ほどと答弁が重なってしまいますけれども、今回のふるさと納税についての課題といったところを増やすとともに、あと、品川区としての魅力の発信というところで、いわゆる返礼品といったところの開発をさらに進めていきたいと考えております。","voiceIndex":355,"id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"意見","question":"魅力発信ということは、ずっとお話ししていただいているわけですけれども、近々、令和７年度は、令和６年度の金額を経てどういった方向か、もう少し具体的にお話しいただけるとよろしいかと思います。","respondent":"吉野税務課長","answer":"来年度も同じように、区内の企業にまたご協力いただいて、こういった体験型の返礼品を増やす予定です。それから、あと、物に対しての返礼品も増やしていきたいと考えております。","voiceIndex":357,"id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そして最後に、先ほどお話ししましたが、２３区、そして川崎市やほかの自治体などとスクラムを組んでいくことも非常に重要ですけれども、「品川区は」という一人称で、大変な状態になっていることを、区民の方に訴えていっていただきたいと思います。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":359,"id":"exchange-156"},{"speaker":"松本委員","kind":"質問","question":"障害をお持ちの方などにも減額があるのですけれども、では何で７０歳以上の方には減額しているのかというところについて、まず理由をお伺いしたいのと、私としては、これはこの間の一般質問や、一般質問以外でも聞いたりもしていますが、社会保障関係費が増大していく中で、高齢者の方たちに対する予算は生命・身体に関わるものに集中していただいて、こうしたある意味。","respondent":"宮澤地域活動課長","answer":"区民保養所の宿泊助成です。７０歳以上の高齢者につきましては、１,０００円加算して５,０００円という形になってあります。区民保養所は、区民の保養と健康増進を図ることが目的です。","voiceIndex":361,"id":"exchange-157"},{"speaker":"松本委員","kind":"質問","question":"平日のというところなのですけど、やはり今、日本国内を見たときに大変なのは、日々、平日も働いて、しかも賃金が安いという方たちが大変だと考えていますので、ここはご事情は分かるのですけれども、見直してほしいというのが私の考えです。今後もこうした提言についてはやっていきたいと思います。これは今も同じという認識でよろしいのか、伺います。","respondent":"宮澤地域活動課長","answer":"光林荘の校外学習施設の利用につきましては、おおむね４月下旬から１０月末まで利用されているです。","voiceIndex":363,"id":"exchange-158"},{"speaker":"松本委員","kind":"質問","question":"これは、夏季は林間学校があるので、ほぼ毎日使われているのですけれども、それ以外のゴールデンウイークぐらいから９月ぐらいまでというのは週３日しか恐らく使われていないのではないかと思いますが、ここは事実でよろしいですか。","respondent":"柏木学務課長","answer":"光林荘の使用状況ですが、基本、移動教室は２泊３日で実施しておりまして、その後、順次、各学校が、最終日は重なったりしていますけれども、そういう形で実施しておりまして、週３日かというと、月によっても、その週によっても異なりますけれども、基本は大体。","voiceIndex":365,"id":"exchange-159"},{"speaker":"松本委員","kind":"質問","question":"そうすると、区民保養所といいながら土日が空いているというのはどうなのだろうというところ。さらに言うと、今のお話ですと、４月後半から９月ぐらいまでは使っているということなのですが、一方で、１１月から翌年の３月までは、原則、休業という形になっています。この施設があるのは日光です。紅葉がきれいなところですけれども、１１月から休みを取っているのはなぜなのでしょうか。","respondent":"宮澤地域活動課長","answer":"４月から冬季の部分を含めて、現在、団体での利用というところで限定していますが、今年度に入りまして４月から１２月までの間に、団体の利用で大体、３００名ぐらいが泊まっているという実績があります。その辺は、使っていない時期に利用しています。","voiceIndex":367,"id":"exchange-160"},{"speaker":"松本委員","kind":"質問","question":"今のお話だと、紅葉の時期に団体でも受け入れていないというところは、なぜなのかというのはよく分からないところはあります。問合せがある場合にはこの電話番号をお願いしますと書かれています。このように考えると、これはもう事実上、民間に今やっていただいていますけれども、民間も、これはもう普通の団体客を含めて、受け入れたくないというのが本音ではないかと思うのですが、いかがでしょうか。","respondent":"宮澤地域活動課長","answer":"運営事業者等をヒアリングする中で、実際、正直なところというところで言われておりますのが、やはりコロナ後、なかなかまとまった団体での利用がないと、やはり収支というのが非常に難しいというところは、お声として聞いているところです。","voiceIndex":369,"id":"exchange-161"},{"speaker":"松本委員","kind":"意見","question":"なので、では団体へ拡大していくのかといったら、そうではないというのが今の私の考え方で、このように考えていくと恐らく、敷衍すると、民間事業者もなかなか受け入れ難いということを思っていらっしゃるのではないかと思うのです。これをずっと「区民保養所」と言うと、また少し視点がぼやけてくるのではないかと思いますが、ここはいかがでしょう。","respondent":"宮澤地域活動課長","answer":"そこ以降の部分につきまして、今後の保養所の方向性について課題となりますのは、校外学習施設というところでの利用が多い光林荘というところがありますので、そういったところも含めて検討を進めていくです。","voiceIndex":371,"id":"exchange-162"},{"speaker":"松本委員","kind":"質問・要望","question":"今日の質疑で、ほぼ、やはり子どもたちの教育施設なのかなというところが、ある程度分かったのではないかと思いますので、今後の施設の在り方は、また別の機会でやらせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":373,"id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"６８ページ、新庁舎整備費についてお聞きしたいと思います。ところで、品川区の新庁舎計画はどうでしょうか。令和３年・令和４年の新庁舎整備基本計画における建設工事費は４００億円でしたが、それから２年４か月しか経過していないのに、令和７年２月時点には７０７億円に値上がりしています。当初計画予算から７５％も増えている。教えてください。","respondent":"小林新庁舎建設担当課長","answer":"工事費の想定という観点ですが、今回、予算の中でお示しさせていただいている金額の中で、発注時までのいわゆる上昇率というのは一定程度見込んだ形で予算要求していますので、まず発注という観点で申し上げますと。","voiceIndex":375,"id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"日本経済は、異常な円安が長期間続いたため、インフレの進行が速くなったこともあり、もうじき日銀においては金利を上げ、円高にして物価を抑えると私は思います。今の日本はインフレ経済の上に、建設の工事費バブルの状況下にあるため、新庁舎建設は大変高いという状況ならば、私はこの工事を延期するべきではないかと思うのですが、お考えを教えてください。","respondent":"小林新庁舎建設担当課長","answer":"そういった観点から申し上げますと、新庁舎につきましても、早く着工して早期に竣工させるということが一番合理的だと考えるところです。","voiceIndex":377,"id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"私は今まで、例えば企画部でも何でもそうですが、一生懸命、いろいろな事業見直しをして、スクラップ・アンド・ビルドですか、その見直しをして、お金をきちんと使って、区民のために還元するということを基本としていたわけです。税金でしょう。それが、三百億円、五百億円も増えるだろうと想定できる金額の事業を推し進めるというのは、私は今やるべきではないかと思うのですが、ご見解をお聞かせください。","respondent":"小林新庁舎建設担当課長","answer":"これらを進めていく中では、例えばバリアフリー動線の関係や、あるいは設備機器の老朽化など、これらを根本的に解決するためには、全面的な建て替えというのが必要だと区としては認識しています。","voiceIndex":379,"id":"exchange-166"},{"speaker":"須貝委員","kind":"意見","question":"現在ここにある庁舎も、免震構造、ダンパーをつけて、長くもつように改修していますよね。今ここが、免震診断しても駄目だというなら、もう課長がおっしゃるとおりだと思います。すぐやらないといけない。だって、当初４００億円が、今７００億円。もう８００億円、１,０００億円に向かっています。でも、皆さんの税金を考えたら、私はそこは考え直すべきだと思うのですが、ご見解をお聞かせください。","respondent":"小林新庁舎建設担当課長","answer":"今回の予算の中でも、やはり我々、実施設計を進めていく中で様々広く検討してきたところです。そうした中では、やはりコストというところも非常に大きなポイントでございまして、今回整備していく中で減額案というのもしっかりと考えてきたところです。","voiceIndex":381,"id":"exchange-167"},{"speaker":"須貝委員","kind":"質問","question":"でも、その前に、私は財政部、企画部にしっかりお聞きしたいのです。片一方はやっているではないですか。ところが、これは何ですか。３００億円、４００億円を超えても、「ああ、しようがないですね」。企画部もこういう姿勢でいいのですか。５０億円、６０億円。でも、これは３００億円、４００億円を超えても構わないのですか。企画部もこういう考え方を進めていいのですか。いいのですか。","respondent":"加島財政課長","answer":"金額の面でいろいろご意見をいただいておりますけれども、今、事業中止にかかる金額というのを具体的に申し上げることはできませんけれども、こちらは施工当初からの徹底したコスト管理、それから安全を確保した上での効率的な施工の実施等によりまして。","voiceIndex":383,"id":"exchange-168"},{"speaker":"須貝委員","kind":"質問","question":"それは何でですか。７５％も金額が増えたらやめます。でも、何で役所は進めるのですか。それは自分の金ではないからですか。税金である予算は、やはり私は有効に使うべきであると思うし、基金がある、お金があるからといって、３００億円、４００億円増えても、膨大な金額でも払ってまで建設しなくてはいけない、進めなくてはいけないという考え方というのは、私は区民にはっきり説明するべきだと思います。","respondent":"小林新庁舎建設担当課長","answer":"いろいろご意見をいただいたところですけれども、やはり庁舎の喫緊の課題を速やかに解決することが区民サービスの向上にもつながるところですので、当然、お金を無駄にしながら工事発注するつもりはございませんけれども、適切な庁舎を。","voiceIndex":385,"id":"exchange-169"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１１５ページからの国民健康保険、後期高齢者医療、介護保険の特別会計について伺いたいと思います。２３区の特別区長会の国民健康保険の見直しに関する提言の中でも、子どもの国民健康保険料軽減について国に求めています。国は適切ではないと言っていますが、禁止はしていないと思いますけれども、禁止はしていないという認識でいいか、確認させてください。","respondent":"池田国保医療年金課長","answer":"保険料の減免については、国では禁止していないということでのお答えをしているところでございまして、保険料の賦課につきましては、国の法律によりまして基準があります。それを超えての各自治体での保険料の賦課はいけないということは決まっているところです。","voiceIndex":388,"id":"exchange-170"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、法定外繰入れでは子どもの国民健康保険料を無料化できないと区がおっしゃってきたので、第７７条を示して、できるのだということを、ずっと求めてきたところです。ですので、禁止はされていないということで、できるということです。できるけれども、やらないと判断しているということですけれども、なぜなのでしょうか。これは国がやるべきだと考えているということでしょうか。伺います。","respondent":"池田国保医療年金課長","answer":"これは、先ほどから委員のおっしゃるとおりではありますけれども、あくまでも、災害やそういう必要などで収入が減少した方々に、条例を定めてということになってありますので、私どもは、こちらのものについては国がやるものですので。","voiceIndex":390,"id":"exchange-171"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"様々理由は述べられているのですけれども、国民健康保険法の第７７条ではできるということになっています。これは、年間１人６万５,６００円です。ですので、改めて、禁止もされていませんし、自治体独自で引き下げているところも増えていますので、区としても独自の無料化を、そして軽減策を、子育て支援としてしていただきたいと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"保険料につきましては、まず、なぜ未就学児の保険料について５割しか軽減しなかったかというところがありますけれども、こちらは国民健康保険制度自体が相互保障の精神に基づきまして、お子様についても保険を使っての制度ということでやってありますので。","voiceIndex":392,"id":"exchange-172"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区独自でできますのでということを何度も述べていますので、ぜひ実施していただきたいです。社会保障は権利です。それは森澤区長も施政方針でおっしゃっていると思いますので、その立場に立って、ぜひ引き下げ、そして無料化を進めていただきたいと思います。これは求めておきたいと思います。背景には、認定が軽く出るということがあるのではないかと思いますけれども、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"第８期においては、特にコロナの影響で、施設サービス費を中心に給付費が伸び悩んだというようなこともありますので、この辺りは今後、コロナが明けて、施設サービス給付費も伸びているというところで、今後は見込みが増えていき。","voiceIndex":394,"id":"exchange-173"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"認定が軽く出るということは、私たち共産党としてもずっと指摘してきました。この国平均で見ても、要支援の出方が、国全体では２８.２％なのが、品川区だと４２％も要支援の方が出るのです。身の回りでも少し、あり得ないような判定が最近結構出ていると感じられる」という声も出ています。ですので、ぜひ、しっかりサービスを使っていただきたい。そのためにも認定はしっかり出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":396,"id":"exchange-174"},{"speaker":"大倉委員","kind":"提案","question":"１２ページ、しながわ水族館リニューアル実施設計委託の債務負担の廃止について、５５ページ、給食運営費について、５８ページ、ふるさと納税寄附金について、７７ページ、障害者グループホーム整備助成等について伺います。今後、先ほどもご提案がほかの委員からありましたが、区長からの発信や、様々、区民により分かりやすく周知していっていただきたいと思いますので、ぜひよろしくお願いいたします。","respondent":"大友公園課長、柏木学務課長、吉野税務課長、佐藤障害者施策推進課長","answer":"その中において、一回立ち止まって、運営を含めて整備する手法というところを改めて検討するというところにおきまして、その検討結果が出次第。加えて栄養士などの研修等を実施するなど、様々な取組を総合的に進めていきたいと考えています。企業版のふるさと納税なのですけれども、こちらは、いわゆる地方交付税、財政の制度の一つであります。こちらは、新規設置による施設整備への補助についてというところでの整備助成になりますが。","voiceIndex":398,"id":"exchange-175"},{"speaker":"大倉委員","kind":"質問・要望","question":"先ほども、これもほかの委員からお話がありましたけれども、施設を運営していく中で、重度障害者の方への支援が進むように、新しく制度をつくっていくというお話だったのですが、以前も、昨年か、代表質問や予算特別委員会などでも、重度障害者のグループホーム等、障害のある方が入れるような施設などもぜひ進めていっていただきたいということで。","respondent":"柏木学務課長、松山障害者支援課長","answer":"これまでもいろいろ、おいしい給食は当然、供給していますので、ただ今後、それをさらにレベルアップできるように、研修等を通じて総合的に進めていきたいと考えています。入居者数と障害支援区分に応じまして、受け入れた事業所へ運営費を助成するものです。こちらの助成を通じて、より重度障害者の方が入居促進できるように進めてまいります。","voiceIndex":403,"id":"exchange-176"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、順番を入れ替えまして、８５ページ、病児保育新規開設運営補助経費、そしてもう一点は、８３ページ、私立幼稚園保育料助成から伺ってまいります。具体的な内容を教えてほしいということで、相談者の方に改めて伺いましたところ、ご友人の中からかなりたくさんの意見を集めていただきました。別の方です。選択肢ですから、否定するわけではないのですけれども。今、強く要望されている皆様。","respondent":"中島保育施設運営課長","answer":"病児保育に関するお尋ねです。改めて貴重なご意見をたくさんいただきまして、この事業の重要性を強く認識したところです。ご質問の、まず協議状況につきまして、３施設と今、協議させていただいています。","voiceIndex":408,"id":"exchange-177"},{"speaker":"あくつ委員","kind":"提案","question":"このようなご意見もいただきました。確認しますと、世田谷区では、病児・病後児、両方対応の施設が９つ、病後児のみ対応の施設が２つありますけれども、世田谷区の公式ホームページで、全ての施設の事前登録がスマートフォン・パソコンによる電子申請で一括で可能になっています。これは、利用者の負担軽減のために、利用の一括登録という導入の検討を、ぜひお願いしたいのですけれども、いかがでしょうか。","respondent":"中島保育施設運営課長","answer":"ただ、今ご提案のございました、利便性の向上というところも重要な観点ですので、そちらにつきましては、病児保育施設の意見も聞きながら、今後、課題も把握しながら検討してまいりたいと思います。","voiceIndex":410,"id":"exchange-178"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ進めてください。次に、予約システムについても伺います。文京区では、こうした課題に対応するために、昨年６月に病児保育予約サービスを導入しました。それが売り文句になっています。利用者目線に立っていただいて、先ほどもありました、施設とぜひ協議をしていただいた上で、先ほど申し上げた一括登録とともに、手軽な予約システムの導入をご検討いただきたいと思いますが、いかがでしょうか。","respondent":"中島保育施設運営課長","answer":"現状、実際にお預かりする際には、クリニックで前日に診療してもらったりという形で、丁寧に今、受入れをしています。先ほども同じですけれども、利便性の向上・改善につながるというご提案ですので、病児保育施設との意見交換を通じまして、重ねて検討してまいりたいと思います。","voiceIndex":412,"id":"exchange-179"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私もたくさんの意見を頂いて、今日も一目瞭然で、こういう要望が今日こんなに多数出るということは、恐らく区内の中で多くの声があるということは間違いないことだと思います。昨年ご要望させていただいて、私立幼稚園の保護者補助金については、施政方針の中で区長にも取り上げていただきましたように、区分の差なく、所得制限なく、一律４万円ということで、これでほぼ実質無償化になったのかなと思います。","respondent":"芝野保育入園調整課長","answer":"一方、これまで園におきましてご負担をおかけする要因となっておりました事務的な負担につきましても、今回の所得制限の撤廃によりまして大幅に解消されるというような見込みになりましたので、保護者の経済的負担の軽減や利便性というのを促進する意味からも。","voiceIndex":414,"id":"exchange-180"},{"speaker":"あくつ委員","kind":"質問・要望","question":"みんなが足並みそろえて全ての園がやらなければいけないということではないということも確認していますので、手を挙げて、こういったことでまた保育園と差がついて、それで私立幼稚園を選ばないという保護者の方がいるというご主張もありますので、新制度になった幼稚園については、それはそもそもやらなくていいということになっていますけれども、今、１７園のうち今年２園が新制度に移りますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":416,"id":"exchange-181"},{"speaker":"西村委員","kind":"質問","question":"順番に、６５ページ、基金積立金、その後、１０ページ、民生費、児童福祉費から、子どもの未来応援基金について伺ってまいりたいと思います。児童福祉費４９億円余の増額の主となるものは、公定価格の上昇分と、子どもの未来応援基金の増額だと理解しております。","respondent":"佐藤保育事業担当課長","answer":"国の公定価格の増額における、背景ですけれども、こちらは保育士の処遇改善というのを国が実施していることによりまして、公定価格の単価が増加されたものです。施設ごとの増額です。区内の私立保育園経費におきましては、運営費を約８億円ほど増額しています。","voiceIndex":418,"id":"exchange-182"},{"speaker":"西村委員","kind":"質問","question":"保育士処遇改善のための大きな補正と、また、さきの文教委員会で子どもの未来応援基金についてのご報告がありましたので、こちらの点を伺ってまいりたいと思います。基金の活用として、大学生奨学金、居場所確保事業、ヤングケアラー事業などの事業を選ばれた理由と、区民の方からいただいた２５億円という大きなご寄附の活用に向けての使途や計画をお聞かせください。","respondent":"藤村子ども育成課長","answer":"そういった中での今回予算編成でございまして、より大きい視点から子育て支援を考えまして、制度や分野のはざまで、支援から抜け落ちている子どもたちにスポットを当てて、利益を享受できるような施策を中心に、特定財源も考慮しつつ検討いたしました。","voiceIndex":420,"id":"exchange-183"},{"speaker":"西村委員","kind":"意見","question":"制度や分野のはざまで支援から抜け落ちている子どもたちを対象とした事業ということですけれども、既存の制度で対応し切れない課題に焦点を当てるという、基金ならではの柔軟性を活かした考え方だとは思うのですが、例えばヤングケアラー事業や居場所確保事業などは、制度や分野のはざまが課題として優先度が高いと判断されたのか、区内事業の中で、この基金をどの事業にどう使うか。","respondent":"藤村子ども育成課長","answer":"廃止する奨学金貸付基金についてですけれども、こちらは、経済的に困難を抱える家庭の子どもが進学の道を諦めることがないように支援するという目的から設置された基金です。","voiceIndex":422,"id":"exchange-184"},{"speaker":"西村委員","kind":"質問・要望","question":"この奨学金貸付基金の意思を、ぜひ引き継いでいただきたいと思います。この基金ですけれども、大学の奨学金に使えば、最大４学年で年間２億４,０００万円程度の算出になると思います。対象学部の拡大、ほかの事業も始めればさらに早くなる可能性がありますが、基金残高を少しでも維持するために方策があれば、お考えをお聞かせください。","respondent":"藤村子ども育成課長","answer":"ご指摘のとおり、このままいくと、基金の残高というのが十数年で枯渇する状況になりますが、今後の充当事業というのは、各年度の予算編成の中で検討しているものですが、まず基金の財源というのが枯渇することのないように、１点目として。","voiceIndex":424,"id":"exchange-185"},{"speaker":"西村委員","kind":"質問・要望","question":"運用益の確保やクラウドファンディングも組み合わせて、持続可能な仕組みをぜひ構築していただきたいと思いますが、寄附見込みや、クラウドファンディングで賄える規模なのか、寄附を集めるのか、そんなに集まるのか、どうなのかと思いますが、その辺りのお考えがあればお聞かせください。","respondent":"藤村子ども育成課長","answer":"ただ、今、子育て応援課で実施しておりますクラウドファンディングでも、毎年、おおむね寄附の金額が増えてきている形ですし、今、区が積極的に、各種無償化など、先進的な子育て施策に取り組んでおりますので。","voiceIndex":426,"id":"exchange-186"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区は、区民や企業からの寄附も見据えておりますし、ふるさと納税の仕組みも取り入れております。クラウドファンディングもまだまだ様々に工夫できると思っておりまして、ぜひ、区の姿勢に賛同してくださる機運の高まりを目指していただきたいと思います。区の基金積立てに関する考え方と今後の見通しをお知らせください。","respondent":"加島財政課長","answer":"予算書に記載の現在高につきましては、あくまで予算編成時点での経過点ですので、基金現在高につきましては、その目的に応じて積立て・繰入れを行っておりますので、現在高のみをもって即座に財政の悪化を示すものではないと認識しております。","voiceIndex":428,"id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7001#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":132863,"voices":433}},{"id":"r07-20250305-3","meetingId":"r07-c-budget","date":"2025年3月5日","dateIso":"2025-03-05","committee":"予算特別委員会","time":"午前 ９時３０分～午後 ７時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度品川区一般会計予算","agenda":"令和７年度品川区一般会計予算","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"ここで動議をします。令和７年度の予算なのですけれども、これが公になったのは２月５日の区長のプレス発表です。しかしながら、２月５日の朝刊に、ここに、皆さん、見ていると思うのですけれども、朝刊に、もう既にかなり詳しい情報が公表されております。その際に、再三、２月５日にプレス発表が終わるまでは公表しないようにという申し入れがありました。この説明をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"石田（し）委員","kind":"確認","question":"理事会で、西本委員がこうやって動議を出されて、それについてご本人からの意向は聞いたのでしょうか。それと、そもそもこの動議を受けるか受けないかという判断も誰がされているのか。それも本人に確認をしたのか。本人の意向も何も確認しないで、理事会でこうしましたから進めますというのは、私は、議会として、丁寧な対応ではないと思いますけれども、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問","question":"そうであれば、初めにその説明をすればよかったのではないですか。我々は何も聞いていないわけです。だから、私はそこをきちんと説明をしていただいてからスタートすればいいのではないですかという話ですから、ぜひそこは丁寧にしていただきますけれども、いかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"提案","question":"そこは丁寧に説明すればいいのではないですかというのが私の提案です。それができないのであれば、事前に、理事会ではこういうふうに決まりましたという報告も各委員にすればよかったではないですか。思わないですか。全然それはいいですけれども、今後のことも考えて、やはりしっかりそこは丁寧にしたほうがいいのではないですかというのが私の発言です。なので、丁寧に説明してくれというのが私の主張です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"ですから、今のお話は、無所属の方が８人いらっしゃる方々に、そのときの説明をしていないということがあるのであれば、しっかりそれは、これから私も判断をするかもしれないけれども、今の段階では、全てこういうことがあったときは、理事会でしっかりそれを議論していきましょうというのが、私の今の理解は、そこの私の委員長としての理解、それが間違っていると、今、違って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"確認","question":"そもそも動議が出されて、その動議をまずどうするかということも確認をしなければいけないですね。それは理事会でもいいです。間違っていますか。それもなく、では、理事会で全て決めますと言って、ここに今いる無所属議員は、何もなく、何の説明もなく、そうですかと進めるかと言ったら、そうではないではないですか。だから、私はきちんと進めたほうがいいですよということを。皆さん、どう思いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それは今、そういう討論をするのだったら私はずっとしますけれども、その思いがほかの人たちにもあるのではないかなと思っているから、別に代表してと言って、恩着せがましく言っているわけではないけれども、現実にそういう声を私は聞いているから、今、発言をしているので、そこはぜひ、そこに議長もいらっしゃいますから、そこはぜひ確認をしていただきたいと思いますけれども、これを最後にしますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"統計は推測する上でも大きな手がかりとなりますので、また幾つか教えてもらいたいと思います。区民税を納めますと、区民の収入と、また、少し高齢化世代の話をしていきたいので、その世代との関連性について教えていただければと思います。","respondent":"吉野税務課長","answer":"課税所得７００万円以上の方なのですけれども、３０歳ですと１,７４８名増、４０歳代ですと１,１００名増、５０歳ですと２２８名増となっている現状です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"世帯との関連性をお聞きしたかったので、そこら辺、分かれば教えてください。","respondent":"吉野税務課長","answer":"失礼いたしました。世帯でいきますと、１人世帯の数が大体５８％ほど、１３万８世帯あります。２人世帯が４万７,０００世帯、２０％余の状況です。","voiceIndex":23,"id":"exchange-009"},{"speaker":"こしば委員","kind":"質問","question":"先ほど触れました総合実施計画の改定素案を見ましても、多様な世代の定住性向上を図るため、品川区で生まれ育った人、また、転入してきた人が、品川区に愛着を持ち住み続けていきたいと思えるような環境をつくり出していくとこの実施計画にも書かれておりますが、この中で多様な世代には当然にＤＩＮＫｓという方々も含まれると思いますが、その辺り、教えていただけますでしょうか。","respondent":"崎村企画課長","answer":"委員からは、なかなか行政の支援が必要ない世帯ではというお話がございましたけれども、そういった夫婦のみの世帯で行政サービスはどういうことが必要なのか、ニーズがどうなのかというところを、これからも行政としては把握していかなければいけないですし。","voiceIndex":25,"id":"exchange-010"},{"speaker":"こしば委員","kind":"質問","question":"先ほど、ＤＩＮＫｓの世帯について、大体１４.７％、１割強いらっしゃるというご回答がございました。ＤＩＮＫｓの方は夫婦共働きですので、帰りが遅くなってしまいます。でも、少しお酒も飲みながら、おいしい料理をすることで１日の疲れを癒やす、そういう方も当然いらっしゃると思います。その辺りで、また、人口増加というところで、将来の見通しについて、教えていただければと思います。","respondent":"崎村企画課長","answer":"生活満足度についても、品川区については、今回の世論調査でもかなり高く出ておりますので、こういった生活環境面、また、区としても力を入れております子育ての負担軽減、子育てのしやすさですとか、教育環境、様々区としての魅力を発信することによって、そういった人口を。","voiceIndex":27,"id":"exchange-011"},{"speaker":"こしば委員","kind":"質問・要望","question":"ぜひ招き入れていただきたいと思います。それは大変高く評価をします。この課題解消のため、区の取組を求める声もあると思います。当然、現状にそういった住宅、要介護者に向けた施策の展開もされておりますけれども、そういった施策を通じたものをＤＩＮＫｓの方にも、あらかじめ周知をしていくことも必要ではないかなと思いますが、その辺りのお考えを教えていただきたいと思います。","respondent":"崎村企画課長","answer":"そういったところで、品川区の施策としては、誰もが年をとって高齢者になるというところでは、来年度、終活の支援の取組として、社会福祉協議会が実施しているサービスについて無償化を図るですとか、また。","voiceIndex":29,"id":"exchange-012"},{"speaker":"こしば委員","kind":"質問・要望","question":"引き続き取り組んでいただきたいと思います。そういった取組が、シティプロモーションではないですけれども、また新たなこういったＤＩＮＫｓの方々の今後の将来に向けて、品川区で住んでいきたいと思えるようなことにつながってくると思いますので、引き続きよろしくお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-013"},{"speaker":"新妻委員","kind":"確認","question":"改めて、本日もどうぞよろしくお願いいたします。６１ページ、区民斎場使用料からなぎさ会館、１３５ページ、ＨＰＶワクチン男性接種補助事業、１７１ページ、リサイクル活動推進事業、時間がある限り伺ってまいります。最初に、今回、なぎさ会館が廃止を検討していくということを表明されたのは、この事務事業評価の結果についてが初めてかどうかということを確認させてください。","respondent":"築山戸籍住民課長","answer":"なぎさ会館の廃止の方向性については、今回の事務事業評価の結果が最初です。","voiceIndex":33,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"今回初めてこのことが公表されました。１つの区の施設が廃止していくということはとても大きいと考えていますので、どのような経緯でこの結果が出されて廃止の検討が示されたのか、具体的に１つ１つお聞きしたいと思います。そして、臨海斎場の拡充の規模をお聞きします。最後に、経費増加を鑑みて、本事業は３年以内に廃止を検討とありますが、具体的にどのように検討が進められていくのかお知らせください。","respondent":"築山戸籍住民課長","answer":"最後に、今後の進め方です。進め方につきましては、地域の方ですとか、斎場関係者等、外部の委員の方を入れまして、地域や事業者の意見を踏まえ、検討会を実施し、丁寧に進めていきたいというふうに考えております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"細かくご答弁をいただきまして、ありがとうあります。今後の進め方が非常に大事かと思うのですが、３年間かけて検討ということですので、これから地域の方にもお知らせをしていきながら、検討会を立ち上げていくということになるかと思いますが、具体的にいつぐらいに検討会を立ち上げてということをお考えなのか。そしてまた、議会への報告はどのようにしていただけるのかお知らせいただきたいと思います。","respondent":"築山戸籍住民課長","answer":"今後の検討会の開始時期等についてです。議会に、まずは臨海斎場の現状、課題等につきまして、区民委員会でご報告をさせていただきたいと考えております。検討会につきましては、早ければ年度初めの４月以降にスタートさせたいと考えています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"丁寧に行っていただきたいと思いますが、３年間という検討期間を示されましたけれども、場合によっては、早く閉鎖ということもあり得るということを確認させていただきました。丁寧に進めていただきたいことを要望いたしまして、この質問を終わりたいと思います。次に、ＨＰＶワクチンの男性接種の周知についての部分だけ少し確認をいたします。","respondent":"五十嵐保健予防課長","answer":"男性のＨＰＶワクチンの１月末現在の接種につきまして、まずご説明します。１回目の接種は１５９名、２回目の接種は１３０名、３回目の接種は４４名となっているところです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日もよろしくお願いいたします。最初に、住民情報システム運営費に関連して質問をいたします。同性カップルの住民票の続柄に、夫・妻（未届）と記載している自治体がある中で、品川区としては、１０区の区長とともに同性パートナーに関する権利や制度等の検討を求める要望書を総務省および厚生労働省に申し入れを行ったと把握しております。","respondent":"築山戸籍住民課長","answer":"こちらですが、昨年９月に、事実婚と同様の表記をした長崎県大村市に対して、国が住民基本台帳および住民基本台帳事務処理要領によりできる限り統一的に記録がされるべきとされていることから、再考を求めるよう国の見解が示されました。","voiceIndex":42,"id":"exchange-018"},{"speaker":"ひがし委員","kind":"質問・要望","question":"昨年の決算特別委員会でも同様の質問をさせていただきまして、まずは区として第一歩を踏み出してくれたということはうれしく思っております。今回、申し入れを行った区と、今後も継続して、同性カップルの権利獲得に向けて行動を起こしてほしいと考えていますが、今後の展開についてもお聞かせください。","respondent":"築山戸籍住民課長","answer":"今後の展開です。戸籍や住民票の事務につきましては、全国統一的な運用が求められるものですので、区が独自の制度運用をすることは困難ですけれども、国の動向に注視するとともに、他自治体とも情報共有を図りながら、区としてできることについて考えていきたいと考えております。","voiceIndex":44,"id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回の決算特別委員会でも区としてできる取組をということで幾つか要望していますので、その点については、総務費の際に再度確認をさせていただきたいと思います。次に、子どもの居場所運営費についてお伺いいたします。今回の事業について、学校サイドにどのような調査を行い、どのような結果が出て実施するに至ったのか、また、モデル校の３校はどこを予定しているのか伺います。","respondent":"藤村子ども育成課長","answer":"全体の校長会ベースというところですとか、そういった場で２回ほどしっかり課題を伺った上で、その解決策も提供させていただいて、ご説明の上、進めているような形になっております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問・要望","question":"このモデル校について、どうやって決めているのか。スケジュール感、現在の進捗についてもお聞かせいただきたいと思います。朝の居場所とともに、朝食支援も大きく報道されておりました。配置の基準としては、校門に１人、居場所に２人、委託業者を配置するとなっておりますが、朝食の提供は誰が行うのでしょうか。利用する生徒の想定人数についてもお伺いいたします。","respondent":"藤村子ども育成課長","answer":"ですので、学校の規模感ですとか、そういったところを配慮して決めていきたいというような形にしております。こちらは試行なので、例えば、トラブルがあった場合に対応していくというところもありますので、庁舎等からの距離感も踏まえて決定していきたいと考えています。","voiceIndex":50,"id":"exchange-021"},{"speaker":"ひがし委員","kind":"質問","question":"朝の朝食の支援については、この事業に関わらず食事を提供する際には窒息事故の防止、また、アレルギー発生時の対応を事前に検討を進めていく必要があると考えております。食の提供に対する事故発生時の対応はどのようになっているのかお伺いいたします。食事提供する際のエピペンの配置、使用方法の指導も必須だと考えていますが、区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"そういった危機対応のところにつきましては、すまいるスクールのほうでノウハウがありますので、そちらを今回の委託会社とも共有していければというふうに考えております。","voiceIndex":52,"id":"exchange-022"},{"speaker":"ひがし委員","kind":"質問","question":"委託先がもしどこか決まっているのであれば、そちらもご共有をお願いいたします。小一の壁に対して対応するならば、参加人数によって増員も検討する必要があると考えますので、その点について区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"例えば、正門から入った中で昇降口が３つに分かれている学校があるとか、もちろんそのまま朝の居場所にストレートに行ける場所も様々ありますので、そういった状況を考慮しつつ、各学校の個別の状況に対応して、増員等も柔軟に考えていきたいというふうには考えております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"ひがし委員","kind":"確認","question":"委託先はこれからということで確認をさせていただきました。冒頭にも言いましたけれども、子どもの安全を第一に考えるためにも、現場の声を聞いていく必要があると思いますので、学校側としっかり協議をした上で検討を進めていただくようにお願いいたします。時間がありませんので、後半の部分については、またほかの款のときに質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"同様に、レクホールのほうも、手元で音量が変えられないというような状況で、こちらも少なくとも点検が必要なのかなと思っていまして、これ、やはり使用料を払って使っているわけですから、しかも高齢の方も今多いわけで、聞こえる、聞こえないかというのは本当に大事な問題だと思っていまして、伺いたいのですが、中小企業センターの大会議室、レクホールなどで。","respondent":"小林地域産業振興課長","answer":"ご指摘のようなご意見もございましたが、我々がふだん聞いているご意見として、常にそういう声があるというものではございませんけれども、今お話しにありましたように、いろいろな利用者の方、高齢者の方も含めていらっしゃるということですので。","voiceIndex":59,"id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"特に３階の大会議室です。こちらが普通に話していても、高齢者の方は声が通らない、拾えない、そういう集音性になっているので、必要性があるかどうかということは確認していただく必要はあると思います。次に、自衛官等募集事務に関連して、１月２６日にしながわ水族館で行われた自衛隊防災フェアについて伺いたいと思います。ここで１月２６日に自衛隊防災フェア、自衛隊防災フェアですから。","respondent":"大友公園課長","answer":"自衛隊防災フェア、１月２６日に実施されましたものなのですけれども、主催は自衛隊となっています。","voiceIndex":61,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"後援の有無は、あるのかどうかお伺いしたいのですけれども。自衛隊からの許可申請の理由と、区はなぜ使用許可してきたのかというのは一部ありましたけれども、理由や経緯など、補足があれば伺いたいと思います。併せて、当日、自衛官募集のチラシやグッズの配布などはあったのか伺います。","respondent":"大友公園課長","answer":"行われた場所です。こちらは、しながわ水族館の売店の上部にある建物にスペースがあるのですけれども、そちらのスペースを使っているというところ。水族館の前のところのイベントスペースを使って実施をしたものです。","voiceIndex":63,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"ＶＲ体験と言いますけれども、具体的に内容を伺いたいと思います。戦車に乗っているという話も聞きましたので、そこら辺の内容をお伺いします。迷彩服の試着と防災意識向上とどのような関係があるのか伺います。","respondent":"大友公園課長、伊藤災害対策担当課長","answer":"こちらは、ふだん自衛隊員にしか体験できない救助や物資を届ける際の降下体験および東日本大震災においても派遣されました特殊車両である戦車内部のＶＲ体験をすることで、自衛隊の防災活動をより身近に感じ。ただいまの答弁に加えまして、区民の防災意識の向上ということでは、やはり自衛隊の皆さんは、災害時にも防災活動に活躍されるということもございまして、この部隊で一緒に活動されたと伺っております。","voiceIndex":67,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは、歳入全般で事務事業評価、１５６ページ、財政調整基金繰入金、１６７ページ、広告料収入についてお伺いいたします。いろいろ工事の関係とか、決して事務事業評価で減ったものではないものもあるかと思いますけれども、はっきりと事務事業評価で削減できたなと分かるものだけでも、ぜひお示しをいただきたいと思っているのですけれども、この点はいかがお考えでしょうか。","respondent":"吉岡政策推進担当課長","answer":"区民への透明性というところと、職員の負担軽減、こういった部分も兼ね合いながら、引き続き分かりやすいお見せの仕方については工夫をしていきたいというふうに考えております。","voiceIndex":71,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。ですので、区民にも議会にも分かりやすくするためにも、ホームページに掲載されている事業の最後辺りに、事務事業の名前、小事業名を記載していただくか、また、もっと丁寧なのは、事務事業評価のページのＰＤＦにリンクをつけていただきたいということなのですけれども、そうしたことについていかがお考えでしょうか。","respondent":"吉岡政策推進担当課長","answer":"区民の皆様に事務事業評価の結果を分かりやすくお示しする、これは非常に重要なことだと考えています。そういったシステムの改修ですとか技術的なところもありますので、どのようなことができるかは、引き続き検討していきたいと思います。","voiceIndex":73,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"財政調整基金についてお伺いいたします。理由としまして、昨日の令和６年度最終補正のところでもご答弁があったとおり、本日でも歳入のところでお話があったとおり、特別区民税などの税収増ということも１つ理由なのでしょうか。すなわち、財政調整基金をつくらなくても、予算は今回つくれたということなのでしょうか。そうしたら、今、比較的余裕のある財政状況なのかをお伺いいたします。","respondent":"加島財政課長","answer":"財源に余裕があるかというところなのですけれども、今回、確かに区民税の伸び、それから特別区交付金の伸びがございましたので、今回、２,３４７億円の予算を組むことができたというふうに考えております。","voiceIndex":75,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした税収の伸びがあったです。ただ、区民としては、本当に今、話題になっておりますけれども、せっかく働いて給与を得ても、税金で大きな負担があると、手取りが少ないというような状況がありまして、税金を取り過ぎではないかという声も出ておりますけれども、そうした余裕分はぜひ区民へと還元をしていただきたいと考えております。その点、いかがお考えでしょうか。","respondent":"崎村企画課長","answer":"今回の予算の中でお示し、施政方針でも示している５つのライフステージのご紹介がございましたけれども、これらの施策は、誰しもが必ず必要になってくるサービスについて、行政として、無償で、また、所得制限なく提供するというものです。","voiceIndex":77,"id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"ただ、５つのライフステージに当てはまるまで待てというわけにはいかず、それで一生懸命手取りが増えない中、納税している方もいらっしゃるので、ぜひ行政サービスの在り方として、そして、一部の対象者の方だけに税金から得た行政サービスを提供するということは、やはり一定の限界がこれから出てくるのかなと考えていますので、区長の考えられた５つのライフステージというのは。","respondent":"加島財政課長","answer":"そういったものと合わせますと、区といたしましては、区民の皆様にあまねく必要なサービスを提供していくために、今の収入が欠かせないと考えておりますので、一律、一足飛びに減税とは今は考えておりません。","voiceIndex":79,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。この件は今回これくらいにして、続いて、広告料収入なのですけれども、端的に言うと、ネーミングライツです。ネーミングライツは、ぜひこれは本腰を入れて検討すべきかと思います。税外収入は、やはりふるさと納税の流出分をカバーするためにもやっていただきたいと考えています。例えば、しながわ水族館で導入するなどありますけれども、ネーミングライツについて、いかがお考えでしょうか。","respondent":"加島財政課長","answer":"１つの収入の確保手段として依命通達にネーミングライツの例を出させていただいたところです。委員から、しながわ水族館という例もいただきましたけれども、今後何ができるかということは考えていく余地はあるかなと考えています。","voiceIndex":81,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"１３１ページのとうきょうすくわくプログラム推進事業補助金、１６１ページの過料から質問をします。次年度は、６,７５０万円の補助金を利用予定となっておりますが、こちらは何園分か内訳を教えていただきたいと思います。区立幼稚園の実績報告が２月、報告についてはホームページで公開されるということでしたが、こちらのスケジュールも教えてください。","respondent":"中島保育施設運営課長","answer":"ホームページにつきましては、幼稚園の件でお尋ねいただきましたが、保育園も含めまして、３月の下旬には公開していきたいというふうに考えてあります。","voiceIndex":84,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"聞き方が悪かったかもしれないですけれども、何園分、施設数を教えていただければと思います。ホームページでの公開について、分かりました。事例を動画で紹介しているものを見かけまして、東京都のユーチューブチャンネルでも他区の事例が紹介されていたのですけれども、品川区でもそういった紹介をしていく予定でしょうか、教えてください。","respondent":"中島保育施設運営課長","answer":"当初、令和６年度は８６園で予定しておりましたので、それより１４園増えているところです。","voiceIndex":86,"id":"exchange-036"},{"speaker":"せらく委員","kind":"確認","question":"合計１００園になるということで確認いたしました。乳幼児の施設でいうと、私立幼稚園と認可外保育施設で制度利用は区の予算としては、区でまとめているものとしては入っていないと思うのですけれども、園独自で利用されたなどの実績は把握されていますでしょうか。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園についてですが、こちらは東京都が直接所管をされている事業ですので、区としては、実施を周知はしたということは聞いているのですけれども、どの程度の園が参加されているのかについては把握しておりません。","voiceIndex":88,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。こちらは大丈夫です。過料について質問していきます。客引き行為等防止過料についてなのですけれども、こちらは歳入のところに記載があるものなので質問させていただきたいと思うのですが、過去に過料を徴収したことがありますでしょうか。取り締まる方法について、誰がどこで、時間帯、何時くらいで行っているのか、そういうところの想定を伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"しかしながら、今、段階を踏んでのことですので、いまだこれまでに徴収実績はございません。時間帯につきましては、おおむね１８時から２２時までの間、適宜行っている状況になっております。","voiceIndex":90,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"はい、分かりました。こちらは条例で定めていて過料を示しているから、毎年予算案にも載ってくるものなのかなという認識なのですけれども、間違っていたら教えてください。この条例の制定のきっかけと、あと、過料を定めているところの理由はお聞きできますでしょうか。","respondent":"河合生活安全担当課長","answer":"歳入のほうに記載されておりますのは、委員おっしゃるとおり、条例で定めておりますので、１件というところで計上しているものです。","voiceIndex":92,"id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"法令の規制がかからない部分を区でやっているということなのですけれども、区でもやったことで、発生件数だったり、区民からの意見に変化がありましたでしょうか。","respondent":"河合生活安全担当課長","answer":"区の条例に基づく規制等の効果といいますか、苦情等の件数なのですけれども、盛り場においてサポート隊の効果だけではないのですけれども、警察の取り締まりも合わせまして、都内の盛り場において、しつこい客引きの数とか、料金のトラブル。","voiceIndex":94,"id":"exchange-040"},{"speaker":"せらく委員","kind":"確認","question":"そういうことですので、承知しました。事項別明細書を見ていると、令和４年辺りから、迷惑な客引き行為が後を絶たないというふうに書いてありましたので、そういった変化があった、区民の安全を守れるようになっている、周辺環境の改善が見られるということを確認できましたので、これで質問は終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、１０１ページ、感染症予防費、時間があれば、同ページの地域生活支援事業費についてお伺いいたします。１点目に、感染症予防費についてお伺いいたします。ジョン・スノウは、１８４８年のロンドン中心部のコレラ流行で、死亡者の住居の分布を調査し、汚染源らしき井戸を地図上で同定し、問題の井戸を周辺住民が使用しないように井戸の把手を除去し、流行を収束させました。","respondent":"五十嵐保健予防課長","answer":"ホームページ等では、区内の感染症の発生状況を品川区内の医療機関から報告いただく感染症法に基づく感染症発生動向調査を実施しておりますが、その結果を毎週更新して発信しているところです。","voiceIndex":98,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。２０２４年４月２６日の読売新聞の香川県内の病院における面会制限に関する記事、「コロナ５類移行から１年、主要８病院で面会制限続く…明確な指針なく、専門家「国も検討すべき」」から一部引用します。患者本人やその家族の意見を聞く場を設ける。非常時の感染症対策についてもお伺いします。平時から換気への意識および空気清浄機を含めた避難所の環境整備が求められる。","respondent":"五十嵐保健予防課長、羽鳥防災体制整備担当課長","answer":"そこで、院内感染対策に留意しつつ、面会を実施する流れの例示を示し、可能な範囲で工夫して面会の対応を検討するよう通知をしているところです。区内の主要医療機関の面会制限の現状につきましては、区としては把握しておりません。来年度以降、導入を予定しております温風機能つきのサーキュレーター、こちらは空気清浄機能がついたものを検討しています。","voiceIndex":100,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問・要望","question":"安心いたしましたので、ぜひ進めていただきたいというふうに思います。今後のパンデミックに備えて、健康危機管理体制の構築に加えて、社会システム全体を捉えながら、区民への被害の最小化を図ってほしいと考えますが、コロナ失業により緊急小口資金や総合支援基金の返済に追われている低所得者層などの所得格差とウェルビーイング格差の現状と、また、今後の対策について区の見解をお伺いいたします。","respondent":"豊嶋生活福祉課長","answer":"私からは、生活に困っている方の現状についてご説明させていただきたいと思います。現在、そうした方は、暮らし・しごと応援センターで様々なご相談をお受けしています。その方法は、訪問ないし電話等々様々です。","voiceIndex":103,"id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"そうした困っている方々のご相談に乗っていただきながら、そうした内容も健康の支援だけではなくて、様々なコロナの影響に対して、いろいろ困っている方、特に低所得者層の方などのお話を聞いていただきながら、そこからもまた今後、パンデミックに備えてどうしていくのかということも、しっかりと区として捉えていただきたいというふうに思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-045"},{"speaker":"せお委員","kind":"確認","question":"よろしくお願いします。１３１ページ、１４７ページ、とうきょうすくわくプログラム、１４７ページ、エデュケーションアシスタント配置支援事業補助金を伺います。先ほど、せらく委員からもありまして、園の数は増えているのかなということが確認できたのですけれども、金額は減っています。３点目、こちらは、園とかの職員だけで、準備から実施、報告とかを行っているのでしょうか。","respondent":"中島保育施設運営課長、中谷指導課長","answer":"すくわくプログラムについてのお尋ねをいただきました。最初に、歳出の科目のところです。保育園のところについて、まず説明します。区立幼稚園の二葉幼稚園で行いました、テーマ「ボールを使って」ですけれども、幼児の興味の関心から、様々な大きさや素材、やわらかさのボールに触れたり。実際のところ、今回、結構予算的にも委託とかも使える部分でありましたので、例えば、木育ワークショップでありますとか、移動水族館みたいなもの。","voiceIndex":107,"id":"exchange-046"},{"speaker":"せお委員","kind":"提案","question":"本当にこの激動の時代には大切だと思っているので、今回も提案するのですけれども、１４７ページのとうきょうすくわくプログラムが、保幼小連携推進事業となっているのです。続けます。ごめんなさい、あと１点、計画的に実行することが大切ということで、この探求活動、探求学習を取り入れていくのであれば、しっかり計画を今後立てていただきたいなと思うのですが、そこら辺の見解をお聞かせください。","respondent":"中谷指導課長","answer":"先ほどご紹介したのは二葉幼稚園なのですけれども、こちらは大学と連携をしまして、専門的なご指導をいただきながら継続的に行う事業となりました。","voiceIndex":111,"id":"exchange-047"},{"speaker":"せお委員","kind":"質問・要望","question":"本当に探究活動、学習のところを幼少期から進めていくと決まったわけであれば、やはり切れ目のない継続性のある計画的な支援を考えていただきたいと要望いたします。時間がなくなってしまったので、エデュケーションアシスタントについては、どこかの款で触れします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。１５５ページ、地所賃貸料、１７５ページ、公園内自動販売機設置運営事業収入、５６ページ、特別区財政調整交付金、１４７ページ、公立学校給食費負担軽減事業補助金について伺いたいと思います。","respondent":"佐藤経理課長","answer":"自動販売機の各施設における設置にかかりまして、行政財産の貸し付けでその部分について貸し付けているというところでございまして、こちらにつきましては、年に１回、各施設ですので、各所管する課の所管ではあるのですけれども、手続上。","voiceIndex":117,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"全体の比率というか、平米と歩合制というか、手数料とか、その辺も伺おうかと思ったのですが、区有施設については平米でやっていて、公園については都市公園法に基づいて、一応、事項別で見ても利益配分が３５％ということで、通常より少し高めで、それだけ売上げがあるのだろうなというところでありますけれども、それで来年度については１,０８５万円ぐらいを見込んでいるというところがあると思います。","respondent":"佐藤経理課長、川崎土木管理課長","answer":"区有施設につきましては、行政財産の貸し付けで設置しているところが３９台、目的外使用で設置しているところは６９台になっております。こちらのほうの災害対応ベンダーにつきましては、許可している台数は３７台なのですが、このうち３４台になります。行政財産の貸し付けの部分については、災害対応をする自販機を条件にしておりますので、対応しております。","voiceIndex":119,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"実際、災害時、鍵を開けてというふうになると思うのですが、そのフローがきちんとできているのかどうかというところ、実際に発災時、直近であれば、昨年でしょうか、災害時に自動販売機を壊してしまってというようなことがあってということも報道ベースでありましたけれども、それがしっかりと協定に基づいた災害時に活用できるかどうかというようなところも含めて教えていただきたいのと、あとは。","respondent":"佐藤経理課長、川崎土木管理課長、大友公園課長","answer":"目的外使用許可をしております主に福祉団体のところですけれども、こちらは先ほど申し上げたとおりで。公園内に設置した飲料自販機の福祉団体のところですけれども、こちらは基本協定を結んでおりまして、その中で、原則、新規設置。公園利用者の声や災害時にいただいた声、また、区民飲料の確保の視点も踏まえ、引き続き検討してまいりたいと考えているところです。","voiceIndex":123,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"もう１つの質問については、これは給食費に関連してなのですが、来年度については、財調の中で、学校給食費保護者負担軽減事業費が新規算定になったり、あとは国のほうで２０２６年度から小学生の部分についての国負担という話も出てきている中で、そうすると、東京都が示す補助金額ベースで単純に計算すると、小学校の場合は１０億７,２７９万６,０００円ぐらいになるだろうというところでは、例えば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"よろしくお願いします。本日、私からは、１３５ページ、出産・子育て応援事業補助金と子供・長寿・居場所包括補助金、１４７ページ、学校給食費負担軽減事業補助金についてお聞きします。先に、学校給食費負担軽減事業補助金から、今年度の有機給食についてお聞きします。こちらの資料を提示します。参加する枠組みとしては、こちらのみどりの食料システム戦略でお間違いはありませんでしょうか。","respondent":"柏木学務課長","answer":"昨日答弁させていただきました農林水産省の取組につきましては、先ほど委員お示しのみどりの食料システム戦略で間違いございません。","voiceIndex":129,"id":"exchange-053"},{"speaker":"おぎの委員","kind":"質問","question":"品川区立の小学校が約１万８,０００食、中学校が約５,５００食、こちらの安定的な食材の確保として、有機野菜だけでなく、特別栽培農産物、こちらも使用するとのことですが、どちらから仕入れるのかお聞きします。有機給食については、量と質を担保する目的ではないとのご答弁でしたが、成長期、食べ盛りの小中学生にしっかりと量も担保されるのかお聞きします。","respondent":"柏木学務課長","answer":"その前提として、現在の地元の既存の事業者に対しては、予算案の議決をいただきましたら、直ちに丁寧な説明や意見交換を行い、市場の動向や現実の実態に耳を傾けながら、円滑かつ持続可能な供給が図れる方策を検討してまいります。","voiceIndex":131,"id":"exchange-054"},{"speaker":"おぎの委員","kind":"質問・要望","question":"あるお母さんから、最近の子どもは外食などで濃い味付けに慣れてしまっているからか、せっかく昆布で出汁をとっても「味が薄い、まずい」と言うとおっしゃっている方がいまして、アンケートにあった「おいしい給食が食べたい」の「おいしい」の部分が、食材なのか、味付けなのか、お肉をたくさん食べたいという希望なのか、または、１人で無言で食べるのか。","respondent":"柏木学務課長","answer":"おいしい給食ということで、「おいしい」というのは人それぞれの部分がありますので、統一的にこれにすればという部分はございませんけれども、日々つくって、また残される量とかもありますので、そういう部分も見ながら、給食についてレベルアップしていければと、また。","voiceIndex":133,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"意見","question":"支援として少し時期がかぶるといいますか、似た感じの事業もあるなといった印象です。出産や子育ての時期に合わせて、頼れる選択肢がたくさんあるというのはいいのかもしれませんが、昨日の議論でもあったように、すくすく赤ちゃん訪問も、見守りおむつ定期便も、それぞれ毎回違う人がやってくるというと、しっかり伴走しようと……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":140,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問","question":"私からは、９７ページの子どもの居場所運営費、１２９ページ、東京ユースヘルスケア推進事業、４３８ページ、債務負担行為について伺いたいと思います。最初に、子どもの居場所運営費についてです。居場所についても、今、モデル事業として３校を調整中ということで理解してよろしいでしょうか。","respondent":"藤村子ども育成課長","answer":"居場所の試行についても３校ということで結構です。","voiceIndex":142,"id":"exchange-057"},{"speaker":"吉田委員","kind":"質問","question":"それで、開始が１学期からということですので、もう３月で、４月から事業開始、モデルだとしてもそこで開始と思うのですけれども、最初のモデルとして調整中のところとの契約はもう進んでいるということなのでしょうか。ということは、学校と契約するのではなくて、あくまで区と事業者が契約するという理解でよろしいでしょうか。それについて伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"委託の契約というところですけれども、こちらについては、契約に向けて準備を進めているというところですので、まだ対象がどこになるかというよりは、どういった仕様にしていくかというところを検討している内容になっております。","voiceIndex":144,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"区と事業者との契約ということで、そうすると、事業の責任主体といいますか、それは、例えば、現場での責任がありますよね。そこは、もしかすると契約の中で、どこが責任を負うということが決まっていくのかと思うのですけれども、やはり現場での責任を誰が負うかということは決めておく必要があると思うのですけれども、その辺の検討はどうなっていますでしょうか。","respondent":"藤村子ども育成課長","answer":"事業を検討するに当たって、学校側ともお話ししする中で、やはり責任の所在ですとか、そういったところは議論の俎上に上がったところです。こちらの一義的な責任は子ども育成課という形で考えて事業展開してまいろうと考えております。","voiceIndex":146,"id":"exchange-059"},{"speaker":"吉田委員","kind":"質問","question":"子ども育成課が契約主体ということであれば、当然、子ども育成課が最終的な責任は負うということは分かるのですけれども、毎日の現場の責任者は、どういう形になるのでしょうか。やはりそこである程度の責任を負える立場の人がいないと、受託した事業者としても少し不安が残るかなと思うのですけれども、その辺についていかがでしょうか。","respondent":"藤村子ども育成課長","answer":"現場は委託の会社の職員がおりまして、当初の何かトラブルがあったときの対応は、そこの事業者で行っていただく形になりますが、例えば、現場で対応し切れない問題に関しましては、連絡手段をこちらのほうで確保しまして、委託の職員から本課の職員に連絡していただいて。","voiceIndex":148,"id":"exchange-060"},{"speaker":"吉田委員","kind":"確認","question":"それで、学校としては、よく把握できていなくてということで少し混乱が起きているので、この朝の居場所現場ではなくて、学校現場の声はどのように確認されているのか。その内容は、今後、締結される契約の中にきちんと反映されているのか、その辺についても確認させてください。","respondent":"藤村子ども育成課長","answer":"学校の声とか、合意がとれているかというところですけれども、先ほども答弁させていただいたのですけれども、学校のほうには、校長先生全体が参加する会で１回説明させていただいています。","voiceIndex":150,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問","question":"そういうＰＴＡの方たちが疑問に思っていることも、では、子ども育成課のほうに問い合わせてくださいというふうにお知らせしていいのでしょうかという質問が１個と、それから、やはり子どもたちが集まっている以上、いろいろはしゃいだり、ふざけたりして、けがとかもあると思うのですけれども、そういうときの対応はどうするのでしょうか。","respondent":"藤村子ども育成課長","answer":"子どものけがへの対応ですが、養護教諭がいない時間帯というお話ですけれども、すまいるスクール運営においても、既に養護教諭の方がいない時間帯のけがへの対応というところで、マニュアル等を作ってしっかり対応しておりますので、先ほど。","voiceIndex":152,"id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"大分私の中で整理されてきたかなと思います。これについては、これから事業が始まって、また点検していかなければいけないと思うのですけれども、もう４月に始まる事業で、契約の締結がまだというのは、少し遅いような、私の感覚では遅いような気がするのですけれども、その点について、しっかり事業の開始に間に合った契約になるということでよろしいですねと、最後、確認させてください。","respondent":"藤村子ども育成課長","answer":"１点、委託の契約が間に合うかというところですが、４月に始まるのではなくて、こちらは１学期の早期の時期にという形なので、今の検討している段階のスタートの期日に間に合うように契約は結んでまいりたいと考えていますので、そちらについては問題ないかと考えております。","voiceIndex":154,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごめんなさい。これはもう単純な質問で、新庁舎関連の事業の債務負担行為が、４年間だったか、非常に大きな額になっていて、緊張してきちんと債務負担行為についても、私たちも責任を持って議決しなければいけないなと思うのですけれども、少し大きな金額を今決めてしまっていいのかなということが、ごめんなさい、今頃になってこのようなことを聞いてなのですけれども、伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"それとまた、国と都からも、今回この建物は区分所有建物ですので、それら相当分の負担額ということを見込みまして、今回の債務負担行為を設定したところです。","voiceIndex":156,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりましたと言っていいのかどうか少し自信がないのですけれども、でも、これは１つ、私たちがずっと求めてきたことが実現したからなのですけれども、この予算書を一般の区民の方が予算特別委員会の前に自由にご覧になれるようになったのですよね。","respondent":"小林新庁舎建設担当課長","answer":"どういったご説明というところかと思うのですが、先ほども申し上げましたとおり、総額として、今回、７００億円余というところがまず大きな枠としています。","voiceIndex":158,"id":"exchange-065"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。次に、１２９ページの東京ユースヘルスケア推進事業について伺います。ただ、具体的な事業というと、今のところ、相談できる窓口の設置ということと、月に１回対面相談会ということなのでしょうか。やはりぜひ居場所とか、そういう事業があったらいいなと思うのですけれども、その点についてはいかがでしょうか。","respondent":"柴田子ども施策連携担当課長","answer":"ただいまご質問いただきました件についてお答えします。相談窓口の設置、それから対面相談ということで、現在の実施状況としましては、チャット相談を週に５日間、また、対面相談は月に１回、児童センターで実施をしています。","voiceIndex":160,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、今、３５０人が、多いのか、少ないのか分からないのですけれども、もっともっとこういう場を求めている人はいらっしゃるのかなと思うのですけれども、今後の広げ方とか、それから、事業もぜひ広げていっていただきたいのですけれども、そういう方たちのお声を直接聞くような、今後の方向性を考える上での仕組みづくりとか、そういうものがあったら教えてください。","respondent":"柴田子ども施策連携担当課長","answer":"それ以外に関しましても、月に１回実施している対面相談会、そちらも今、児童センターはキャラバンで回っているのですけれども、定期的に同じ場所でやったりとか、そういったことも工夫しながら展開をしていきたいと考えています。","voiceIndex":162,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、５０ページから始まる歳入全般における増収について、１６１ページ、奨学金貸付金返還金について、あと、ページがないのですけれども、訪問介護事業所への支援を求めて質問をします。それぞれこの増収になった理由を伺います。区民税については、午前中の質疑でご説明がありましたけれども、３０代から５０代の方が増えているということで、なぜこの世代が増えているのか伺います。","respondent":"吉野税務課長、加島財政課長","answer":"逆に、例えば、課税標準額５００万円以下の方は、逆に下がっているような状況であります。財政調整交付金ですけれども、こちらにつきましては、調整税の伸びと、それから配分割合の変更が５５.１％から５６％に変更になったことによるものです。","voiceIndex":166,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"消費税のところでは、結局、今回は１２か月分が入っているということでよろしいでしょうか。","respondent":"加島財政課長","answer":"説明が足りなくて申し訳ございません。令和６年１２月分の１か月分と、令和７年１月から１１月まで、合わせて１２か月分が地方消費税交付金、こちらの予算額です。","voiceIndex":169,"id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"今いろいろご説明があった中で、やはり今年度、これだけ１２２億円も増収をしているということで、ぜひこの財政力を区民に還元することを求めたいと思います。この消費税の減税も、物価高対策としては、ぜひ国に求めていただきたいと、これは要望しておきたいと思います。区民への還元について、その１つとして、高校生への奨学金貸付金の返済免除を求めたいと思います。","respondent":"飛田子育て応援課長","answer":"高校生の旧奨学金制度ですが、現在、返済をしている方は、令和７年１月現在で１７１名となっております。返還金額は、全体で約３,０００万円となっております。","voiceIndex":171,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"来年度の予算には、大学生の給付型奨学金事業が盛り込まれてよかったと思います。先ほども少し柔軟に対応しているということですが、その柔軟な対応に加えて、ぜひこの奨学金貸付金の返済、これを一部または全額免除をしていただきたいと思いますが、いかがでしょうか。以前に求めた際に、区は他区を注視していきたいということで言っておりましたけれども、その注視状況がどうなったか伺います。","respondent":"飛田子育て応援課長","answer":"今回、新しい奨学金となり、応援資金ということで返済免除となっております。様々な事情がありながらも、こつこつ返済をなされている方がいらっしゃいます。この１年で返済が終わった方も５０名以上いらっしゃるという現状です。","voiceIndex":173,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"他区の状況を注視しているということで、以前、答弁がありましたけれども、今の状況をお伺いします。","respondent":"飛田子育て応援課長","answer":"今のところ、他区のところでも、同じように返済は、こつこつと返している方がいるということで、品川区と同じような状況であるということを認識しております。","voiceIndex":175,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、一番長い人では３０年ですか、返済し続けているということですので、やはりそうした社会状況もありながら、返すことが困難になっているという人もいると思いますので、そこは免除をしていっていただきたいと思います。国の支援ではまだ足りないと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-073"},{"speaker":"中塚委員","kind":"提案","question":"６５ページ、区民活動交流施設使用料に関連して、品川歴史館としながわ区民公園屋外プールの、それぞれ子どもの利用料無償化と、プールのロッカーの返却式による無償化を求めて質問したいと思います。子どもの無償化について、昨年の決算特別委員会でも提案いたしましたが、品川歴史館では年間３万３,０００円、区民公園の屋外プールでは５６万円で可能だということです。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"こちら、品川歴史館につきましては、４月２１日にリニューアルをした中でも、金額をそのまま当時と変わらぬ金額でやっているというところで、妥当な金額設定であると考えております。１人の方が複数使用しますとロッカーが不足するということにもなりますので、その点を防止する観点、運営上の都合もあり、最低金額ではありますけれども、１０円をご負担いただいていることになってあります。","voiceIndex":179,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問・要望","question":"それならば、なぜ品川歴史館と区民プールは引き続き有償なのか、これを改めて伺いたいと思います。区長は、社会全体で子どもと子育てを支えると述べております。それならば、なぜ歴史館とプールは、子どもについても受益者負担を求めるのか。子どももお金を払うのか、子どもも自己責任なのか、これが区長の考えなのか伺います。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"区外の小中学生からの徴収といったところにはなりますけれども、そちらは区長の施政方針の中では、誰もが必要としている基礎的な行政サービスの無償化という訴えも、そういうところもありますので、歴史館の拝観につきましては。このような、例えばプール、また、限られた仲間で場所を占有して使用する野球場などの施設においては、やはり受益者負担の考えのもと、使用料を設定させていただいているというところになってあります。","voiceIndex":182,"id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"プールは誰もがではないとおっしゃいますけれども、私は、区長の無償化の説明が本気だったらば、せめて子どもは無償にと述べてきましたが、なぜならば、保育園も、すまいるスクールも、今回、無償化なのです。だったら、なぜプールは誰もがではないからとなるのか、改めて伺いたいと思います。結局、区長が説明する無償化と、歴史館とプールの子どもの有料は何が違うのか。改めて伺います。","respondent":"大森文化観光戦略課長、大友公園課長","answer":"当然、品川歴史館に多くの方に来館していただきたいという思いはございまして、全区民の方に来ていただきたいというふうな思いもありますが、こちらの生活する上というか。誰もが必要とする基礎的なサービス、社会保障については無償化という考えもありますけれども、本件に限りましては、受益者負担のもと、使用料を設定させていただいているところです。","voiceIndex":185,"id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"プールは５６万円で可能です。決算特別委員会では、１人の方が複数使用するとロッカーが不足する、これを防ぐ観点で１０円を負担していただいていると述べましたけれども、では、１０か所借りたら１００円ですから、でも、そのような乱暴な使い方をしている人はいないわけです。これは区長の施政方針に引くまでもなく、区民の利便性の向上と、このような簡単なことをなぜすぐできないのか伺いたいと思います。","respondent":"大友公園課長","answer":"初めに申し上げました答弁と重なるところがありますけれども、予約数とロッカーの数が、現状、一緒となっているところが原因となっています。","voiceIndex":188,"id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"よろしくお願いします。１１９ページ、子ども家庭支援包括補助金の中から児童センター運営費、１３３ページ、とうきょうママパパ応援事業補助金から産後ケア事業について伺ってまいります。は産前産後ケアの拡充に向けて、どのような思いがあったのか伺ってまいりたいと思います。その後、宿泊型、日帰り型と伺ってまいりたいと思いますのでお願いいたします。","respondent":"石橋品川保健センター所長","answer":"それは初産婦でも経産婦でも一緒です。全ての産婦の方が少しでも安心して子育てをしていただけるよう、出産後間もなくから産後とその家族に寄り添った支援をしたいという強い思いのもと、今回の大幅な拡充をさせていただきたいと考えております。","voiceIndex":191,"id":"exchange-078"},{"speaker":"西村委員","kind":"質問","question":"大変思いがあっての上ということは理解しております。宿泊型なのですが、利用日数等が拡充されまして、どのような産後のお母さんたちからの声があって、今回の拡充に至ったのか伺いたいと思います。日帰り型ですけれども、新たに助産師などの専門職による講話ですとか相談が拡充されました。これは各保健センターで行うと伺っております。そこで考えられた新しい施策とすれば、大変すばらしいと考えています。","respondent":"石橋品川保健センター所長","answer":"日帰り型の個別につきましては、従来どおり、産後ケア室、荏原保健センターでの実施になりますが、そちらにつきまして、荏原保健センターが元に戻るというタイミングもありますので、今後、国のガイドライン等にも基づいて、そちらをよく考えながら。","voiceIndex":193,"id":"exchange-079"},{"speaker":"西村委員","kind":"質問","question":"よく分かりました。さらに私が感謝申し上げたいのが、訪問型のほうでして、こちらの乳房ケアと、あと、助産師の仕事について伺ってまいりたいと思いますが、乳房ケアに特化した助産師が訪問する事業だと理解しております。これ以外に区内の助産師たちが活動していらっしゃるお仕事について、改めて伺えればと思います。","respondent":"石橋品川保健センター所長","answer":"助産師の仕事、役割というところについての質問になりますが、今、保健センターでは、妊娠期の面談におきまして、助産師が妊娠期から出産後のプラン、その後の毎日の生活のプランを一緒に考えたりですとか、すくすく赤ちゃん訪問で助産師の指導員が訪問して、お子様の体重測定。","voiceIndex":195,"id":"exchange-080"},{"speaker":"西村委員","kind":"質問","question":"これらの助産師の支援がありまして、今後さらに新しくＭｙ助産師制度が始まるということで、こちらは子ども育成課が担当する理由と、児童センターでも保健センターと連携してすくすく赤ちゃん訪問など産後の支援を展開していただいておりますので、決定までの経緯を伺えればと思います。","respondent":"藤村子ども育成課長","answer":"例えば、昨夏には、きゅりあんのほうで、お笑い芸人のノンスタイルの石田さんを招いて講演会を行いまして、２００人以上、父親だけで集まって大盛況だったのですが、そこでもアンケートの中で、もっと育児に参加したいが方法が分からないという声をいただいたりですとか。","voiceIndex":197,"id":"exchange-081"},{"speaker":"西村委員","kind":"質問・要望","question":"父親だけのイベントというのは大変画期的だったなと思いますし、父親支援を私も要望していきたいのですけれども、事業の発案が大変すばらしいと思っておりまして、ウーマンズビジネスグランプリを受賞した事業をすぐに導入したことは、迅速な判断だったなと考えていますが、既にこれまで区内で活動してきてくださっている助産師たちがいますので、この地域の助産師たちとの築いてきた長年の関係性と。","respondent":"藤村子ども育成課長","answer":"このＭｙ助産師事業の中では、区の事業を知って利用してもらうというところも１つの目的になってくるかと思いますので、保健センター事業のほか、児童センターで行う助産師と連携している事業もありますので、様々なそういった親育ち支援事業のほうにつなげられることで。","voiceIndex":199,"id":"exchange-082"},{"speaker":"西村委員","kind":"意見","question":"オンライン支援の中でさらに支援が必要になった場合の連携、どう下ろしていくのかという連携と、あとはＭｙ助産師制度が、逆にウェアラブル端末で睡眠時間なども把握していけますので、例えばですけれども、この端末の情報をオンラインで訪問する助産師たちと共有できないかとか、方法については、既存の助産師たちの声が最も重要だと思いますので、今後の展開など区のお考えがあればお聞かせください。","respondent":"藤村子ども育成課長","answer":"オンライン支援の中では、リアルで支援が必要だなというような判断がある方には、お医者さんがコメントするというパターンもあるようなのですが、さらに子ども未来部や保健センター一体となって対応したいと考えています。","voiceIndex":201,"id":"exchange-083"},{"speaker":"塚本委員","kind":"質問・要望","question":"この特別栽培農産物については、少し聞き慣れないというか、あまり一般的に認知されていないもので、有機栽培と一般の慣行農業との間に存在するものというような位置づけだと思いますが、この特別栽培農産物とはどういうものなのかということについてご説明いただきたいということが１つと、あとは、給食事業者の方々、給食をつくっている方々は、朝早くから仕込みに働いていらっしゃって、１２時というか。","respondent":"柏木学務課長","answer":"その中では、当然、ふぞろいのものもございましたけれども、そういう部分では、これまでもそういうもので対応できているという部分はあります。改めて、今回、有機農産物等を調達する際には、そういう部分の負担軽減がさらにできるような調達方法等について検討をしてまいります。","voiceIndex":204,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問","question":"決して当たり前に給食が、私なども当たり前に出てくるものだから、そういう裏でどれだけの苦労があったかということを、今回初めて、改めて認識したようなところがありますけれども、そういった方々のいろいろなご懸念を考えると、今後、話をよく聞きながら、１０月からの事業スタートに向けて進めていくですけれども、やはり何が何でも有機だ特別栽培だというようなことでこだわって。","respondent":"伊崎教育長","answer":"本予算案のご議決をいただきましたら、直ちに地元の事業者の方や、関係する皆様に丁寧なご説明や意見交換を行ってご理解をいただき、進めていきたいと考えております。","voiceIndex":206,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、社会資本整備総合交付金の公園・児童遊園整備費についてですけれども、水道と言ったらいいのですか、水が出るというか、飲み水とかが出る水道の設備がない公園が、品川区には幾つかあるかと思います。この数がどれぐらいあるのか分かれば教えていただきたいのと、未設置数、設置する、しないの基準、こういったものはどういうところにあるのか最初にお伺いいたします。","respondent":"大友公園課長","answer":"区で管理する全２７６公園・児童遊園等のうち、水道設備が設置されていない公園数は２０公園となっています。","voiceIndex":208,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問","question":"基本的には設置ということがある中で、２０公園、主に小さな公園ということですかね、雑駁に言うと。これは、今後、設置に向けての考え方は、どういう状況なのでしょうか。課題等があるのであれば、その課題についても教えていただければと思います。","respondent":"大友公園課長","answer":"公園の形状であったり、また、護岸の上であったり、様々な理由があるところなのですけれども、公園の改修時などを機に水道設備の新設ができないかというところを改めて検討してまいりたいと考えています。","voiceIndex":210,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問・要望","question":"この質問をしたのは、ある区民の方から要望がありまして、公園の水やりを区のほうから、所管は少しはっきりしていないのですけれども、花壇への水やりをお願いされたという言い方をしていましたけれども、具体的にどういうやり取りだったか詳しくは聞いていませんが、ただ、そこの公園には水道がないので、その水やりを家からバケツかで運んで、水やりをしたりしている中で、高齢者なのです。","respondent":"山下交通安全担当課長","answer":"この宣言の趣旨は、交通事故の根絶というところがございまして、また、古い「交通戦争」というような言葉も入っておりますが、やはり背景ですとか歴史ですとか、こういったものをここに残すことによって、そういったものを大切にしながら、また。","voiceIndex":212,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"お願いします。私からは、７９ページ、戸籍証明手数料に関連してと、１５６ページのふるさと納税でお願いします。その中で、答弁として課題が多いということは伺っておりますが、一方で、その際に、改正を国に機会を捉えて要望するということもおっしゃられていました。その後の経過はいかがでしょうか。お願いします。","respondent":"築山戸籍住民課長","answer":"令和６年１２月２３日に、同性パートナーの方が事実婚の方と同様の権利が得られるよう、各種社会保障制度等の改定についての検討と、パートナーシップ制度の適用を受けた方の住民票の続柄表記について、当事者の関係を適切に反映した新たな表記の設定と対応という要望について。","voiceIndex":216,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"区としても要望しているということでよろしいですか。","respondent":"築山戸籍住民課長","answer":"区では、ジェンダー平等と性の多様性を尊重し合う社会を実現するための条例を今年度４月に施行しておりますけれども、その条例に基づいて、区としても、同性パートナーも含め、誰もが自分らしく生きられる社会の実現に向けて取り組んでいきたいという思いから。","voiceIndex":218,"id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"一方で、例えば、先行自治体でいえば、栃木市ですとか、神奈川県の葉山町、逗子市で、２３区では１１月から世田谷区、中野区で、国に先駆けて自治体でこういった取組がもう既に始まっておりますけれども、なぜそこまで今たどり着けていないのかというところが非常に疑問なのですけれども、その点をお伺いします。","respondent":"築山戸籍住民課長","answer":"品川区としても、住民票の表記については、当事者に寄り添うため検討をしてきたところだったのですけれども、やはり一番大きかったのは、国のほうから先行自治体に対して、住民票の記録に対しては。","voiceIndex":220,"id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いします。先行自治体に対して、何か不都合が出ているのかとか、問題があるのかということを調査研究等はされていますでしょうか。","respondent":"築山戸籍住民課長","answer":"２３区でいきますと、先行的に続柄を（未届）、事実婚と同様の（未届）と記載している自治体が、中野区と世田谷区がございまして、そこの自治体に対して課題を幾つか聞いているところです。","voiceIndex":222,"id":"exchange-092"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"次、ふるさと納税なのですけれども、いわゆる区の実入りといいますか、もうけと言ってはなんなのですけれども、ざっくりとした計算方法なのですが、例えば１万円の品を仕入れた場合、出演料でも、商品でもいいですけれども、大体３万円、３倍で区としては売り出して、そのうちの５,０００円ぐらいが手数料になって、表示額のうちの５割ぐらいが区のいわゆる売上になるという。","respondent":"吉野税務課長","answer":"ですので、寄附額は、例えば１万円であれば３万円。そこで、あとは経費です。こういった経費は５割ルールとなりまして、半分、１万５,０００円以内に収めるようにというようなルールがあります。","voiceIndex":226,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"提案","question":"確認できました。そこで、また提案なのですけれども、品川区出身で日本を代表するプロ野球選手がいることを皆さんご存じでしょうか。それは石川柊太投手です。知らないですか。ということで、ぜひ石川柊太選手を招いて、シーズンオフに野球教室などを催してはいかがかと思いますけれども、親子野球教室ですね、いかがでしょうか。","respondent":"吉野税務課長","answer":"現在、野球の選手の方がどこに住んでいるのかというところもやはり大きなあれになってくるかなと思いまして、品川区でのものになりますので、例えば、品川区で、そこで活動されている方であればできるかなと。","voiceIndex":228,"id":"exchange-094"},{"speaker":"やなぎさわ委員","kind":"質問","question":"何かしらの形で活動してもらえば大丈夫なのかなと思ったのです。ＮＰＢ、いわゆる皆さんが想像するプロ野球選手は、９００人しか現役選手はいないのですけれども、その中でもトップクラスの選手が品川区出身というのは非常に大きな財産だと思います。サイン会とか、トークショーとかも兼ねて、そういった親子野球教室とか、そのようなものをぜひ進めていきたいと思います。改めていかがでしょうか。","respondent":"吉野税務課長","answer":"今のご提案、検討します。このほかに品川区では返礼品の開発を進めておりますので、よろしくお願いいたします。","voiceIndex":230,"id":"exchange-095"},{"speaker":"松永委員","kind":"提案","question":"６１ページのなぎさ会館について伺いたいと思います。区民斎場なぎさ会館は、平成４年に開館してから約３３年が経過しております。令和６年度事務事業評価シートでは、実績を確認し、利用率は、ここ３年では約３割前後であり、評価はＤ、今後については、完了または廃止という方向で考えていると先ほどの答弁で伺いました。そこで、このなぎさ会館の跡地について提案をします。考えをお知らせください。","respondent":"築山戸籍住民課長","answer":"先ほど委員がおっしゃられたように、施設の特性上、死、別れを連想させる施設ですので、そういったときに用途として人が住んだりとか集まったりという施設の転用は心理面から難しいのではないかですとか、あとは、現在。","voiceIndex":233,"id":"exchange-096"},{"speaker":"松永委員","kind":"提案","question":"ぜひ総合的な観点からも、そうしたところも必要ですが、例えば、なぜドッグランかというと、あそこはやはりペットを飼われている方が多いので、避難場所としても使えるのではないかという提案だったので、ぜひそうしたところも含めてご検討いただければというふうに思います。次に、８３ページの動物死体処理手数料について伺います。来年度予算の１７０頭についてであります。","respondent":"篠田品川区清掃事務所長","answer":"こちらにつきましては、過去の実績に基づいて予算計上しているものでございまして、実績で言いますと、令和５年度が１６２頭、令和４年度が１７３頭、令和３年度が１６１頭ということで、ここ数年は１６０頭から１７０頭程度で推移をしているところから。","voiceIndex":235,"id":"exchange-097"},{"speaker":"松永委員","kind":"質問","question":"この予算の理由については理解いたしました。近年、ペットも家族の一員とされ、きちんとした葬儀を済ませてお寺で火葬され、また、お墓も建てているご家庭が増えていると伺っております。そこでペット葬についてでありますが、各自治体によって異なると思います。こうした取組がある中で、本区においてどういった方法をとられているのでしょうか。伺います。","respondent":"篠田品川区清掃事務所長","answer":"私どもでは、民間の事業者、ペット霊園に委託をいたしまして、各ご家庭からお預かりした動物のご遺体に関しましては、そちらのほうで対応させていただいているところです。","voiceIndex":237,"id":"exchange-098"},{"speaker":"松永委員","kind":"質問","question":"そうした提携をしているところは、１か所のみですでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"私どもで提携しているというか、委託をかけているのは、民間の事業者１社と契約を結んでいるところです。","voiceIndex":239,"id":"exchange-099"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした中で、先ほども述べさせていただきましたが、ペットも家族の一員と思われる方もたくさん増えている状況でございまして、最後の看取りというところも、ぜひ一緒にさせていただきたいということで、ご要望もいただいております。区内には、ペット葬儀、また、火葬、霊園をされているところがありますので、そうしたところについて伺いたいと思います。","respondent":"篠田品川区清掃事務所長","answer":"行政でつける名前ですので、できるだけ目的ですとか趣旨ですとか、明確ではっきりしたもの、伝わりやすいものということが大事なのかなということで、現状の名前だとは思うのですけれども、こういったものも、時代の流れですとか、価値観ですとか、変化することによって。","voiceIndex":241,"id":"exchange-100"},{"speaker":"松永委員","kind":"質問","question":"１４１ページの空き家利活用等区市町村支援事業補助金について伺いたいと思います。区として、この空き家については、空き家専門相談窓口、また、空き家ホットラインを開設して、年に大体２００件から３００件ほどご相談があって、約１００件の空き家が改善されていると伺っておりますけれども、その後どういった形になっているのか伺いたいと思います。","respondent":"川原住宅課長","answer":"２００件以上いただいているところですが、住宅課の職員と連携してホットラインの相談についてもしっかりと取り組んでいるところでございまして、主な調査としては、現地調査をしっかり行っているところです。","voiceIndex":243,"id":"exchange-101"},{"speaker":"松永委員","kind":"質問","question":"この調査というのはとても大変だと思います。例えば、空き家に対しても、いろいろな方がいる。区営住宅にもなかなか当選できないという方もおられますので、もしそういった空き家が、区で借り上げができたら、そうしたところも含めてご検討いただければと思いますが、空き家の活用について、区としては、どのように考えておられるのか教えてください。","respondent":"川原住宅課長","answer":"そのうち今まで特定空家というふうに認定をされていた空き家も、２件、除却、解体、更地という形で、これは利活用というか、区での活用というところでは残念ながらなく、民間への売却という形にいずれもなってしまっているのですが。","voiceIndex":245,"id":"exchange-102"},{"speaker":"松永委員","kind":"質問","question":"ぜひそうした観点を含めてご検討いただければと思います。最後に、１５９ページの国際交流推進基金繰入金のうち、地域住民と外国人の交流について伺います。本区内において、約１万５,０００人の方が住まわれておりまして、品川区に来られる理由として、仕事とか結婚など様々な理由があります。その中で、やはり日本の文化、外国の文化、変わってくると思います。","respondent":"勝亦総務課長","answer":"そういった中で、外国語によるご案内ですとか、あと、やさしい日本語、そういったものを周知・啓発して、外国人の方に生活等のご理解をして地域住民との共生を図っていきたいと考えております。","voiceIndex":247,"id":"exchange-103"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。５２ページ、特別区たばこ税、１０５ページ、空き家等対策事業についてお伺いいたします。最初に、特別区たばこ税に関連しまして、来年度からの民間公衆喫煙所設置、維持に関する助成の拡大について質問をします。","respondent":"河合生活安全担当課長","answer":"委員のご説明のとおり、来年度は民間公衆喫煙所を主軸といたしまして整備を進めてまいります。そして、そこで足りない部分について等は、コンテナ喫煙所等を、そのときに場所の選定等を検討してまいりたいと考えております。","voiceIndex":250,"id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"事業の概要としては、助成率の引き上げ、これは私ども会派のほうからも、１０分の１０という要望もさせていただき、それに伴って、変更後、１０分の１０、補助対象経費の上限拡大をしていただきまして、どうもありがとうあります。それで、次の項目で補助対象経費の拡大があります。","respondent":"河合生活安全担当課長","answer":"既存の喫煙所等で協力いただけるところで１０件という想定でしております。なお、制度が開始になりまして、状況に応じて、申請等が多いようであれば、補正で対応したいというところで財政とも検討しています。","voiceIndex":252,"id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認させていただきました。それで、これは助成率の引き上げ、来年度やっていく、拡大もしていく。１０件程度という見込みにおいて、その目標数値に当たらなかった場合は、来年度中に補正で適地の敷地があれば検討をしていくという考え方でよろしいのか。もう１回、再確認させてください。","respondent":"河合生活安全担当課長","answer":"区が設置するコンテナ喫煙所等につきましては、足りないところを含めて検討いたしまして、そこで足りないところでは、地域の方々のご協力をいただくような形の説明が必要になりますので、そういったことを進めながら検討してまいりたいと考えております。","voiceIndex":254,"id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"補助対象経費の拡大もそうなのですけれども、民間の公衆喫煙所というところでいうと、コンビニとかも、特にファミリーマートは、民間の公衆喫煙所として、区内でも幾つか、私、何か所あるか分からないのですけれども、今後、この１年間、来年度をやるに当たって、４月以降、そういうコンビニ、あとセブン－イレブンとか、ファミリーマートを含めて。","respondent":"河合生活安全担当課長","answer":"したがいまして、品川区につきましても、民間公衆喫煙所の助成を拡大していく方針になった際にも、事前に、例えば某コンビニのエリアマネジャー等にお話をする形で感触をとりまして、他区でやっている助成率のほうに引き上げられれば、やはり進出しやすいといいますか。","voiceIndex":256,"id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これ、先ほど申し上げたように、たばこを吸う人、吸わない人も安全安心という観点からいうと、これは特別区たばこ税、一般財源として取り扱って設置をしているのだけれども、やはりたばこを吸わない人にも、区税、税金で設置されているとか、コンテナでもいいのですけれども、青空の喫煙所でもいいのですけれども、何かそういう取組もあってもいいのかなと私は思っているのですけれども。","respondent":"河合生活安全担当課長","answer":"喫煙所を一般財源で整備しているということの周知に関しましては、やはり喫煙者、たばこ税を支払ってくださっている方々に対することとして必要な部分と、あと、やはり税金で喫煙所を整備するのはおかしいだろうという声も実際にありますので、そういったところを踏まえまして。","voiceIndex":258,"id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ検討していただきたいと思います。その辺については所管が違うと思いますので、その辺の過料について、今、本区では、恐らく都条例に基づいた条例があると思うのですけれども、その辺について、区として、これから要綱をつくったりとか、そういうお考えがあるのかお尋ねをさせていただきたいと思います。","respondent":"若生健康課長","answer":"今後、区として独自に設定する必要があるかどうかですけれども、こちらについては、法と、あとは東京都の条例、こちらで明確に規定されているところから、区のほうで独自に設定するという考えは現在のところございません。","voiceIndex":260,"id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そういうときは、定期的に指導したりとか、近隣の方からの連絡によって指導に行くこともあるかと思うのですけれども、それは定期的にやっておられるものかどうかということを確認させていただきたいと思います。","respondent":"若生健康課長","answer":"飲食店等の禁止されているところについて喫煙させているというような事業者については、現在、通報に基づいてといいますか、いろいろなお問い合わせがあった際に現地を確認したりというところで対応しています。","voiceIndex":262,"id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"先般、いろいろ近隣からの情報提供とか、所有者からの件数が年々多くなっているように思われますけれども、その辺についてお伺いしたいのと、あともう１点が、先ほど、松永委員からも質疑がございましたけれども、空き家専門相談窓口で解決した空き家の内容の中で、建て替え、売却、リフォーム、有効活用を様々されたということは私も認識しておりますが、建て替え、売却、リフォームの中で。","respondent":"川原住宅課長","answer":"２点、ご質問をいただきました。１点目は、所有者および近隣の方からの相談件数についての回答です。","voiceIndex":264,"id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"意見","question":"それで、外部委託で相続人調査がありますけれども、その相続人調査というのは、以前、予算・決算特別委員会でも、私が発言をさせていただいたと思うのですけれども、これ、スパンで１か月とかというような問題で済むような問題ではないですよね。１年、２年かけて調査するというのは大変なご苦労と作業もあると思います。これからの方向性について、最後にお答えをお願いしたいと思います。","respondent":"川原住宅課長","answer":"今後の方向性につきましては、引き続き、相続人調査もしっかりと行いながら、空き家の適正管理を促しながら、また、相続人の方への空き家となるひどい状態になる前の管理の予防というところを発信してまいりたいと思います。","voiceIndex":266,"id":"exchange-112"},{"speaker":"石田（し）委員","kind":"質問","question":"私は、歳入全般で、いわゆる税収増に見る区内経済についてお伺いしていきます。国は、６年連続で税収増、過去最高です。１９８９年、いわゆる法人税収のバブル絶頂期を超えて、３６年ぶりに最高になるのではないかと、今、想定がされています。そこで、まず質問です。品川区では、今どのような税収の推移があったのか、また、どのような要因でそのようになっているのかお知らせください。","respondent":"吉野税務課長","answer":"特別区民税ですけれども、こちらは、先般、ご説明させていただいたとおり、大分課税標準額が、区民の方の底上げといいますか、経済的な部分もありまして、皆さんのそういった課税標準額が上がっております。","voiceIndex":269,"id":"exchange-113"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる国は６年連続最高記録を更新しているのですよね。その辺について区はどうなのですか。","respondent":"吉野税務課長","answer":"品川区も、令和元年度からずっと税収は伸びております。令和４年度から令和５年度に関しましても、２０億円ぐらいずつ増えてきている現状です。","voiceIndex":271,"id":"exchange-114"},{"speaker":"石田（し）委員","kind":"質問","question":"一方で、倒産件数は、２０２２年５月から３３か月連続で前年同月を上回っている。２０２４年度は、このままいけば、１１年ぶりの１万件を超していくのではないかというふうに言われています。つまり、納税者が約６,０００万人ですから、６人に１人が今これを利用して、いわゆる節税、還付、税制優遇制度ということで利用している。物価高で。どのように対策をとっていこうと思っているのか教えてください。","respondent":"加島財政課長","answer":"令和７年度予算案の中では、これからご審議いただく款に入ってまいりますけれども、子育ての負担軽減ですとか、障害者、高齢者の方の無償化や負担軽減も図っているところです。そういったところでサービスを実感していただきたい。","voiceIndex":273,"id":"exchange-115"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"すばらしい答え。その中で、３０年間上がってこなかった給料で、上がってきたのは国民負担率だけですよ。あの世代、私もそうですけれども。政治が起こした世代ですよ。この人たちが１０年後、年金をもらう世代になったときに、とんでもないことになりますよ。今からやらないと、これは耐えられないから、もうぜひやっていただきたいけれども、その自己責任論でいけば、その点はどうですか。教えてください。","respondent":"加島財政課長","answer":"とても厳しい世代でした。１０年後、２０年後を考えたとき、今、若い世代が同じ苦しみを味わってほしくないというふうに思っております。地域貢献して、品川によい社会を築くことによって、まずは区民の方にここに住んでいてよかったと思ってもらいたい。","voiceIndex":275,"id":"exchange-116"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、７９ページ、住民基本台帳証明手数料、１１５ページ、防犯設備整備補助金、１４１ページ、細街路拡幅整備事業、順不同で時間のある限りさせていただきたいと思います。しかし、これまで整備場所によっては、目的が達成されていないと見受けられる。併せて、そもそも拡幅工事をするときに、移設についてはどのように行っているのか、取り扱いや移設の費用などを確認させてください。","respondent":"森建築課長","answer":"２項後退の電柱の残りについてのご質問です。２項後退で道路が広がっても電柱が残ってしまうというような課題があるということは、区といたしましても認識しています。","voiceIndex":278,"id":"exchange-117"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問にまいります。そこで、例えば、国民健康保険はマイナンバーとつながっているので、マイナンバーが活用されていて、転入届をするだけで反映される、そうした個人情報が反映される仕組みができているというふうに国保医療年金課長にも確認しております。いかがでしょうか。","respondent":"築山戸籍住民課長","answer":"マイナンバーを利用した手続の簡素化です。現在、国のほうで様々な検討が進んでおりますので、今後できる手続が増えてくるというふうに考えております。","voiceIndex":282,"id":"exchange-118"},{"speaker":"鈴木委員","kind":"質問・要望","question":"源氏前小学校の父母の方からご要望をいただいたのですけれども、源氏前小学校の改築計画で、プールが屋上にあるのですけれども、屋根がないということで、本当に気候危機の中でこれからつくるのに何とかならないかというご要望なのですけれども、子どもがプールサイドに上がったときには、２～３ｍのひさしがあるけれども、プールの上には屋根がないという状況で、これからさらに猛暑が予想される中で。","respondent":"荒木学校施設担当課長","answer":"こちらのプールの整備の理由といいますか、どういう整備、施設の有無ですが、冒頭申し上げましたとおり、コスト面や維持管理面というところを優先して検討し、決定しています。","voiceIndex":285,"id":"exchange-119"},{"speaker":"鈴木委員","kind":"質問・要望","question":"同時期につくる鈴ケ森小学校も、できたばかりの浜川小学校も、屋根つきのプールになっているのです。」、「水深は６０cmで行っています。もう２３年前につくられたままなのですけれども、こういうものは、品川区としては、考え方としてつくられないのか、また、こういうものをどういう学校の校舎にするのかということの基準みたいなものはどう考えるのか、その点についても伺います。","respondent":"荒木学校施設担当課長","answer":"プール施設の在り方につきましては、プール授業の実施の方法なども含めまして、今後、在り方について検討を進めてまいりたいというふうに考えてあります。３点目の学校改築計画指針です。こちらは、平成の初期の段階につくったです。","voiceIndex":287,"id":"exchange-120"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと、説明会なのですけれども、ＰＴＡの意見をぜひとも聞いてもらいたい、また、説明もしてもらいたいというご要望もいただいているのですけれども、また、地域への説明会とかも含めて、源氏前小学校の改築に対して、そういう説明会の場をぜひつくっていただきたいと思うのですけれども、いかがでしょうか。","respondent":"荒木学校施設担当課長","answer":"説明会の実施状況ですが、令和５年８月に近隣住民を対象とした計画説明会を実施しており、保護者については、令和５年９月に在校生保護者を対象とした保護者説明会、今年に入りまして、７月に、また近隣住民を対象として工事説明会を実施したところです。","voiceIndex":289,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問","question":"私、５９ページの特別養護老人ホーム等管理費負担金に関連して、そして時間がありましたら、１４７ページの公立学校給食費負担軽減事業補助金に関連して有機野菜についてお伺いしたいと思います。特養に関してであります。私は、その場で、もっと現場をしっかり見てほしいという思いも込めて再質問などもさせていただきましたが、今回、この負担金の項目の中に、三徳会が載っております。","respondent":"菅野高齢者福祉課長","answer":"それと反してというか、今まで区が介護人材は足りているというようなお話がございましたが、決してそのような意識はなく、今回も慢性的な人材不足に備えて、今年度から居住支援手当等を支給させていただいているという状況もありますので。","voiceIndex":292,"id":"exchange-122"},{"speaker":"田中委員","kind":"質問","question":"そういうときには、限定的に派遣職員に頼るということが本来のあるべき姿だと思います。それで、もう１つ言うと、そこもお伺いしたいのですけれども、その上段に、ここの評価の視点として、外国人の方の介護人材を積極的に取り入れていますということが、今回、選定理由の評価項目として記載されております。","respondent":"菅野高齢者福祉課長","answer":"最初、ある施設で、少し難色を示したところもあったということなのですが、ある施設で手を挙げて３人の方を採用したところ、とても評判がよかったので、ほかの施設に波及していって、今では１３人の方がいらっしゃるということで。","voiceIndex":294,"id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"外国人労働者を積極的に取り入れることの意味合いも分かりますが、その背景には、やはり介護職員が不足しているという背景もあるので、そこはしっかり改善していただきたいと思います。そういった労働環境のチェックといったことも、私は指定管理の基本方針に基づいて、しっかり福祉部の方には、環境整備、労働環境の確認という視点でも取り組んでいただきたいと思いますが、最後によろしくお願いします。","respondent":"菅野高齢者福祉課長","answer":"労働環境のチェックの部分につきましては、指定管理者制度のモニタリングの中でも労働環境チェックを５年のうちに１回、実施していますので、その中でしっかりと確認はしていきたいと思います。","voiceIndex":296,"id":"exchange-124"},{"speaker":"えのした委員","kind":"質問","question":"私からは、６７ページ、公園運動施設使用料についてお伺いします。私も一区民として、野球場など施設を使用しています。この場をお借りして感謝を申し上げます。そこでお伺いいたします。各公園の野球場、サッカー場、庭球場、フットサル場、多目的広場など、暑さ対策、熱中症対策はどのように取り組まれていますでしょうか、お聞かせください。","respondent":"三井スポーツ推進課長","answer":"屋外の公園運動施設の利用者に対する熱中症対策については、公園運動施設では熱中症の注意喚起のポスターを掲示するとともに、熱中症警戒アラートなどが発令された際には、当日であっても、使用前であれば。","voiceIndex":300,"id":"exchange-125"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。キャンセルの件数などが分かれば、お知らせください。","respondent":"三井スポーツ推進課長","answer":"昨年の数値になりますが、熱中症予防を目的にキャンセルされた方は２２０件となっております。","voiceIndex":302,"id":"exchange-126"},{"speaker":"えのした委員","kind":"意見","question":"２２０件。施設の予約は、区内団体は、抽せん申込みが３か月前、そして空き予約が１か月前など、使用日のかなり前からになるので、天候などの予測が難しく、予約がキャンセルでき、キャンセル料も発生しないのは、使用者にとっては大変ありがたく助かる取組だと評価をいたします。実際の公園では、暑さ対策について、どのような取組がされているのかお聞かせください。","respondent":"大友公園課長","answer":"公園内の熱中症対策ですけれども、公園内のパーゴラによしずを設置して日陰を設けることや、一部の公園ではミストを設置しております。区が管理する全公園に熱中症への注意喚起の看板を設置しまして、注意喚起を行っているところです。","voiceIndex":304,"id":"exchange-127"},{"speaker":"えのした委員","kind":"質問","question":"続きまして、品川区は、令和６年６月に、大塚製薬株式会社と包括連携協定を締結いたしました。ホームページには、大塚製薬株式会社が推進する熱中症対策アンバサダー講座、正確で専門的な知識を持って熱中症対策を学べる講座を、区が、避暑シェルターを開設している施設の職員を含めた約２００人がオンラインで受講予定とありました。こちらは既に実施されたのでしょうか。","respondent":"勝亦総務課長","answer":"大塚製薬と連携協定を締結いたしまして実施しました熱中症対策アンバサダー講座についてです。こちらの講座につきましては、令和６年６月から８月の期間に、オンラインで実施しています。","voiceIndex":306,"id":"exchange-128"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。ホームページを確認したところ、この講座は、自治体、学校、企業等の組織、団体を対象に、開講に取り組まれており、区民の方へ向けた実施は考えておられますでしょうか。こちらは進められていますでしょうか、お聞かせください。","respondent":"勝亦総務課長","answer":"熱中症アンバサダー講座です。実績といたしまして、今年度、１１３人ですけれども、引き続き、広く受講を進めてまいりたいと考えています。地域の方ですとか、そういった方への受講対象につきましては、今後、検討してまいりたいと考えています。","voiceIndex":308,"id":"exchange-129"},{"speaker":"えのした委員","kind":"質問","question":"ウォーターボトルは持ち歩いているけれども、ついつい忘れてしまうこともあり、ペットボトルの水をいただけるのであれば本当に助かると、多くの声を伺いました。避暑シェルターは、高齢者施設が含まれており、誰でも利用できると認識しておりますが、小中学校、児童センター、幼稚園、保育園等、子どもたちの施設、子育て世代についての周知啓発はされていますでしょうか、お聞かせください。","respondent":"勝亦総務課長","answer":"避暑シェルターの周知啓発につきましては、広報に掲載するほか、学校、それから保育園、幼稚園等に、大塚製薬と連携して作成した啓発ポスターを掲出しています。今後、ＳＮＳの活用など、より広く避暑シェルターについて、区民の方にお知らせしていきたいと考えています。","voiceIndex":310,"id":"exchange-130"},{"speaker":"若林委員","kind":"確認","question":"５２ページの特別区たばこ税について、歳入、または来年度の取組を確認します。高橋伸明委員と大分重なると思いますが、私のほうは、また淡々と確認しますので、よろしくお願いいたします。それをベースに、例えば、１１月６日の喫煙状況実態調査では、迷惑性や危険性を否定できない喫煙状況が確認されたと。そこで、来年度に向けて、この対策方針、規制強化、喫煙所整備の考え方の取組を確認します。","respondent":"吉野税務課長、河合生活安全担当課長","answer":"令和６年度の見込みも、こちらは減る見込みでおります。それに見合いまして、実績見合いとしまして、令和７年度も減収の見込みで立てております。規制強化と喫煙所の整備促進というところで進めておりまして、来年度の方針ですが、条例の規制強化が制定されましたら、７月施行予定です。","voiceIndex":313,"id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"それも含めて、３か所について、地域や公衆喫煙所の形態ですか、業態というのでしょうか、そこら辺も見通しがついていれば、お聞かせいただきたいと思います。続いて、この件に関しては、新規設置が３か所、それから維持管理が１０か所の予算が組まれております。この３か所と１０か所の違いを分かりやすくお知らせいただきたいと思います。最後までいきます。規制強化のほうです。","respondent":"河合生活安全担当課長","answer":"公衆喫煙所の新規設置３件、維持管理１０件ですが、新規３件につきましては、現在、現実的に話が進んでおりますところですと、自動販売機等で収益を得ながら無料公衆喫煙所を開設している事業者等と話を進めながら。","voiceIndex":316,"id":"exchange-132"},{"speaker":"若林委員","kind":"確認","question":"最後、これ、令和７年度予算、条例がこれから可決ということなのですが、予算案では、歩行喫煙防止推進経費という、いわゆる防止条例のネーミングになっておりますので、今後の公共の場所での禁止というネーミングのあらわし方、また、区民への周知の考え方をお聞きして、７月から施行ということで、実質、１回、２回、実態調査をしていただいたわけですが、スタートして。","respondent":"河合生活安全担当課長","answer":"成果の確認調査ですが、やはり施行されまして、それだけの効果があるかどうかという、今後の規制強化も検討する上でも、やはり時期を見て、そういったところは検討する必要があると考えております。","voiceIndex":318,"id":"exchange-133"},{"speaker":"西本委員","kind":"確認","question":"満足しておりません。なぜこの動議をかけたかというと、本来は、予算の審議に入る前に、この情報の出し方、やはり区の態度をしっかりと確認をしていかないと、まともな審査ができないと思ったからなのです。私だけではないのです。皆さんが、全員がこの問題について関与している、関係しているので、だから、冒頭に、どうしてこういうことになったのかということを聞く、確認をするということが私の趣旨です。","respondent":"與那嶺戦略広報課長","answer":"西本委員から、プレス発表の前に、今回の予算の内容について報道があったことについてのご質問です。こちらの報道につきましては、メディア、報道各社につきましても、日々、独自の取材や編集などを行っているですので、区として関与するところではございません。","voiceIndex":321,"id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"それはおかしいですよね、その答弁の仕方。読売新聞、区立中学校の制服無償化、ここに書いてあるのが「区幹部は」ということになっています。それで、オンラインＭｙ助産師の話、これは朝日新聞です、「区によると」とあります。それから、毎日新聞では、品川区給付型奨学金創設。部課長の上は誰ですか。それしかいないですから。これ、どう説明するのですか。誰がやったのですか。そこを説明してください。","respondent":"與那嶺戦略広報課長","answer":"先ほどと少し繰り返しになりますが、報道については、メディアの各社において、それぞれ積極的に取材などが行われているものと認識しております。","voiceIndex":323,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"もう答弁になっていません。それで納得しますか。千代田区がどうのこうの、関係ないです。でも、これ、区の関係者や区の幹部から聞いたとなっているではないですか。私は、２０年以上議会活動をしております。この予算の説明の中で説明があって、プレス発表の前に新聞報道になって、これだけの、全社です、全紙です、されたことはないですから。それをどう説明するのですか。説明をきちんとしてください。","respondent":"與那嶺戦略広報課長","answer":"では、どこから情報を得たかというところにつきましては、各報道機関の中で、取材源の秘匿の原則がありますので、そちらについては、区のほうで誰がというところの関知をするものではないと認識しています。","voiceIndex":325,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"本当は、早く終わって、款別審査に入りたかったのですけれども、これ、無理ですね。これ、記者に話を聞けば分かりますよ。誰に聞いたのですかと言えば分かりますよね。ごまかしはやめてください。ごまかしは。だから守っていたではないですか。私らは守りました。これ、大きな問題です。なので、この責任は、やはり副区長、区長があると思いますので、区長、副区長からのお答えをお聞かせください。","respondent":"與那嶺戦略広報課長","answer":"繰り返しのご答弁になり恐縮です。あくまで今回のプレス発表につきましては、各報道機関において、日頃からの積極的な取材の帰結であるというふうに認識しています。","voiceIndex":327,"id":"exchange-137"},{"speaker":"西本委員","kind":"質問","question":"委員長、これで納得いくと思いますか。この答弁で。これ、さすがに議会蔑視ですよ。これから予算の審査をするという段になって、いろいろと勉強しながら準備を進めて、守るべきことをしっかり守って、なのに、行政側のほうから約束を破っているではないですか。リークしますよ。いいですか、皆さん。誰がやったのですか。こういう行動をこれからも続けるのですか。これ、区長、きちんと答えてください。","respondent":"與那嶺戦略広報課長","answer":"そういったところもありますし、先ほども再三申し上げているとおり、記者の方の取材活動もあるですので、こちらについては、品川区特有ということではなく、自治体であったりとか、国政、都政においても起こり得るようなところであるという形で認識しています。","voiceIndex":329,"id":"exchange-138"},{"speaker":"西本委員","kind":"質問","question":"これは、このままでは済まされません。なので、これは議会運営委員会に要請をします。この原因、どうしてこういう経緯になったのかということを議会運営委員会にかけていただきますので、きちんと答えてください。全て答えになっておりません。そして区長、区長からきちんと説明しなければいけないですよ。責任者は区長なのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":331,"id":"exchange-139"},{"speaker":"澤田委員","kind":"質問・要望","question":"本日もどうぞよろしくお願いいたします。１５６ページ、ふるさと納税寄附金、１５７ページ、各種子どもの未来応援事業を時間があれば質問させていただきたいと思います。１５６ページ、ふるさと納税寄附金について伺います。ふるさと納税寄附金の一般分を１億円と計上されていますが、金額の理由を教えてください。","respondent":"吉野税務課長","answer":"ふるさと納税の返礼品なのですけれども、こちらは、返礼品と体験型を含めたものの予算になります。品川区には、まだ潜在的な魅力がたくさんありますので、こちらのものを返礼品として掘り起こしをしていきたいと考えております。","voiceIndex":334,"id":"exchange-140"},{"speaker":"澤田委員","kind":"質問・要望","question":"なぜ１億円と計上されているかよく分かりました。昨日来、ふるさと納税による減収が５０.９億円に上っていることが区の課題として上がっています。そこで、会派として、令和７年度の主な要望を３点させていただきました。２点目は、国に対し、特別区への支援制度を要望すること。３点目は、体験型と同様に、返礼品の企画開発の推進、地域貢献の寄附型の推進、これらを要望してまいりました。そこで伺います。","respondent":"吉野税務課長","answer":"現地型決済なのですけれども、これは今年度も実は実施したのですけれども、まだ伸びが少し悪かったものですから、こちらはもう少し力を入れまして、拡充を図っていきたいと考えています。それから、団体応援寄附金、こちらも実施したいと考えています。","voiceIndex":336,"id":"exchange-141"},{"speaker":"澤田委員","kind":"質問・要望","question":"そこでお伺いいたします。例えば、議会として、また例えば私として、どのようなことができるとお考えでしょうか。なぜこのようなことをお伺いしたかといいますと、区民の方に、自分たちは何をすればいいのか、何ができるのかと地域の方などに聞かれた際に、私たち議員は、それに対して答える立ち位置にいるのですけれども、その問いに対して、どう返答することができるのか。","respondent":"吉野税務課長","answer":"先ほど少しお伝えしたのですけれども、企業とか、個人事業主の方から、横のつながりが少しずつできつつあるのです。ですので、やはり情報提供といいますか、いろいろといただけると、大変助かります。","voiceIndex":338,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"１７４ページの諸収入、雑入、１６ページの特別区債の都市計画交付金、または１９３ページ、総務管理費、先に１７４ページのほうで、諸収入、雑入で、健康センターの利用料収入還元金、これが７３６万円余と予算書に掲載されました。１６ページの区債のほうです。今年度事業費３億３,０００万円の工事は、都市計画決定による都市計画事業として実施するものと認識しています。この理由についてお伺いします。","respondent":"加島財政課長","answer":"私から、都市計画交付金についてですけれども、現在の交付要綱上、素直に交付対象であると判断できる事例ではないとの見解を都側から示されております。そのため、東京都のほうに事業の概要について情報共有を行いまして、現在、具体的な相談を行っているところです。","voiceIndex":342,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、区の主張と、東京都の主張を、簡潔で結構ですので教えていただきたいと思います。都市計画交付金、これ、全体が３３億円なのです。令和７年度は３億３,０００万円ですけれども、そうすると、交付される見込みがどのぐらいあるかということです。何があってもというのは、言い方があれですけれども、全額認めてもらうべきだと思いますけれども、その辺りはいかがでしょうか。","respondent":"加島財政課長","answer":"現段階におきましては、まだ相談の初期段階ですけれども、過去、令和４年度には広町二丁目都市計画事業のほうで都市計画交付金を受けているという実績もありますので、区側の主張を粘り強く都へ届けながら、都市計画交付金の獲得に向けて調整を進めてまいりたいと考えております。","voiceIndex":344,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、粘り強くということを伺いました。３３億円にかかることですから、ぜひ頑張れというのはあれですけれども、きちんと説明して、都の解釈を区の解釈に合わせていただくということが必要だと思います。次には、特別区債４１億５,０００万円についてお伺いします。起債の種類と、事業費に対する充当率はどれぐらいでしょうか。それから、これも関係しますか、利率はどれぐらいなのでしょうか。","respondent":"加島財政課長","answer":"５年後の令和１２年度に満期を迎えますので、元金と利子を一括償還いたします。ただ、その際ですけれども、令和１２年度の償還時に借り換えを行う予定ですけれども、借り換えの際に、減債基金を活用いたしまして、元金の一部の償還に充ててまいります。","voiceIndex":346,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"意見","question":"でも、それは僅か４１億円です。そうすると、９０億円をまた２０年かけて、今と同じパターンで、令和８年度に、例えば９０億円、令和９年度に９０億円、令和１０年度に９０億円、令和１１年度に９０億円、そして、それが全て２０年かかって償還していくという、９０億円という金額は少し置いておいて、考え方がそれで正しいかどうかお願いします。","respondent":"加島財政課長","answer":"令和８年度から１１年後の払いにつきましては、こちらは工事の出来高に応じて、また支払額が変わってまいりますので、こちらの状況を見極めながら、借入額も決定してまいりたいと考えております。もちろん予算編成前にはきちんと見込額をお示ししたいと考えています。","voiceIndex":348,"id":"exchange-146"},{"speaker":"松本委員","kind":"質問","question":"よろしくお願いします。この財政の見通しをどう考えていくのかというのはとても大事な点かと思いまして、一般質問でも、私、区の財政の将来はどうなるのだというふうな質問をさせていただいた。その中で、では、このぐらい足りなくなってくる可能性があるみたいな、この２０年、３０年、あるいは５０年ぐらいの財政のシミュレーションが、今、品川区の中で数字としてお持ちなのかお伺いいたします。","respondent":"加島財政課長","answer":"そのことにつきましては、大変大きな課題認識を持っておりまして、この先が見通しづらい状況、時代におきまして、１０年、２０年後の財政の見通しをにらみながら、今から準備をしていく必要があると考えておりまして、手元のところでは、令和７年度予算案になりますけれども。","voiceIndex":352,"id":"exchange-147"},{"speaker":"松本委員","kind":"質問","question":"理由は建築費の高騰に伴う資金不足が原因というふうな話なのですけれども、では、どうするのかということを考えるに当たって、目黒区も、２０年、３０年先の予測を、追求をやったです。なので、ここは具体的に時間をかけてでも、財政シミュレーション、２０３０年、２０４０年、２０５０年までやったほうがいいと思うのですが、いかがでしょうか。","respondent":"加島財政課長","answer":"委員からご提案がございました１０年、２０年先を見据えての財政シミュレーションというところですけれども、今の時代において福祉サービスの充実を図るとともに、ご提案のあった財政シミュレーションにつきましても、研究して取り組んでまいりたいと、そのように考えております。","voiceIndex":354,"id":"exchange-148"},{"speaker":"松本委員","kind":"質問・要望","question":"これは我々議員も、あるいは区民も、これだけやってほしいなと思うけれども、将来の子どもたちのことを考えたら、それは要望できないよねというふうな形も生まれてくると思います。なので、ぜひともこれは、改めて強く財政シミュレーションをやっていただきたいというふうに要望したいと思います。次にいきたいと思います。庁舎管理費負担金ですけれども、こちらは東京都と国の負担金が計上されています。","respondent":"小林新庁舎建設担当課長","answer":"新庁舎につきましては、実施設計を進めている最中で、間もなくまとまるところです。そこの中で、国と都、それから区の面積按分を算出した上で、現在の按分と比較をしていくことになりますので、今の段階では、どうなるかというところについては、手持ちでは持っておりません。","voiceIndex":356,"id":"exchange-149"},{"speaker":"松本委員","kind":"質問","question":"どんどん建設費は上がっていますので、そこの部分はきちんとした負担をしていただくようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":358,"id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"１６７ページ、区史等有料頒布収入、品川歴史館資料等となっているのですけれども、「等」とは何ですか。それと、１６９ページ、荏原複合施設大規模改修工事負担金なのですけれども、これ、順調に改修していますか。社会福祉法人にいらっしゃって、次長としてやっているそのキャリアを活かしていくと考えていますので、その辺についてお伺いしたいと思います。","respondent":"高梨都市計画課長、三ツ橋荏原保健センター所長","answer":"区史等頒布収入の中に含まれているものですが、例えばという一例になりますけれども、都市計画課のほうから発行している都市計画図であるとか、品川のまちづくりといった冊子等の収入が入ってあります。荏原保健センター、荏原複合施設大規模改修工事です。こちらにつきましては、順調に進んでいるところです。おかげさまで、令和８年５月に荏原保健センターは移転する予定はそのまま変わらず、遅滞なく実施しています。","voiceIndex":360,"id":"exchange-151"},{"speaker":"藤原委員","kind":"質問・要望","question":"荏原保健センター所長、期待していますので、今までのキャリアを発揮していただきたいと思います。だから、その辺の意気込みを、せっかくですから伺いたいというのと、あと、区史等頒布収入、みんな中へ入ってしまいましたけれども、頒布の「等」だけ聞いたのではなくて、いろいろありますよね、歴史館で売っているものとか、区政資料室で売っているものとかあるのです。いかがでしょうか。","respondent":"福地大井保健センター所長、大森文化観光戦略課長、勝亦総務課長","answer":"全ての区民が健康で幸せに暮らせる地域社会の実現を目指し、職員一丸となって、質の高い保健サービスを提供し、地域の健康課題に柔軟に対応することで。そのうちキャッシュレスのパーセンテージは１４.７％ということになってあります。そういった中で、販売の方法、キャッシュレス等の導入につきましては、関係する所管とも相談をしながら、区民の利便性を向上させていきたいと。","voiceIndex":363,"id":"exchange-152"},{"speaker":"藤原委員","kind":"質問","question":"それと、財政課長、今回の予算においての私が考える特徴は、すごく増収になったのは、まず初めに、財調が５５.１％から５６％になったということだと思います。ただ、どういう形でなったかというのは、総括質疑のときに副区長にお伺いしますので、今日は答弁は要らないですけれども、まず特別区財政調整交付金が１点。それと、特別区民税が上がったということ、これは間違いないですよね。上がった。","respondent":"加島財政課長","answer":"委員がおっしゃるとおり、特別区民税、それから特別区財政調整交付金につきましては伸びまして、こちらが歳入を押し上げている１つの要因となっております。","voiceIndex":367,"id":"exchange-153"},{"speaker":"藤原委員","kind":"質問","question":"予算編成に当たってはというところの文章で、区政の全６６９事業を対象に実施した事務事業評価により、予算額の１％の２０億円ということしか書いていないのです。普通だったら、特別区民税を入れたり、財調を入れたりということを施政方針に入れるべきですよね。企画課長。これ、なぜ入れなかったのですか。どうしても納得いかないのです。いや、私は施政方針に入れるべきだと思いますよ。","respondent":"崎村企画課長","answer":"予算の部分の記載として、今お話にあった事務事業評価で１％を満たした、これは令和６年の施政方針のときでもお示しをさせていただきましたけれども、こういった努力を区自体も行った上で。","voiceIndex":369,"id":"exchange-154"},{"speaker":"藤原委員","kind":"質問","question":"あれだけずっと言ってきて、６割の仕事、でも、４割しかないとか、いろいろやって、暮れにまたやったのですよね。多分。品川区なのだから、品川区の人口がどうなりますとか、品川区の出生率がどうなるとか、そういうことを施政方針に書くべきですよね、品川区なのだから。やはり適切な人口動態をこうやって出していかないといけないと思っているのですけれども、なぜこれ、国のことを書いてしまったのですか。","respondent":"崎村企画課長","answer":"今回、新たな社会モデルをお示しするといったところで、あらゆる人々の生活を保障して、将来の不安を取り除く、これはもちろん、品川区政を担っている我々としては、品川区のことを第一に考えていかなければいけませんけれども、区長もおっしゃっていますけれども、社会に対して。","voiceIndex":371,"id":"exchange-155"},{"speaker":"藤原委員","kind":"確認","question":"何か納得したようで納得していないというか、でも、国を品川区から変えるというので、変えていますものね、いろいろ無償化とかで。品川区。変えていますから、笑っていないですよ。分かりました。８ページ、特別区税なのですけれども、税務課長、徴収率は２３区でトップですよね。それの確認をします。","respondent":"吉野税務課長","answer":"令和５年度は、２３区で１位になりました。現在ですけれども、令和６年度を見ますと、前年よりも収納は多くなってあります。まだ順位等は出ていないのですけれども、このまま収納率を伸ばしていきたいと考えております。","voiceIndex":373,"id":"exchange-156"},{"speaker":"藤原委員","kind":"質問・要望","question":"本当に徴収率、それを求めるわけではないですけれども、対面でお客様と会うわけですから大変だと思いますが、職員の方、労ってあげてください。本当に大変だと思いますので、こういう数字が出てくるわけですから、お願いします。たばこ税なのですけれども、来年か再来年、たばこ税が上がるという情報があるのですけれども、その辺、どうつかんでいますか。","respondent":"吉野税務課長","answer":"たばこ税なのですけれども、こちらは、税制大綱が発布されまして、令和８年の４月と１０月の２段階で引き上げは決まっております。","voiceIndex":375,"id":"exchange-157"},{"speaker":"藤原委員","kind":"質問","question":"たばこ税、一般財源にというのはもうよく分かっているのですけれども、私は、たばこを買った方はたばこ税が含まれて買っているわけですから、たばこ税は、全部とは言わないですけれども、やはりたばこを買った方、たばこを吸った方に還元する施策を打ってもらいたいと思っています。私は思っています。そうですよね。これはたばこ税でつくった喫煙所ですとか、書けばみんな納得しますよ。いかがでしょうか。","respondent":"河合生活安全担当課長","answer":"喫煙所の整備につきましては、税収というところもあるのですけれども、環境と課題に即したところでやっていくですので、また、たばこ税でというところは、その必要性については研究してまいりたいと思います。","voiceIndex":377,"id":"exchange-158"},{"speaker":"藤原委員","kind":"質問","question":"生活安全担当課長、今日、これで終わらないですから。終わらないとは時間があるから終わるけれども、次、総務費でまたやりますので、がっつりこれをやるので、大前提で改めて言っておきます。たばこ税は、たばこを吸う方のための施策に使うべきだと私は思っております。今日はこれで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":379,"id":"exchange-159"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、１５４ページの物品売払収入の防災ラジオ売払代金と、あと、１７８ページの議会費から、行政視察について伺いたいと思います。防災行政無線について、聞こえづらい点の改善は何かされてきているのか伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"それに加えまして、現在は、ホームページ、しなメール、ＬＩＮＥ等でも防災行政無線と連携いたしまして、文字情報で確認をできるというような体制をとっているところです。","voiceIndex":381,"id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問","question":"区民の方からは、他区で防災行政無線をたまたま聞いたときに、とてもクリアに聞こえたという声も寄せられておりまして、他区の防災行政無線の仕組みと違いはあるのでしょうか。そういったところの状況を参考にしたりはしているのか。先ほど課長もおっしゃったように、町の状況、ビルの高さとか、そういうところもあると思うのですけれども、そもそもの仕組みの違いはあるのでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"他区との比較ですけれど、具体的に他区とどういった違いがあるのかというところまで詳細を把握はしてございませんが、現在の防災行政無線は、令和４年度以降、デジタル化をいたしまして更新を図っているところです。それに合わせまして、防災ラジオも更新をしています。","voiceIndex":383,"id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その防災ラジオについて伺っていきたいのですけれども、防災ラジオは、現在、区が助成をして、６５歳以上の高齢者は１,０００円、障害者手帳を持っている人に１,０００円で、そして非課税世帯にも１,０００円で販売されていると。その他の方は２,０００円で販売されています。","respondent":"羽鳥防災体制整備担当課長","answer":"金額といたしましては４１５万円。一般世帯、こちらは２,０００円ご負担いただいている分ですが、台数としては５７４台、金額といたしましては１１４万８,０００円、合計いたしまして、４,７２４台、金額といたしましては５２９万８,０００円という状況です。","voiceIndex":385,"id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"確認","question":"それ以外の方は１,０００円です。新宿区は、災害時要援護者に無償貸与ということで、無償の枠がつくられているのです。この台数を見ても、やはり一般よりも高齢者の方々のほうが、１０倍とまではいかないのですけれども、多く購入されているという状況もありますので、やはり必要とされているのではないかなと思いますので、この無償の枠を設けていただけたらと思うのですけれども、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"その結果によりますと、１１４名の方からご回答をいただきましたが、「安い」とご回答いただいた方が４６％、「妥当」とご回答いただいた方が５０％、こちらを合計しますと、９６％の方が「安い」方等々ということでご回答をいただいたところです。","voiceIndex":387,"id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、議会費のほうにいきたいと思います。これまで経年的な行政視察の経費を伺いたいと思いましたけれども、時間もなくなってきていますので、今までも５００万円から６００万円程度の視察経費がかかってきているかと思うのです。ですので、しっかり報告書をつくっておりますし、この報告書を、やはり税金をかけていますので、区議会ホームページに掲載すべきということを求めてきておりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":389,"id":"exchange-164"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総務費補助金、土木費補助金から、防災安全交付金に関連して、飯田市との交流事業について伺ってまいります。予算編成に当たり、その柱となる理念が籠もった施政方針について確認をします。後ほど質問と答弁を求めますので、その前提で、少し所見を述べますので、委員長、少しご容赦ください。これ、言っていませんけれども、財政課長、企画課長、この本はお読みになられましたでしょうか。","respondent":"崎村企画課長、加島財政課長","answer":"昨年の施政方針の中にも書かせていただいたように、区長が井手教授のお話をお聞きしたということを伺いまして、私も井手教授の本を購入しまして、自席の横に置いてあります。私のほうでも書籍を拝読させていただきました。","voiceIndex":391,"id":"exchange-165"},{"speaker":"あくつ委員","kind":"質問","question":"私は、言葉の力を信じています。論より証拠。質問します。森澤区長と井手教授は、昨年の邂逅以来、親交を温め意見交換をされていらっしゃるとお見受けしますが、今回の施政方針および令和７年度予算案、つまり、ベーシックサービスという強力な理念を据えられたウェルビーイング予算２.０について、提唱者である井手教授はどのようにご覧になられたのか伺います。","respondent":"森澤区長","answer":"施政方針、そして、施政方針に示されている令和７年度予算案につきまして、井手教授からは、ご自身のＳＮＳで発信されていましたけれども、施策、財源、社会像が調和しているというふうに評価をいただいております。","voiceIndex":394,"id":"exchange-166"},{"speaker":"あくつ委員","kind":"提案","question":"協定締結後の昨年１２月、森澤区長は、飯田市を訪問され、佐藤市長との懇談や飯田市を視察されたと伺っております。我々公明党は、今から１０年近く前から、飯田市議会公明党と交流連携をしながら、相互の議会質問において、協定締結を含む交流の深化、深まりを求めてまいりましたので、首長同士の早速のトップ交流を大変に頼もしく思っております。質問いたします。その後の検討状況について伺います。","respondent":"勝亦総務課長","answer":"具体的には、区としましては、早川町、山北町、水と緑の交流、それ以外にも、福井県坂井市、それから高知県との連携交流等を行っております。そういった中で、双方で一緒に具体的に、どのように効果的な交流ができるか、一緒に考えていきたいと考えております。","voiceIndex":396,"id":"exchange-167"},{"speaker":"あくつ委員","kind":"提案","question":"水と緑の交流についてのことをお伺いしたのですけれども、なかなか進んでいないのかなという印象を受けましたが、ぜひよろしくお願いします。私ども会派の代表質問において、元旦号の新春対談で、佐藤市長から、疎開保険のご提案があったことを取り上げました。疎開保険について、飯田市と品川区相互の検討状況について教えてください。","respondent":"勝亦総務課長","answer":"どういった形の特産品を送ったら喜ばれるのかですとか、一緒になって、一生懸命、それぞれにメリットのある疎開保険にしていきたいと考えております。","voiceIndex":398,"id":"exchange-168"},{"speaker":"あくつ委員","kind":"提案","question":"一生懸命一緒に考えていくというご答弁をいただきました。例えば、防災課や地域活動課が連携をして、宿泊施設の特別価格によるあっ旋や交流バスツアーなどの企画も考えられますが、いかがでしょうか。このような提案を私どもから単発で議会から申し上げ確認するということも重要だと思います。なかなか進んでいないということも確認する上で。いかがでしょうか。","respondent":"勝亦総務課長","answer":"早川、山北、それから高知、坂井と、それぞれと協定を結んで交流を図ってまいりました。そういった中で、トップ同士の交流、それから議員の方のご支援、そういったものを踏まえながら、双方が一緒に考えて、効果的なものを進めてきたというのが実感です。","voiceIndex":400,"id":"exchange-169"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"有機食材、この２日間、いろいろな委員からも様々聞きました。これ、私も「夢見る給食」、ご存じでしょうか。ですので、やはり議会として、事実関係はしっかりと確認して、第一会派として、責任ある政策提言を行っていきたいと考えております。だからこそ、この導入の経緯とか、導入に係る考え方は、改めてこれは教育長からしっかり発言していただきたいと思いますが、いかがでしょうか。","respondent":"伊崎教育長","answer":"私から、学校給食への有機特別栽培野菜導入に至った背景として、その考え方についてご説明します。","voiceIndex":403,"id":"exchange-170"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"気持ちは分かりました。不を取り除くということが、品川区のスタイルでありますから、やはり供給業者、そしてまた栄養士の皆さんには、改めてしっかりとした話し合い、そして、検討の場、丁寧な対応が絶対に必要ですし、声を聞く、必ず声を聞いていただきたいと思っています。既存の納入業者、栄養士には、当たり前ですけれども、真摯に向き合っていただくことを強く求めますが、ご見解をお聞かせください。","respondent":"伊崎教育長","answer":"もとより市場の動向や現場の実情を踏まえながら、こうした関係する皆様とともに進めていける持続可能な方策を適切かつ柔軟に検討してまいります。","voiceIndex":405,"id":"exchange-171"},{"speaker":"まつざわ委員","kind":"質問","question":"給食の中では財源のお話も出ました。お金が高いとか、そういったいろいろなお話もありましたけれども、この給食費の予算総額、これは１７億円のうち２,８００万円ぐらいですか、約１.６％になると思いますが、この財源は、お話の中だと、一般財源の中から出ると思いますが、どこから捻出する予定なのかお聞かせください。","respondent":"伊崎教育長","answer":"今回の給食費予算についてですが、有機食材の導入とは別に、１食当たりの単価を５０円程度の引き上げを予定し、予算案に計上しております。","voiceIndex":407,"id":"exchange-172"},{"speaker":"まつざわ委員","kind":"提案","question":"寄附があったというお話、大変すばらしいと思いますけれども、結局、一般財源を使わなくても、モニタリングと検証は絶対に必要ですので、ぜひやっていただきたいと。それで、また提案ですけれども、○○○こうやって進めていくよりも、例えば、すみません、言葉を間違えました。例えば、試行期間で少しチャレンジしてみるとかいって、そういった感覚も必要かなと思いますけれども、すみません、時間がなくて。","respondent":"伊崎教育長","answer":"は今回の取組、新規施策ですので、トライアルと捉え、柔軟かつアジャイルに進めていく、こうした形で随時改善を図っていきたいと思います。","voiceIndex":409,"id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7003#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":129337,"voices":411}},{"id":"r07-20250305-10","meetingId":"r07-cm03","date":"2025年3月5日","dateIso":"2025-03-05","committee":"議会運営委員会","time":"午後 ７時３０分～午後 ７時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区議会個人情報の保護に関する条例施行規程の一部改正","agenda":"品川区議会個人情報の保護に関する条例施行規程の一部改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"議長決定ではあるのですが、今日この場で１回目、初めて出されたということなので、決定については次回の議運で質問させていただければと思いますが、いかがでしょうか。","respondent":"大澤区議会事務局長","answer":"施行日を２４日と考えているのですが、いかがでしょうか。","voiceIndex":25,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認ですが、先ほど終わりました予算特別委員会の中で、西本委員の最後、質疑の中で議運に対して意見を言いたいということの表明があったのですが、今の時点では来ていないということなのか、それはどのような形で、いつこちらに諮られる見通しなのかというのがもしあれば教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6977#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":5371,"voices":33}}]);
